/* Story data: original game dialogue; no copied song lyrics. */
window.KROVO_STORY = {"meta":{"title":"КРОВОСТОК — Четверг / Пятница / Выходные / Понедельник / Вторник / Среда","subtitle":"Многоперсонажная чат-новелла. Оригинальная игровая адаптация сюжетов песен.","provenance":["«Голова» — чистая квартира, голова неизвестного мужчины в пакете «Дикси» на кухонном столе; сохраняем отсутствие доказанного объяснения.","«Коромысло» — Андрей убит, безымянный убийца; Валерик извлекает из памяти сведения о тайниках, делёж пополам.","«Шурик» — звонок с Филиппин, старые долги и желание оставить прошлое позади; не обязательно связан с другими происшествиями.","«Летом» — бытовой летний день похитителя и заложник Шомпол в подполе, срок денег до седьмого. Здесь только отдельная предварительная линия через Томазика.","«Патологоанатом» — профессиональное соседство с телесным сюрреализмом; не даём чудесного универсального опознания.","«Подозрение» — сомнения человека, который слишком хочет увидеть общую скрытую схему; его версии могут быть ложными."],"original_inventions":["Серёга как имя героя «Головы»; Марат как имя подозревающего; игрок без фиксированной биографии; новый чат между ними.","Телефонные связи игрока с персонажами, конкретные сообщения, варианты реплик, действия полиции/Томазика/Аллы и последствия пересылок.","Общие события не образуют автоматически один заговор. Межпесенные знакомства и причинные связи — только наша игровая надстройка."],"state":{"head_first":["photo","police","details"],"photo_route":["doctor","valerik","private"],"shurik_mode":["truth","ask","friendly"],"val_mode":["quiet","question","relay"],"killer_mode":["literal","refuse","confront"],"cross_mode":["separate","mention","money"],"rumor_mode":["contained","speculation","leave"],"theory_mode":["challenge","spread","ignore"],"cellar_mode":["careful","identify","leave"],"shurik_end":["warm","past","silent"],"sergey_end":["leave","tomorrow","observe"],"last_choice":["stop","head","split"]},"design":"12 решений, 3 ответа в каждом. Варианты поздних сообщений условно проверяют предыдущие выборы. Игрок не может отмотать чужую жизнь, но меняет распределение сведений, доверие и последствия распространения слухов. Нет таймеров ожидания, свободного ввода и обязательного универсального злодея.","version":"0.3.0","scenes":90,"author":"Игровая адаптация byGagarin","copyright":"Оригинальные игровые диалоги. Полные тексты песен не включены."},"scenes":[{"id":"E01","title":"09:04 — Не к завтраку","chat":"Серёга","core":[{"who":"Серёга","text":"Ты проснулся?","kind":"in"},{"who":"Серёга","text":"У меня дома посторонний.","kind":"in"},{"who":"Серёга","text":"Точнее, часть постороннего. На кухонном столе, в пакете из «Дикси». Мужик какой-то. Лет тридцать.","kind":"in"},{"who":"Серёга","text":"Крови нет. Бардака нет. Дверь закрыта была. Я чайник поставил, а потом уже вспомнил, что надо кому-нибудь написать.","kind":"in"},{"who":"Серёга","text":"Ты же живой? Ответь.","kind":"in"}],"choices":[{"id":"A","title":"Попросить фотографию","echo":"Фотографию покажи.","set":{"head_first":"photo"},"lines":[{"who":"Серёга","text":"Сейчас.","kind":"in"},{"who":"Серёга","text":"[фото: раскрытый пакет, лицо неизвестного мужчины; рядом кружка и хлебница]","kind":"media"},{"who":"Серёга","text":"Лицо отдельно не снимал. У меня к нему претензий нет, зачем мне крупным планом.","kind":"in"}],"note":"Получаем фото пакета, но не опознание."},{"id":"B","title":"Предложить вызвать полицию","echo":"Звони в полицию. Это не тот случай, где надо гадать.","set":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Позвоню. Сначала кофе долью. Не буду же им потом объяснять, почему у меня кружка недопитая.","kind":"in"},{"who":"Серёга","text":"Только ты никуда это не пересылай. Я тебя просто в известность поставил.","kind":"in"}],"note":"Серёга сообщает властям и особенно просит не разносить историю."},{"id":"C","title":"Спросить про обстоятельства","echo":"Ты проверил замок, окна и что было вчера?","set":{"head_first":"details"},"lines":[{"who":"Серёга","text":"Замок закрыт. Окна закрыты. Вчера я дома был, макароны варил. Макароны съел.","kind":"in"},{"who":"Серёга","text":"Сегодня у меня на столе голова. Видимо, меню разнообразится.","kind":"in"}],"note":"Узнаём детали, снимка пока нет."}]},{"id":"E02","title":"09:19 — Кому показывать","chat":"Серёга","core":[{"who":"Серёга","text":"Я сейчас ещё раз посмотрел. Всё на своих местах. Даже холодильник шумит как обычно.","kind":"in"},{"who":"Серёга","text":"Есть вообще человек, который может сказать, что делать с такой хернёй?","kind":"in"}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Из дежурной части сказали не трогать. Великолепный совет. Я и так не собирался с ним обниматься.","kind":"in"}],"note":""},{"when":{"head_first":"photo"},"lines":[{"who":"Серёга","text":"Вот то фото, что прислал, кому показывать собрались?","kind":"in"}],"note":""},{"when":{"head_first":"details"},"lines":[{"who":"Серёга","text":"Если надо — сфотографирую. Только мне не хочется всю жизнь хранить такой снимок в галерее.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Показать патологоанатому","echo":"Есть один врач. Спрошу, может ли он что-нибудь сказать.","set":{"photo_route":"doctor"},"lines":[{"who":"Серёга","text":"Если он попросит остальные части, то у меня остальные части отсутствуют.","kind":"in"},{"who":"Док","kind":"forward","from":"Серёга","text":"Серёга прислал фотографию неизвестного мужчины. Есть что сказать по ней?","media":"head"}],"note":"Док получает данные только о находке; лицо неизвестно."},{"id":"B","title":"Переслать Валерику","echo":"Спрошу Валерика. Он странными задачами занимается.","set":{"photo_route":"valerik"},"lines":[{"who":"Серёга","text":"Только с подписью «не моё». Мне ещё кредит за телевизор закрывать, не хватало уголовного дела.","kind":"in"},{"who":"Валерик","kind":"forward","from":"Серёга","text":"Серёга просил узнать, кто этот мужчина. Фотография из его кухни.","media":"head"}],"note":"Валерик знает, что у Серёги есть голова. Это позже узнаёт убийца."},{"id":"C","title":"Не распространять снимок","echo":"Пока никому. Разберись сам с тем, кто должен приехать.","set":{"photo_route":"private"},"lines":[{"who":"Серёга","text":"Вот. Адекватное мнение. Я тебя за это и ценю.","kind":"in"},{"who":"Серёга","text":"Если завтра в пакете появятся ноги, я напишу. Сейчас меня не отвлекай, я есть собираюсь.","kind":"in"}],"note":"Сведений о голове больше никто не получает автоматически."}]},{"id":"E03","title":"10:06 — С другого берега","chat":"Шурик","core":[{"who":"Шурик","text":"Димон, живой? Это Шура.","kind":"in"},{"who":"Шурик","text":"Тут у меня море. Настоящее. Без льда, без машин на берегу и без дураков с автоматами.","kind":"in"},{"who":"Шурик","text":"Я, короче, остаюсь. Сначала думал — месяца на три, а теперь понял, что мне и триста лет тут нормально.","kind":"in"},{"who":"Шурик","text":"Ты Кольку давно видел? Я его старый номер потерял.","kind":"in"}],"choices":[{"id":"A","title":"Сразу сказать, что ошибся","echo":"Это не Димон. Номер, видимо, перепутал.","set":{"shurik_mode":"truth"},"lines":[{"who":"Шурик","text":"А. Ну, отлично. Значит, я постороннему человеку уже про море рассказал.","kind":"in"},{"who":"Шурик","text":"Кольку если увидишь — скажи, что мы с ним квиты. Он мне не должен. И я ему тоже. Так и передай, без деталей.","kind":"in"},{"who":"Шурик","text":"А ты будь здоров, кто бы ты ни был.","kind":"in"}],"note":"Шурик не узнаёт о других контактах. Его история остаётся отдельной."},{"id":"B","title":"Уточнить, что с Колькой","echo":"Кольку не видел. А чего ты его ищешь?","set":{"shurik_mode":"ask"},"lines":[{"who":"Шурик","text":"Не ищу. Просто решил, что на старости лет хорошо бы закрыть старые разговоры.","kind":"in"},{"who":"Шурик","text":"Было время, мы таких вопросов друг другу задавали, что потом приходилось окна в машине менять.","kind":"in"},{"who":"Шурик","text":"Если ему попадёшься, передай: ничего не должен. Только пусть больше не звонит со старых номеров.","kind":"in"}],"note":"Появляется бытовой контекст девяностых; никаких биткоинов или тайных списков."},{"id":"C","title":"Поддержать разговор","echo":"Море — дело хорошее. Ты там надолго?","set":{"shurik_mode":"friendly"},"lines":[{"who":"Шурик","text":"Судя по всему, навсегда. Тут одна женщина мне сказала, что по утрам надо сначала завтракать, а уже потом решать проблемы.","kind":"in"},{"who":"Шурик","text":"Я эту идею до сорока лет проверял бы — не додумался.","kind":"in"},{"who":"Шурик","text":"Всё, я побежал. Кольку увижу — сам ему скажу про долги. Если вспомню зачем.","kind":"in"}],"note":"Шурик исчезает на время, довольный жизнью, без обязаловки решать сюжет о голове."}]},{"id":"E04","title":"11:38 — Специалисты","chat":"Валерик","core":[{"who":"Валерик","text":"Слушай, если тебе напишут насчёт меня, скажи: я до вечера занят.","kind":"in"},{"who":"Валерик","text":"Не «не беру трубку». Именно занят. Это разные вещи.","kind":"in"},{"who":"Валерик","text":"И не давай никому мой домашний номер.","kind":"in"}],"variants":[{"when":{"photo_route":"doctor"},"lines":[{"who":"Док","text":"Ты мне чью-то голову в личку прислал в одиннадцать утра. Я, конечно, много видел, но хочу напомнить: по фотографии я человека не вскрываю.","kind":"in"},{"who":"Док","text":"Если он не шевелится, это ещё не вся информация, которую мне нужно сообщить. С официальными вопросами — в соответствующие службы.","kind":"in"},{"who":"Док","text":"И да. Скажи хозяину: пакет не превращает предмет в продукт. Я сегодня как раз с такими спорами закончил.","kind":"in"}],"note":"Док отказывает в чудесном опознании."},{"when":{"photo_route":"valerik"},"lines":[{"who":"Валерик","text":"А насчёт снимка: человека не узнаю. Видел сегодня другого покойника. Тоже, знаешь ли, неразговорчивый.","kind":"in"},{"who":"Валерик","text":"И фото больше никому не рассылай. Глупо, когда одну чужую смерть начинают приписывать другой.","kind":"in"}],"note":"Валерик чётко разделяет покойников, но сам факт находки уже известен."},{"when":{"photo_route":"private"},"lines":[{"who":"Валерик","text":"День хороший. Никто ещё не прислал мне ничего лишнего. Даже странно.","kind":"in"}],"note":"Валерик не знает о голове."}],"choices":[{"id":"A","title":"Согласиться и не лезть","echo":"Ладно, если кто спросит — ты занят.","set":{"val_mode":"quiet"},"lines":[{"who":"Валерик","text":"Вот за это спасибо. Нормально сформулированная информация — нынче редкость.","kind":"in"}],"note":"Игрок не вмешивается в дело Коромысла."},{"id":"B","title":"Спросить, что случилось","echo":"Валер, что за срочность?","set":{"val_mode":"question"},"lines":[{"who":"Валерик","text":"Один человек решил, что мёртвый Андрей всё равно должен ему деньги.","kind":"in"},{"who":"Валерик","text":"Технически мысль не самая глупая. Способ реализации — совершенно ебанутый.","kind":"in"},{"who":"Валерик","text":"Я тебе потом напишу, если это будет смешно. Сейчас пока только противно.","kind":"in"}],"note":"Игрок знает об Андрее раньше, но не о личности убийцы."},{"id":"C","title":"Предложить передать сообщение","echo":"Могу передать одному твоему человеку, что ты на месте.","set":{"val_mode":"relay"},"lines":[{"who":"Валерик","text":"Не надо. Я сам знаю, кому и что должен говорить.","kind":"in"},{"who":"Валерик","text":"Ты хороший человек, но твоя привычка пересылать всё подряд однажды кого-нибудь достанет. Не обязательно тебя.","kind":"in"}],"note":"Валерик начинает осторожнее давать информацию игроку."}]},{"id":"E05","title":"12:41 — Андрей не отвечает","chat":"Без имени","core":[{"who":"Без имени","text":"Валерик сказал, ты у него есть в контактах.","kind":"in"},{"who":"Без имени","text":"Телефон заряжен? Не пропадай.","kind":"in"},{"who":"Без имени","text":"Я Андрюху Коромысло убил. В порыве. Ничего героического, просто разозлился.","kind":"in"},{"who":"Без имени","text":"А потом выяснилось, что все места, где у него лежат деньги, он держал в собственной голове.","kind":"in"},{"who":"Без имени","text":"Валерик может это вытащить. Он умный. А я вечно сначала делаю, потом думаю.","kind":"in"},{"who":"Без имени","text":"Если он спросит, говори: я ничего не прячу. Мне нужны мои деньги, а не лекции.","kind":"in"}],"variants":[{"when":{"photo_route":"valerik"},"lines":[{"who":"Без имени","text":"И что там у вас за фотография чужой башки гуляет? Валерик спрашивал, не нашего ли клиента нашли.","kind":"in"},{"who":"Без имени","text":"Это не Андрей. Я Андрея видел с очень близкого расстояния. Уж поверь.","kind":"in"}],"note":"Из-за пересылки фото убийца узнаёт о Сергее, но голова не объявляется Коромыслом."}],"choices":[{"id":"A","title":"Передать сообщение буквально","echo":"Передам Валерику дословно.","set":{"killer_mode":"literal"},"lines":[{"who":"Без имени","text":"Дословно — хорошо. Ты там ничего от себя не добавляй, я и сам умею испортить впечатление.","kind":"in"},{"who":"Валерик","kind":"forward","from":"Без имени","text":"Если он спросит, говори: я ничего не прячу. Мне нужны мои деньги, а не лекции.","media":null}],"note":"Валерик увидит требование без редактирования."},{"id":"B","title":"Отказаться быть посредником","echo":"Я тебя не знаю. И в твоё дело не полезу.","set":{"killer_mode":"refuse"},"lines":[{"who":"Без имени","text":"Правильное решение. Я бы на твоём месте тоже отказался.","kind":"in"},{"who":"Без имени","text":"Валерик всё равно в курсе. Просто сказал тебе, потому что говорить вслух сегодня особенно мерзко.","kind":"in"}],"note":"Дело продолжается без помощи игрока."},{"id":"C","title":"Напомнить, что речь об убийстве","echo":"Ты понимаешь, что написал признание в убийстве незнакомому человеку?","set":{"killer_mode":"confront"},"lines":[{"who":"Без имени","text":"Понимаю.","kind":"in"},{"who":"Без имени","text":"Незнакомые обычно хоть слушают. Знакомые почему-то сразу спрашивают про деньги.","kind":"in"},{"who":"Без имени","text":"Ладно. Зря написал. Удали, если тебе так спокойнее.","kind":"in"}],"note":"Игрок получает прямое признание; доверия больше не становится."}]},{"id":"E06","title":"13:05 — Что знает Валерик","chat":"Валерик","core":[{"who":"Валерик","text":"Мне сейчас один прекрасный человек объяснил, что хочет получить наследство раньше покойника.","kind":"in"},{"who":"Валерик","text":"Не спрашивай, как устроена техника. Тебе не понравится.","kind":"in"},{"who":"Валерик","text":"Мне нужен только список мест. Человеку — деньги. С этим всё ясно.","kind":"in"},{"who":"Валерик","text":"А дальше — как получится.","kind":"in"}],"variants":[{"when":{"killer_mode":"literal"},"lines":[{"who":"Валерик","text":"Ты его слова прислал как есть. Молодец. Теперь хотя бы я знаю, что он не собирается торговаться. Пока.","kind":"in"}],"note":""},{"when":{"killer_mode":"refuse"},"lines":[{"who":"Валерик","text":"Он сказал, ты отказался передавать. Нормально. Я бы тоже отказался. Что с меня возьмёшь, я уже в деле.","kind":"in"}],"note":""},{"when":{"killer_mode":"confront"},"lines":[{"who":"Валерик","text":"Ты спросил его про убийство. Он теперь всем доказывает, что это была ошибка в коммуникации. Дурацкое слово, да.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Оставить историю отдельной","echo":"Разбирайтесь сами. Только чужую голову сюда не приплетайте.","set":{"cross_mode":"separate"},"lines":[{"who":"Валерик","text":"Именно. Люблю, когда события не мешают в одну кашу.","kind":"in"},{"who":"Валерик","text":"У меня сейчас вполне достаточно одного трупа.","kind":"in"}],"note":"Сведения о Сергее не расширяются; история Коромысла живёт самостоятельно."},{"id":"B","title":"Упомянуть Серёгину находку","echo":"Кстати, у знакомого дома на столе неизвестная голова. Ты ничего об этом не слышал?","set":{"cross_mode":"mention"},"lines":[{"who":"Валерик","text":"Слышал только от тебя. Или от твоего друга — если ты уже рассылал снимок.","kind":"in"},{"who":"Валерик","text":"Нет, не надо делать вид, что две смерти автоматически связаны. Это ты не следователь, а человек с телефоном.","kind":"in"},{"who":"Валерик","text":"Но адрес человека мне не отправляй. Ему сейчас точно не нужны мои знакомые.","kind":"in"}],"note":"Валерик знает подробность: голова в квартире. Это создаст побочный риск слуха."},{"id":"C","title":"Спросить о деньгах","echo":"Если список получишь, вы оба будете богаты?","set":{"cross_mode":"money"},"lines":[{"who":"Валерик","text":"Деньги — слово широкое. Они там в виде чисел, которые очень радуют людей, не умеющих считать.","kind":"in"},{"who":"Валерик","text":"Я, в отличие от некоторых, умею. А вот делиться не люблю.","kind":"in"},{"who":"Валерик","text":"Договор уже есть. Половина мне, половина человеку с нервами.","kind":"in"}],"note":"Игрок получает сведения о долях. Это нельзя переносить на Шурика без его собственного участия."}]},{"id":"E07","title":"14:22 — Беспокойство Серёги","chat":"Серёга","core":[{"who":"Серёга","text":"Ты там вообще как?","kind":"in"},{"who":"Серёга","text":"Я вот уборку закончил. Не из-за головы, просто по четвергам у меня уборка.","kind":"in"},{"who":"Серёга","text":"Пакет пока на месте. По нему решения нет.","kind":"in"}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Полиция перезвонила. Приедут, как освободятся. Прелесть. Хорошо, что я не пирог в духовку поставил.","kind":"in"}],"note":""},{"when":{"photo_route":"doctor"},"lines":[{"who":"Серёга","text":"Доктор твой чего? Не узнал? Ну ладно. Меня это не удивляет, у мужика лицо какое-то совершенно незнакомое.","kind":"in"}],"note":""},{"when":{"photo_route":"valerik"},"lines":[{"who":"Серёга","text":"Твой Валера написал мне с незнакомого номера. Спросил, где именно пакет лежит.","kind":"in"},{"who":"Серёга","text":"Я ему ответил: «Там, где и утром». Он почему-то обиделся.","kind":"in"}],"note":""},{"when":{"photo_route":"private"},"lines":[{"who":"Серёга","text":"Знаешь, приятно, что никто из чужих пока не спрашивает, что у меня на завтрак.","kind":"in"}],"note":""},{"when":{"cross_mode":"mention"},"lines":[{"who":"Серёга","text":"Кстати, кто-то спрашивал, в квартире ли это. Ты всем мой адрес рассказываешь?","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Остановить распространение","echo":"Больше никому ничего не пересылай. Я тоже не буду.","set":{"rumor_mode":"contained"},"lines":[{"who":"Серёга","text":"Идёт. Мне вообще не нравится, когда моя кухня превращается в общественное место.","kind":"in"},{"who":"Серёга","text":"Пойду макароны сварю. Вчера нормально получились.","kind":"in"}],"note":"Слух ограничен текущими контактами."},{"id":"B","title":"Спросить разрешение показать ещё одному","echo":"Есть человек, который любит искать совпадения. Можно ему без адреса показать снимок?","set":{"rumor_mode":"speculation"},"lines":[{"who":"Серёга","text":"А мне за это что будет?","kind":"in"},{"who":"Серёга","text":"Хотя ладно, показывай. Только пусть сначала объяснит, зачем ему моя голова. В смысле та.","kind":"in"},{"who":"Марат (версии)","kind":"forward","from":"Серёга","text":"Серёга разрешил показать фотографию. Имя погибшего неизвестно, адрес не передаю.","media":"head"}],"note":"Открывает Марата, автора ложных теорий. Голову начинают обсуждать публичнее."},{"id":"C","title":"Не обсуждать больше голову","echo":"Понял. Скажешь потом, чем кончилось.","set":{"rumor_mode":"leave"},"lines":[{"who":"Серёга","text":"Вот и договорились. Я тоже пока не хочу с ней разговаривать.","kind":"in"},{"who":"Серёга","text":"С ней — это с проблемой, если что. Саму голову я не спрашивал. Не настолько ещё всё плохо.","kind":"in"}],"note":"Серёга действует самостоятельно; игрок теряет часть сведений."}]},{"id":"E08","title":"16:02 — Человек со схемой","chat":"Марат (версии)","core":[{"who":"Марат","text":"Ты же вчера говорил, что люди в случайности верят. Я думал, ты шутишь.","kind":"in"},{"who":"Марат","text":"Я тут вывел одну закономерность. В городе стало слишком много людей, которым надо срочно что-то забыть.","kind":"in"},{"who":"Марат","text":"Старые деньги, новые деньги, старые друзья — у всех всё сходится. Только у меня почему-то не сходится.","kind":"in"}],"variants":[{"when":{"rumor_mode":"speculation"},"lines":[{"who":"Марат","text":"Фотографию получил. Вот смотри: вчера кто-то говорит про тайник, сегодня у кого-то голова. Я бы подумал.","kind":"in"},{"who":"Марат","text":"Правда, людей с головами у нас много. Это немного мешает теории.","kind":"in"}],"note":""},{"when":{"rumor_mode":"contained"},"lines":[{"who":"Марат","text":"Ты даже фотографию не прислал. Отлично. Теперь мне не на что опереться, кроме собственного подозрения.","kind":"in"}],"note":""},{"when":{"rumor_mode":"leave"},"lines":[{"who":"Марат","text":"Ты ничего не рассказываешь. Поэтому на всякий случай скажу: молчание тоже умеет совпадать.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Попросить доказательства","echo":"Назови один факт, а не пять красивых совпадений.","set":{"theory_mode":"challenge"},"lines":[{"who":"Марат","text":"Справедливое замечание.","kind":"in"},{"who":"Марат","text":"Я двадцать лет ловил одну закономерность. И вдруг понял, что она может существовать только в моей голове.","kind":"in"},{"who":"Марат","text":"Пока не знаю, хорошо это или плохо. Наверное, сначала поем.","kind":"in"}],"note":"Марат сам сомневается и перестаёт раздувать связь."},{"id":"B","title":"Разрешить ему распространять версию","echo":"Ладно, спроси у своих, кто слышал про эти случаи.","set":{"theory_mode":"spread"},"lines":[{"who":"Марат","text":"Вот! Уже работаем.","kind":"in"},{"who":"Марат","text":"Сейчас накидаю в чат района. Названий не будет. Только наводящие вопросы.","kind":"in"}],"note":"Сплетня выйдет за пределы знакомых; Серёга потеряет контроль над информацией."},{"id":"C","title":"Не ввязываться","echo":"Ты без меня пока. Я сегодня и так насмотрелся на совпадения.","set":{"theory_mode":"ignore"},"lines":[{"who":"Марат","text":"Ладно. Только если окажется, что всё это разные события, ты мне не забудь сказать.","kind":"in"},{"who":"Марат","text":"Я, честно говоря, очень хочу, чтоб оказались.","kind":"in"}],"note":"Не получает новые версии, но и не распространяет сплетню."}]},{"id":"E09","title":"18:36 — Магазин закрывается","chat":"Томазик","core":[{"who":"Томазик","text":"Ты не занят? У меня мужик с соседней улицы весь день по два раза ходил. Покупал хлеб, молоко, потом опять хлеб.","kind":"in"},{"who":"Томазик","text":"Я спросил, зачем столько. Он говорит: «Кормить надо». Сказал нормально, без шуток.","kind":"in"},{"who":"Томазик","text":"А ещё Алла утром спрашивала, не слышно ли чего у них из подвала.","kind":"in"},{"who":"Томазик","text":"Я магазин держу, мне за сплетни не платят. А ты людей знаешь. Чего там?","kind":"in"}],"choices":[{"id":"A","title":"Попросить Аллу проверить без риска","echo":"Алле скажи, чтобы сама туда не ходила. Если слышит кого-то — пусть зовёт помощь.","set":{"cellar_mode":"careful"},"lines":[{"who":"Томазик","text":"Передам. И правильно, у меня через час закрытие, я чужие подвалы посещать не собираюсь.","kind":"in"},{"who":"Томазик","text":"Но странный он. Смеялся над акцией на пельмени. Никто над ней не смеётся, там реально скидка.","kind":"in"}],"note":"Алла предупреждена, что не надо входить в дом; линия Шомпола остаётся отдельной, но помощь возможна."},{"id":"B","title":"Спросить имя мужчины","echo":"Кто ходил? Имя есть?","set":{"cellar_mode":"identify"},"lines":[{"who":"Томазик","text":"Имени не помню. Он всегда на наличные берёт. А Алла его как-то называла, но я тогда холодильник размораживал.","kind":"in"},{"who":"Томазик","text":"У меня всё равно двадцать минут до закрытия. Если вспомню — напишу.","kind":"in"}],"note":"Игрок получает лишь неполное свидетельство; человек не становится общим злодеем."},{"id":"C","title":"Не вмешиваться в разговоры у магазина","echo":"Не знаю. Если всё тихо, не лезь в чужой дом.","set":{"cellar_mode":"leave"},"lines":[{"who":"Томазик","text":"Согласен. Я лучше ценники поменяю.","kind":"in"},{"who":"Томазик","text":"Только Алла что-то сегодня беспокойная. Ну, её дело.","kind":"in"}],"note":"Томазик никого не предупреждает. События линии «Летом» идут сами."}]},{"id":"E10","title":"21:16 — Последний звонок","chat":"Шурик","core":[{"who":"Шурик","text":"Слушай. Я тут почему-то номер не удалил.","kind":"in"},{"who":"Шурик","text":"У меня на пляже парень из Омска. Двадцать лет с женой ругается, но домой всё равно звонит. Говорит: привычка.","kind":"in"},{"who":"Шурик","text":"Вот и я думаю, что зря раньше по привычке людям жизнь портил.","kind":"in"},{"who":"Шурик","text":"Кольку если встретишь, скажи: он мне больше ничего не должен. Впрочем, и мне он тоже.","kind":"in"},{"who":"Шурик","text":"И тебе, незнакомец, спокойной ночи. Я у себя тут уже позавтракал.","kind":"in"}],"variants":[{"when":{"shurik_mode":"truth"},"lines":[{"who":"Шурик","text":"Забавно, что я всё это вообще не тому человеку рассказываю. Но с Колькой я бы так спокойно не смог.","kind":"in"}],"note":""},{"when":{"shurik_mode":"ask"},"lines":[{"who":"Шурик","text":"Старые долги нельзя считать каждый день. А то вместо солнца опять будут одни цифры.","kind":"in"}],"note":""},{"when":{"shurik_mode":"friendly"},"lines":[{"who":"Шурик","text":"Ты, кстати, хороший собеседник. Не задаёшь лишних вопросов о том, как я туда попал.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Ответить тепло","echo":"И тебе хорошего дня. Береги себя.","set":{"shurik_end":"warm"},"lines":[{"who":"Шурик","text":"Постараюсь. Сегодня, во всяком случае, никого убивать не собираюсь. Для праздника достаточно.","kind":"in"}],"note":"Шурик завершает свою историю добрым бытовым сообщением."},{"id":"B","title":"Спросить о старых делах","echo":"А чего ты всё-таки из России уехал?","set":{"shurik_end":"past"},"lines":[{"who":"Шурик","text":"Долго рассказывать. Неинтересно особенно. Молодой был, дурак был, думал — навсегда таким останусь.","kind":"in"},{"who":"Шурик","text":"А теперь вот бананы ем и боюсь только, что интернет отключится посреди разговора.","kind":"in"}],"note":"Можно раскрыть кусочек биографии, но он не связан с головой и биткоинами."},{"id":"C","title":"Не отвечать","echo":"[Не отвечать]","set":{"shurik_end":"silent"},"lines":[{"who":"Система","text":"Шурик был в сети в 21:19. Больше сообщений нет.","kind":"sys"}],"note":"Отсутствие ответа — допустимый выбор; миру не требуется мгновенная реакция игрока."}]},{"id":"E11","title":"23:48 — Нормальный вечер","chat":"Серёга","core":[{"who":"Серёга","text":"Я тут решил, что пора спать. День странный, но за электричество заплатил. Хоть что-то полезное.","kind":"in"},{"who":"Серёга","text":"Мне вот интересно, ты почему всегда думаешь, что на всё должен найтись ответ?","kind":"in"},{"who":"Серёга","text":"Я с утра несколько раз посмотрел на эту херню и всё ещё не понимаю ничего. Может, и не пойму.","kind":"in"}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Кстати, приехали люди, всё оформили и забрали пакет. В квартире даже просторнее не стало.","kind":"in"}],"note":""},{"when":{"rumor_mode":"contained"},"lines":[{"who":"Серёга","text":"Спасибо, что не превратил мой стол в городской чат. Серьёзно. У меня и без того соседи лишнего знают.","kind":"in"}],"note":""},{"when":{"rumor_mode":"speculation"},"lines":[{"who":"Серёга","text":"Какой-то знакомый твоего знакомого уже спрашивает про магазин «Дикси». Я ему написал: «У нас ещё «Пятёрочка» есть, хотите список?»","kind":"in"}],"note":""},{"when":{"theory_mode":"spread"},"lines":[{"who":"Серёга","text":"Вот теперь в районном чате спрашивают, у кого пропала голова. Восемьдесят человек гадают и ни один не предлагает её поискать.","kind":"in"}],"note":""},{"when":{"cross_mode":"mention"},"lines":[{"who":"Серёга","text":"И запомни: чужим людям не нужно знать, в какой квартире я живу. Даже если люди умные.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Принять, что ответа может не быть","echo":"Да. Не всё надо раскручивать сегодня. Спокойной ночи.","set":{"sergey_end":"leave"},"lines":[{"who":"Серёга","text":"Вот. Нормально поговорили.","kind":"in"},{"who":"Серёга","text":"Если завтра проснусь и на столе будет вторая, я тебе не напишу. Шутка. Наверное.","kind":"in"}],"note":"Не решает загадку, но сохраняет отношения."},{"id":"B","title":"Предложить разобраться завтра","echo":"Давай завтра. По свежей голове лучше соображать.","set":{"sergey_end":"tomorrow"},"lines":[{"who":"Серёга","text":"По свежей — это ты сейчас неудачно выразился.","kind":"in"},{"who":"Серёга","text":"Ладно. Завтра так завтра. Я холодильник только закрою.","kind":"in"}],"note":"Игрок сохраняет возможность продолжить локальную линию."},{"id":"C","title":"Попросить написать, если что-то изменится","echo":"Просто сообщи, если что-то изменится. Без теорий.","set":{"sergey_end":"observe"},"lines":[{"who":"Серёга","text":"Хорошо. Если изменится, напишу.","kind":"in"},{"who":"Серёга","text":"Сам тоже не мешай мне отдыхать. Я с сегодняшнего дня считаю это серьёзной работой.","kind":"in"}],"note":"Пассивное наблюдение вместо расследования."}]},{"id":"E12","title":"05:14 — Разделили","chat":"Валерик","core":[{"who":"Валерик","text":"Уже утро, если ты ещё не спал.","kind":"in"},{"who":"Валерик","text":"Список достали. Техническая часть сработала.","kind":"in"},{"who":"Валерик","text":"Человек, который вчера признался тебе в убийстве, больше не спрашивает про пароли. Он спрашивает, почему у меня такая довольная физиономия.","kind":"in"},{"who":"Валерик","text":"Договорились пополам. Ему хватит. Мне тоже.","kind":"in"},{"who":"Валерик","text":"Андрея, разумеется, это не вернуло. И никогда не было такой задачи.","kind":"in"}],"variants":[{"when":{"cross_mode":"separate"},"lines":[{"who":"Валерик","text":"Про твою другую историю я ничего не знаю. И не хочу знать. По отдельности жизнь хотя бы помещается в календарь.","kind":"in"}],"note":""},{"when":{"cross_mode":"mention"},"lines":[{"who":"Валерик","text":"И ещё: Серёге не писал. Фотографию никому не отправлял. Мне одного мёртвого сегодня достаточно.","kind":"in"}],"note":""},{"when":{"cross_mode":"money"},"lines":[{"who":"Валерик","text":"Вот тебе обещанная арифметика: половина и половина. Никто не стал делать вид, что убитый нам что-то добровольно подарил.","kind":"in"}],"note":""},{"when":{"theory_mode":"spread"},"lines":[{"who":"Валерик","text":"Слышал, в районе уже увязали мою работу с каким-то пакетом. У людей талант устраивать расследование, не выходя из сортира.","kind":"in"}],"note":""},{"when":{"cellar_mode":"careful"},"lines":[{"who":"Томазик","text":"Алле передал. Она сказала, что без посторонних никуда не пойдёт. И что у неё к тому дому давно вопросы.","kind":"in"},{"who":"Система","text":"Неизвестно, помогло ли это Шомполу. Его история ещё не закончилась.","kind":"sys"}],"note":""},{"when":{"cellar_mode":"leave"},"lines":[{"who":"Томазик","text":"Алла больше не заходила. Мужик всё-таки купил ещё хлеб. Я закрыл магазин.","kind":"in"},{"who":"Система","text":"Шомпол остаётся в подполе в пределах известных событий. Его дальнейший исход здесь не показан.","kind":"sys"}],"note":""},{"when":{"cellar_mode":"identify"},"lines":[{"who":"Томазик","text":"Вспомнил только прозвище. Короткое и дурацкое. Скажу, когда снова зайдёт.","kind":"in"},{"who":"Система","text":"Имя похитителя не установлено. История Шомпола не привязана к Андрею Коромысло.","kind":"sys"}],"note":""}],"choices":[{"id":"A","title":"Закончить разговор","echo":"Всё. Пожалуй, хватит на сегодня.","set":{"last_choice":"stop"},"lines":[{"who":"Валерик","text":"Поддерживаю. Я тоже впервые за сутки хочу просто поспать.","kind":"in"}],"note":"Игрок сознательно не ищет общую разгадку."},{"id":"B","title":"Спросить о голове","echo":"А неизвестного в пакете ты так и не знаешь?","set":{"last_choice":"head"},"lines":[{"who":"Валерик","text":"Нет.","kind":"in"},{"who":"Валерик","text":"Иногда неизвестный человек остаётся неизвестным. Это, если честно, гораздо обычнее, чем людям хочется.","kind":"in"}],"note":"Подчёркивает самостоятельность историй."},{"id":"C","title":"Спросить, почему делили именно так","echo":"Почему пополам? Он же сам всё испортил.","set":{"last_choice":"split"},"lines":[{"who":"Валерик","text":"Потому что я не умею убивать, а он не умеет читать память. Люди иногда идеально дополняют друг друга. Отвратительное, конечно, обстоятельство.","kind":"in"}],"note":"Закрывает историю «Коромысло» без оправдания убийства."}]},{"id":"F01","title":"Пятница, 09:18 — Нормальное продолжение","chat":"Серёга","core":[{"who":"Серёга","text":"Пятница наступила. Никакой символики, просто пятница.","kind":"in"},{"who":"Серёга","text":"Чайник сломался. Вчера работал, сегодня кипятит воду с таким видом, будто я ему денег должен.","kind":"in"},{"who":"Серёга","text":"Ты вчера что-нибудь узнал по моей истории? Без версий про международный синдикат, пожалуйста.","kind":"in"}],"choices":[{"id":"A","title":"Ответить, что ясности нет","echo":"Нет. Человека никто надёжно не опознал.","set":{"frank_head":"unknown"},"lines":[{"who":"Серёга","text":"Ну и ладно. Хуже всего, когда начинают уверенно врать.","kind":"in"}],"note":""},{"id":"B","title":"Обсудить публикацию снимка","echo":"Снимок кто-нибудь ещё видел, кроме тех, кому мы отправляли?","set":{"frank_head":"spread"},"lines":[{"who":"Серёга","text":"Не знаю. Я сегодня впервые пожалел, что когда-то научился пользоваться интернетом.","kind":"in"}],"note":""},{"id":"C","title":"Спросить про быт","echo":"А ты сам как? Спал хоть?","set":{"frank_head":"care"},"lines":[{"who":"Серёга","text":"Спал. Очень даже хорошо. Во сне голова не снилась. Мне, кстати, картошка снилась. Нормальная, крупная.","kind":"in"}],"note":""}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Если ты про пакет: его вчера забрали. Бумажку выдали. У меня теперь вместо головы номер дела.","kind":"in"}]},{"when":{"head_first":"photo"},"lines":[{"who":"Серёга","text":"Снимок я удалил из галереи. Пока удалял, телефон спросил: «Создать воспоминание?» Потрясающая техника.","kind":"in"}]},{"when":{"head_first":"details"},"lines":[{"who":"Серёга","text":"Пакет я не разворачивал второй раз. Моё любопытство умерло где-то после завтрака.","kind":"in"}]},{"when":{"theory_mode":"spread"},"lines":[{"who":"Серёга","text":"А ещё мне сосед написал, что я якобы торгую головами. Спасибо людям за рекламу.","kind":"in"}]}]},{"id":"F02","title":"Пятница, 10:03 — У магазина","chat":"Томазик","core":[{"who":"Томазик","text":"Утро, дружище. Ты вчера про мужика спрашивал. Я вспомнил, где видел его машину.","kind":"in"},{"who":"Томазик","text":"У дома с глухими окнами, за остановкой. Он с утра два раза заходил ко мне за хлебом.","kind":"in"},{"who":"Томазик","text":"Алла опять интересовалась, что там у них внизу. Я ей сказал, что магазин справок о подвалах не выдаёт.","kind":"in"}],"choices":[{"id":"A","title":"Передать осторожное предупреждение","echo":"Попроси Аллу не заходить туда одной. Если кто-то просит помощи — пусть зовёт службы.","set":{"alla_signal":"caution"},"lines":[{"who":"Томазик","text":"Передам. И отдельно скажу, что я не консультирую по чужим подвалам даже за деньги.","kind":"in"}],"note":""},{"id":"B","title":"Попросить контакт Аллы","echo":"Можешь дать ей мой номер? Хочу уточнить, что она сама слышала.","set":{"alla_signal":"contact"},"lines":[{"who":"Томазик","text":"Дам. Скажу, что ты не полиция. Не обещаю, что она обрадуется.","kind":"in"}],"note":""},{"id":"C","title":"Не развивать разговор","echo":"Ясно. Лучше не лезть, пока ничего толком не известно.","set":{"alla_signal":"quiet"},"lines":[{"who":"Томазик","text":"Может, и так. Я, во всяком случае, чужую дверь открывать не собираюсь.","kind":"in"}],"note":""}],"variants":[{"when":{"cellar_mode":"careful"},"lines":[{"who":"Томазик","text":"Кстати, Алла вчера спасибо сказала за предупреждение. Не знаю, за что именно, но спасибо.","kind":"in"}]},{"when":{"cellar_mode":"identify"},"lines":[{"who":"Томазик","text":"Я про прозвище вспомнил только одно: его все почему-то называют коротким словом. По имени никто не обращается.","kind":"in"}]},{"when":{"cellar_mode":"leave"},"lines":[{"who":"Томазик","text":"Я вчера никому не звонил. Но Алла утром сама пришла: говорит, шум опять был.","kind":"in"}]}]},{"id":"F03","title":"Пятница, 10:47 — Алла","chat":"Алла","core":[{"who":"Алла","text":"Томазик дал мне твой номер. Я сама попросила. Говорит, ты про дом спрашивал.","kind":"in"},{"who":"Алла","text":"Я вчера там была. Уходила уже поздно. Во дворе вроде никого, а из-под пола кто-то три раза стукнул.","kind":"in"},{"who":"Алла","text":"Не знаю, что это было. Может, трубы. Я не мастер по трубам.","kind":"in"},{"who":"Алла","text":"Ты чего хочешь узнать?","kind":"in"}],"choices":[{"id":"A","title":"Спросить лишь о звуке","echo":"Ты точно слышала три стука? Из дома или с улицы?","set":{"alla_detail":"sound"},"lines":[{"who":"Алла","text":"Из дома. Три раза и потом пауза. Время почти одиннадцать было. Записала, чтобы не забыть.","kind":"in"}],"note":""},{"id":"B","title":"Назвать подозрение прямо","echo":"Есть опасение, что внизу держат человека. Я не уверен.","set":{"alla_detail":"warning"},"lines":[{"who":"Алла","text":"Это уже не про трубы. И хорошо, что сказал «не уверен». От уверенных людей у меня самые большие проблемы.","kind":"in"}],"note":""},{"id":"C","title":"Не втягивать её в риск","echo":"Пока ничего не делай. Просто будь осторожна.","set":{"alla_detail":"gentle"},"lines":[{"who":"Алла","text":"Я и не собиралась туда возвращаться. Мне завтра на работу, а не в кино ужасов.","kind":"in"}],"note":""}],"variants":[{"when":{"alla_signal":"caution"},"lines":[{"who":"Алла","text":"И спасибо, что через Томазика сказал не ходить одной. Удивительно, что кому-то это нужно отдельно объяснять.","kind":"in"}]},{"when":{"alla_signal":"contact"},"lines":[{"who":"Алла","text":"Томазик предупредил, что ты будешь спрашивать. Ладно, расскажу как было.","kind":"in"}]},{"when":{"alla_signal":"quiet"},"lines":[{"who":"Алла","text":"Не знаю зачем пишу. Томазик сказал, что ты вчера хотя бы слушал, не строил версии.","kind":"in"}]}]},{"id":"F04","title":"Пятница, 11:26 — Вторая работа","chat":"Док","core":[{"who":"Док","text":"Между прочим, в нашей профессии крайне удобно, когда люди не требуют узнать судьбу по одному пикселю.","kind":"in"},{"who":"Док","text":"Мне сегодня снова пишут незнакомые люди и спрашивают, что можно узнать по фотографии. Иногда даже самой фотографии не прикладывают.","kind":"in"}],"choices":[{"id":"A","title":"Попросить не распространять","echo":"Можешь просто больше никому это не пересылать?","set":{"doc_reply":"closed"},"lines":[{"who":"Док","text":"Могу. Уже не пересылал. У меня, к счастью, есть куда более скучная работа.","kind":"in"}],"note":""},{"id":"B","title":"Уточнить источник","echo":"Писали разные люди или один и тот же?","set":{"doc_reply":"source"},"lines":[{"who":"Док","text":"Разные номера. Но две подписи совпадают слово в слово. Это говорит о копировании, а не о заговоре.","kind":"in"}],"note":""},{"id":"C","title":"Сменить тему","echo":"Забудь про фото. Скажи лучше, что у тебя с работой.","set":{"doc_reply":"distance"},"lines":[{"who":"Док","text":"Всё нормально. Я работаю, люди умирают, соседи спорят, кто забрал мою доставку. Жизнь идёт.","kind":"in"}],"note":""}],"variants":[{"when":{"photo_route":"private"},"lines":[{"who":"Док","text":"Ты лично мне, кстати, ничего не присылал. Даже приятно. Но слух дошёл и без тебя.","kind":"in"}]},{"when":{"photo_route":"doctor"},"lines":[{"who":"Док","text":"А твой снимок я никому не передавал. Он сам уже давно живёт своей отдельной жизнью.","kind":"in"}]},{"when":{"photo_route":"valerik"},"lines":[{"who":"Док","text":"Ты мне вчера не писал, но кто-то фотографию переслал. Раз уж начали — я не определю личность по такому качеству.","kind":"in"}]}]},{"id":"F05","title":"Пятница, 12:18 — Доля","chat":"Без имени","core":[{"who":"Без имени","text":"Ну что, доброе утро. У Валерика половина. У меня половина.","kind":"in"},{"who":"Без имени","text":"У Андрея, понятно, ничего. Мертвецам с дележом не везёт.","kind":"in"},{"who":"Без имени","text":"Мне всё ещё не нравится, как получилось. Но назад это уже не отмотать.","kind":"in"},{"who":"Без имени","text":"Ты кому-нибудь успел пересказать вчерашнее?","kind":"in"}],"choices":[{"id":"A","title":"Не распространять признание","echo":"Твоё признание осталось в переписке. Я не передавал его по городу.","set":{"killer_reply":"private"},"lines":[{"who":"Без имени","text":"Ладно. Хотя странно тебя за это благодарить. Мы даже не знакомы.","kind":"in"}],"note":""},{"id":"B","title":"Не обещать секретности","echo":"Я не обещал хранить твои признания в тайне.","set":{"killer_reply":"boundaries"},"lines":[{"who":"Без имени","text":"Разумно. Я тоже тебе ничего хорошего не обещал. Просто написал, потому что надо было кому-то написать.","kind":"in"}],"note":""},{"id":"C","title":"Закончить разговор","echo":"Никакого разговора про деньги больше не хочу.","set":{"killer_reply":"block"},"lines":[{"who":"Без имени","text":"Тогда и не будет. Я свою часть уже получил. Продолжения по этому поводу не планирую.","kind":"in"}],"note":""}],"variants":[{"when":{"killer_mode":"refuse"},"lines":[{"who":"Без имени","text":"Ты вчера отказался помогать — помню. Не переживай, без тебя справились.","kind":"in"}]},{"when":{"cross_mode":"mention"},"lines":[{"who":"Без имени","text":"И ещё: чужую голову я не трогал. Мне хватает собственных неприятностей.","kind":"in"}]},{"when":{"theory_mode":"spread"},"lines":[{"who":"Без имени","text":"А тут ещё какие-то идиоты в районном чате решили, что я с пакетом хожу. Какой-то жутко активный следователь без удостоверения.","kind":"in"}]}]},{"id":"F06","title":"Пятница, 13:34 — Что видел Томазик","chat":"Томазик","core":[{"who":"Томазик","text":"Мужик с хлебом опять заходил. Стоял у кассы, сдачу пересчитывал минуту.","kind":"in"},{"who":"Томазик","text":"Я его спросил, почему он вчера так много взял. Говорит: «Чтоб хватило». На что — не уточнял.","kind":"in"},{"who":"Томазик","text":"Алла сейчас у остановки. Смотрит на тот дом и злится. Не похоже на неё.","kind":"in"},{"who":"Томазик","text":"Мне передать ей что-нибудь?","kind":"in"}],"choices":[{"id":"A","title":"Предложить безопасный вызов помощи","echo":"Если она слышала просьбы о помощи, пусть вызывает службы. И сама не входит.","set":{"help_route":"official"},"lines":[{"who":"Томазик","text":"Скажу. Она и сама, кажется, к этому пришла. Я тут за кассу вернусь, а то очередь смотрит как на врага.","kind":"in"}],"note":""},{"id":"B","title":"Не подтверждать догадки","echo":"Передай, что мы не знаем, кто там. Пусть не рискует из-за слухов.","set":{"help_route":"cautious"},"lines":[{"who":"Томазик","text":"Так и передам. Ничего о подвале от себя добавлять не буду.","kind":"in"}],"note":""},{"id":"C","title":"Разрешить ей решать самой","echo":"Пусть сама решит, что делать. Я не видел этого дома.","set":{"help_route":"hands_off"},"lines":[{"who":"Томазик","text":"Ладно. Я и не собирался командовать. Но если кто из них зайдёт за хлебом, я запомню.","kind":"in"}],"note":""}],"variants":[{"when":{"alla_detail":"warning"},"lines":[{"who":"Томазик","text":"Алла сказала, что ты предположил человека внизу. Она не уверена, но теперь относится серьёзнее.","kind":"in"}]},{"when":{"alla_detail":"sound"},"lines":[{"who":"Томазик","text":"Алла показала мне время стука на телефоне. Я в то время холодильник выключал. Прямо как наш компрессор.","kind":"in"}]},{"when":{"alla_detail":"gentle"},"lines":[{"who":"Томазик","text":"Она сказала, что ты не велел ей ничего расследовать. Правильно, она и так устаёт.","kind":"in"}]}]},{"id":"F07","title":"Пятница, 15:09 — С другого света","chat":"Шурик","core":[{"who":"Шурик","text":"Привет ещё раз. Я нашёл Кольку. Не того, о котором говорил, а вообще другого. Номеров у меня, оказывается, двадцать семь одинаковых.","kind":"in"},{"who":"Шурик","text":"Ничего. Вышло даже хорошо. Этот Колька женился. Счастливый, аж противно.","kind":"in"},{"who":"Шурик","text":"Тебя не достал вчера? А то я тогда что-то разговорился.","kind":"in"}],"choices":[{"id":"A","title":"Поддержать разговор","echo":"Всё нормально. Рад, что у тебя там хорошо.","set":{"shura_friday":"warm"},"lines":[{"who":"Шурик","text":"И я рад. Представляешь: двадцать лет мечтаешь, чтобы никто не звонил по делу, а потом сам всем пишешь.","kind":"in"}],"note":""},{"id":"B","title":"Спросить про старые долги","echo":"Ты действительно решил больше никому ничего не предъявлять?","set":{"shura_friday":"debt"},"lines":[{"who":"Шурик","text":"Решил. Сколько можно предъявлять. От этой бухгалтерии даже море хуже видно.","kind":"in"}],"note":""},{"id":"C","title":"Закрыть чат","echo":"Нет проблем. Я занят, Шур.","set":{"shura_friday":"short"},"lines":[{"who":"Шурик","text":"Понял. Бывай. Если ещё позвоню, значит, опять номер перепутал.","kind":"in"}],"note":""}],"variants":[{"when":{"shurik_mode":"truth"},"lines":[{"who":"Шурик","text":"Да, я всё ещё помню, что ты не Димон. Хоть кто-то тут держит в голове факты.","kind":"in"}]},{"when":{"shurik_mode":"friendly"},"lines":[{"who":"Шурик","text":"Ты даже не спрашиваешь, где точно живу. Хороший подход к чужой жизни.","kind":"in"}]}]},{"id":"F08","title":"Пятница, 17:43 — Правильная теория","chat":"Марат (версии)","core":[{"who":"Марат","text":"Слушай, у меня интересное открытие.","kind":"in"},{"who":"Марат","text":"Я вчера написал людям про странные совпадения. В ответ получил пятнадцать историй про пропавшие вещи, три про соседей и одну про сломанный лифт.","kind":"in"},{"who":"Марат","text":"Ни одна из них, кажется, не имеет отношения к твоей.","kind":"in"},{"who":"Марат","text":"Я теперь не могу понять, был ли вообще смысл спрашивать.","kind":"in"}],"choices":[{"id":"A","title":"Признать ограниченность версий","echo":"Вопросы нормальные. Беда начинается, когда догадки выдают за факты.","set":{"mara_reply":"learn"},"lines":[{"who":"Марат","text":"Справедливо. Мне надо научиться останавливаться до той части, где я рисую стрелки на обоях.","kind":"in"}],"note":""},{"id":"B","title":"Попросить убрать слух","echo":"Лучше удали публикацию про голову. Хозяину квартиры от неё неприятности.","set":{"mara_reply":"remove"},"lines":[{"who":"Марат","text":"Удалю. Если кто сохранил — поздно. Но хотя бы сам продолжать не буду.","kind":"in"}],"note":""},{"id":"C","title":"Оставить его с его выводами","echo":"Тебе виднее. Я не собираюсь спорить весь вечер.","set":{"mara_reply":"leave"},"lines":[{"who":"Марат","text":"Ладно. Я и сам устал. Пойду поем. Если вдруг выяснится, что всё вообще не связано, напиши. Это был бы хороший финал.","kind":"in"}],"note":""}],"variants":[{"when":{"theory_mode":"spread"},"lines":[{"who":"Марат","text":"И да, тот вчерашний пост разошёлся. Меня уже трое спросили, где именно всё случилось. Я им адреса не давал.","kind":"in"}]},{"when":{"theory_mode":"challenge"},"lines":[{"who":"Марат","text":"Ты вчера правильно попросил факт. Я так ни одного и не нашёл.","kind":"in"}]},{"when":{"theory_mode":"ignore"},"lines":[{"who":"Марат","text":"Ты вчера меня проигнорировал, но я всё равно пишу. Больше поговорить не с кем.","kind":"in"}]}]},{"id":"F09","title":"Пятница, 20:12 — В подполе","chat":"Алла","core":[{"who":"Алла","text":"Уже вечером хотела выключить телефон, но напишу.","kind":"in"},{"who":"Алла","text":"Там сегодня снова был шум. Я сама не заходила, можешь не ругаться.","kind":"in"},{"who":"Алла","text":"Томазик сказал, что вы уже обсуждали дом. Я не строю догадки. Просто знаю, что слышала.","kind":"in"},{"who":"Алла","text":"И теперь мне надо решать, что делать с этим знанием.","kind":"in"}],"choices":[{"id":"A","title":"Поддержать обращение за помощью","echo":"Если подозреваешь, что человеку грозит опасность, обратись в службы. Только сама не заходи.","set":{"alla_final":"help"},"lines":[{"who":"Алла","text":"Так и сделаю. Не ради детектива. Просто не хочу потом думать, что ничего не сказала.","kind":"in"}],"note":""},{"id":"B","title":"Попросить сообщать факты","echo":"Сохрани время и то, что слышала. Не нужно самой проверять подвал.","set":{"alla_final":"record"},"lines":[{"who":"Алла","text":"Записала всё, что помню. Тут сложно ошибиться, когда дом под боком.","kind":"in"}],"note":""},{"id":"C","title":"Не давить на неё","echo":"Решай сама. Я не был там и не могу за тебя ответить.","set":{"alla_final":"autonomy"},"lines":[{"who":"Алла","text":"Спасибо, что хотя бы этого не отнимаешь. Я поговорю с Томазиком утром.","kind":"in"}],"note":""}],"variants":[{"when":{"help_route":"official"},"lines":[{"who":"Алла","text":"Томазик уже рассказал мне, что можно попросить помощи, не входя в дом. Я об этом и думала.","kind":"in"}]},{"when":{"help_route":"cautious"},"lines":[{"who":"Алла","text":"То, что ты не выдаёшь подозрения за знания, я ценю. Другие так не умеют.","kind":"in"}]},{"when":{"help_route":"hands_off"},"lines":[{"who":"Алла","text":"Да, мне сказали, что ты не хочешь вмешиваться. Я за тебя и не решила.","kind":"in"}]}]},{"id":"F10","title":"Пятница, 22:10 — Кухня","chat":"Серёга","core":[{"who":"Серёга","text":"Ну что. Пятница закончилась. Я наконец купил чайник.","kind":"in"},{"who":"Серёга","text":"Заодно взял хлеба. Чувствую, что мне теперь хлеб будет сниться до конца жизни.","kind":"in"},{"who":"Серёга","text":"С историей на кухне никакой красивой разгадки не получилось.","kind":"in"},{"who":"Серёга","text":"Ты, кстати, не жалеешь, что я тебе тогда написал?","kind":"in"}],"choices":[{"id":"A","title":"Ответить по-дружески","echo":"Не жалею. Просто странное было утро.","set":{"sergey_final":"friend"},"lines":[{"who":"Серёга","text":"Странное — да. Но я ещё всё-таки люблю обычные утра. Даже после такого.","kind":"in"}],"note":""},{"id":"B","title":"Поставить границу","echo":"Пиши, конечно. Но чужие фотографии больше без предупреждения не присылай.","set":{"sergey_final":"boundary"},"lines":[{"who":"Серёга","text":"Договорились. Следующее фото будет котлеты. Если котлета не окажется чужой головой.","kind":"in"}],"note":""},{"id":"C","title":"Не искать обязательный ответ","echo":"Не на всё найдётся ответ. Иногда можно просто жить дальше.","set":{"sergey_final":"accept"},"lines":[{"who":"Серёга","text":"Это мой любимый вариант. Я и так чайник из-за этой истории чуть не похоронил.","kind":"in"}],"note":""}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Кому нужно разбираться, теперь разбираются. Мне только сказали пока не уничтожать переписку.","kind":"in"}]},{"when":{"theory_mode":"spread"},"lines":[{"who":"Серёга","text":"Марат там, кстати, себе целый детектив написал. Мне теперь соседи соболезнуют. Хотя я живой.","kind":"in"}]},{"when":{"mara_reply":"remove"},"lines":[{"who":"Серёга","text":"Слух хоть перестал разрастаться. За это спасибо.","kind":"in"}]},{"when":{"photo_route":"private"},"lines":[{"who":"Серёга","text":"Спасибо, что не гонял фото по знакомым без спроса. Я это заметил.","kind":"in"}]}]},{"id":"F11","title":"Суббота, 08:06 — Разные дела","chat":"Валерик","core":[{"who":"Валерик","text":"Утро. Я решил написать тебе один раз и потом заняться своим.","kind":"in"},{"who":"Валерик","text":"Андрей мёртв. Список извлечён. Деньги разделены. Это всё, что я точно знаю о нашей истории.","kind":"in"},{"who":"Валерик","text":"А что там у людей на кухне, под полом и за магазином — у них свои дела. Ты не обязан собирать из них одну картину.","kind":"in"},{"who":"Валерик","text":"Был от тебя толк хотя бы как от собеседника?","kind":"in"}],"choices":[{"id":"A","title":"Остаться на связи","echo":"В чём-то да. Своё закончи сам, а я со своими людьми разберусь.","set":{"chapter_end":"open"},"lines":[{"who":"Валерик","text":"Вот. Разумно. Но кофе в следующий раз оплачиваешь ты.","kind":"in"}],"note":""},{"id":"B","title":"Закрыть неприятную линию","echo":"Я твоё признание и твои деньги больше обсуждать не хочу.","set":{"chapter_end":"close"},"lines":[{"who":"Валерик","text":"Это твоё право. Я, кстати, тоже хочу поговорить о чём-нибудь кроме мозга покойника.","kind":"in"}],"note":""},{"id":"C","title":"Спросить о последствиях","echo":"Убитого не вернёшь, но у этой истории же ещё будут последствия?","set":{"chapter_end":"questions"},"lines":[{"who":"Валерик","text":"Разумеется будут. Дело сделано не значит дело забыто. Ты только не проси меня придумывать их заранее.","kind":"in"}],"note":""}],"variants":[{"when":{"killer_reply":"private"},"lines":[{"who":"Валерик","text":"Убийца сказал, что ты не разносил его слова. Он, по-моему, даже смутился.","kind":"in"}]},{"when":{"killer_reply":"boundaries"},"lines":[{"who":"Валерик","text":"Убийца сказал, что ты ничего не обещал. Нормальный подход, учитывая, что вас вообще не знакомили.","kind":"in"}]},{"when":{"killer_reply":"block"},"lines":[{"who":"Валерик","text":"С ним я договорился. Тебя он, насколько знаю, больше беспокоить не будет.","kind":"in"}]},{"when":{"alla_final":"help"},"lines":[{"who":"Система","text":"Алла решила обратиться за помощью. Подтверждения о судьбе Шомпола у игрока пока нет.","kind":"sys"}]},{"when":{"alla_final":"record"},"lines":[{"who":"Система","text":"Алла сохранила время и подробности, но исход событий в подполе пока неизвестен.","kind":"sys"}]},{"when":{"alla_final":"autonomy"},"lines":[{"who":"Система","text":"Алла оставила решение за собой; сообщений о результатах пока нет.","kind":"sys"}]}]},{"id":"F12","title":"Суббота, 10:42 — Стук за стеной","chat":"Алла","core":[{"who":"Алла","text":"Слушай. Ты спрашивал про того, кто стучал. У меня есть новости.","kind":"in"},{"who":"Алла","text":"Я сама слышала стук. Дальше я могу говорить только о том, что действительно случилось после этого.","kind":"in"}],"choices":[{"id":"A","title":"Спросить об исходе","echo":"Главное: человек там был? Ты узнала?","set":{"cellar_epilogue":"ask"},"lines":[{"who":"Алла","text":"Узнала ровно столько, сколько тебе написала. Дальше будут уже чужие слова.","kind":"in"}],"note":""},{"id":"B","title":"Поблагодарить за информацию","echo":"Спасибо, что написала. И что не пошла туда одна.","set":{"cellar_epilogue":"thanks"},"lines":[{"who":"Алла","text":"Сама бы не пошла. Но предупреждение услышала. И Томазик услышал.","kind":"in"}],"note":""},{"id":"C","title":"Закончить без новых вопросов","echo":"Если появятся подтверждённые новости — сообщи. Пока не буду гадать.","set":{"cellar_epilogue":"quiet"},"lines":[{"who":"Алла","text":"Договорились. Лучше одна нормальная новость, чем десять красивых версий.","kind":"in"}],"note":""}],"variants":[{"when":{"help_route":"official","alla_final":"help"},"lines":[{"who":"Алла","text":"Я попросила помощи. Ночью приехали. Из дома вывели мужчину. Живого. Соседи назвали его Шомполом.","kind":"in"},{"who":"Алла","text":"Я его не знаю, так что по имени не клянусь. Но он говорил сам, стоял на ногах, и его увезли на скорой.","kind":"in"},{"who":"Томазик","text":"Я видел машины у дома. Магазин тогда уже закрыл. Алле потом принёс воды. У меня всегда есть вода, это магазин.","kind":"in"}]},{"when":{"help_route":"official","alla_final":"record"},"lines":[{"who":"Алла","text":"Я записала время стука и потом сообщила про него. Приезжали какие-то люди, поговорили с соседями.","kind":"in"},{"who":"Алла","text":"Кто был под полом и нашли ли кого-нибудь — не знаю. Я на месте не присутствовала.","kind":"in"}]},{"when":{"help_route":"official","alla_final":"autonomy"},"lines":[{"who":"Алла","text":"Томазик передал, что стоит обратиться за помощью. Я решила сначала поговорить с соседкой.","kind":"in"},{"who":"Алла","text":"Соседка говорит, ничего не слышала. Но сейчас я знаю, что сама слышала, и могу это подтвердить.","kind":"in"}]},{"when":{"help_route":"cautious","alla_final":"help"},"lines":[{"who":"Алла","text":"Я всё-таки позвонила и рассказала, что слышала. Приезжали, спрашивали про стуки.","kind":"in"},{"who":"Алла","text":"Открывали ли они подвал — не видела. Никто пока не сказал, что там нашли.","kind":"in"}]},{"when":{"help_route":"cautious","alla_final":"record"},"lines":[{"who":"Алла","text":"У меня есть запись времени. Томазик пообещал вспомнить, кто покупал хлеб.","kind":"in"},{"who":"Алла","text":"Больше ничего подтверждённого. Сегодня в доме тихо.","kind":"in"}]},{"when":{"help_route":"cautious","alla_final":"autonomy"},"lines":[{"who":"Алла","text":"Я передумала спрашивать. Сегодня в доме тихо. Не знаю, хорошо это или плохо.","kind":"in"}]},{"when":{"help_route":"hands_off","alla_final":"help"},"lines":[{"who":"Алла","text":"Никто не подсказал, что делать, но я сама позвонила. Мне сказали: разберёмся.","kind":"in"},{"who":"Алла","text":"Был ли там кто-то, я не видела. Стараюсь больше не смотреть в те окна.","kind":"in"}]},{"when":{"help_route":"hands_off","alla_final":"record"},"lines":[{"who":"Алла","text":"Ночью я ещё раз услышала стук и записала время. Сомнений меньше, подтверждений нет.","kind":"in"}]},{"when":{"help_route":"hands_off","alla_final":"autonomy"},"lines":[{"who":"Алла","text":"Ничего не сделала. Сегодня я просто прошла мимо и не остановилась.","kind":"in"},{"who":"Алла","text":"Стук больше не слышала. Почему — понятия не имею.","kind":"in"}]}]},{"id":"S01","title":"Суббота, 12:06 — Одно обычное утро","chat":"Серёга","core":[{"who":"Серёга","text":"Добрый день. Только не удивляйся — я опять жив.","kind":"in"},{"who":"Серёга","text":"Сломался кран. Вода течёт прямо на пол. Два дня назад я бы решил, что это знак. Сейчас думаю, что прокладка.","kind":"in"},{"who":"Серёга","text":"Сосед просит показать фотографию. Говорит, ему нужно для доказательства, что я всё выдумал.","kind":"in"},{"who":"Серёга","text":"Я уже сказал, что никому ничего доказывать не собираюсь. Но он упёртый.","kind":"in"}],"choices":[{"id":"A","title":"Поддержать отказ","echo":"Не показывай. Ты ему ничего не должен.","set":{"s_neighbor":"refuse"},"lines":[{"who":"Серёга","text":"Вот и я так думаю. Сфотографировал ему кран. Пусть разбирается с этим доказательством.","kind":"in"}],"note":""},{"id":"B","title":"Уточнить, что знает сосед","echo":"А он вообще сам видел пакет или только твой рассказ слышал?","set":{"s_neighbor":"check"},"lines":[{"who":"Серёга","text":"Только рассказ. Зато пересказывает его теперь лучше меня. Знаешь, какая у меня выходит интересная жизнь.","kind":"in"}],"note":""},{"id":"C","title":"Предложить заняться краном","echo":"Закрой воду и вызови сантехника. Соседа потом.","set":{"s_neighbor":"plumber"},"lines":[{"who":"Серёга","text":"Сначала вызову сантехника. Он хоть за деньги, но приходит с инструментами, а не с теориями.","kind":"in"}],"note":""}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Пакет-то уже забрали ещё в четверг. А люди обсуждают так, будто он у меня до сих пор на столе.","kind":"in"}]},{"when":{"head_first":"photo"},"lines":[{"who":"Серёга","text":"И ещё спасибо за вчерашнюю рассылку. Фотографию видел даже человек, которого я никогда не встречал.","kind":"in"}]},{"when":{"theory_mode":"spread"},"lines":[{"who":"Серёга","text":"Это всё после районного чата началось. Там один умник из пакета целый бизнес построил.","kind":"in"}]}]},{"id":"S02","title":"Суббота, 12:41 — Куртка из чулана","chat":"Старый","core":[{"who":"Старый","text":"Слушай, я у себя в чулане куртку нашёл. Кожаную. Ты такую уже лет двадцать нигде не встретишь.","kind":"in"},{"who":"Старый","text":"В одном кармане коробок. В другом ничего. Зато на груди дырка и старое пятно.","kind":"in"},{"who":"Старый","text":"Последний раз я её надевал в девяносто четвёртом. После этого лето провёл в больнице.","kind":"in"},{"who":"Старый","text":"Вопрос простой: выбросить нахер или оставить?","kind":"in"}],"choices":[{"id":"A","title":"Спросить о прошлом","echo":"А что именно случилось в девяносто четвёртом?","set":{"jacket_intro":"history"},"lines":[{"who":"Старый","text":"Я сейчас не готов целый девяносто четвёртый перепечатывать. Там и без меня всё довольно насыщенно было.","kind":"in"},{"who":"Старый","text":"Но куртка хорошая. Мне её даже жалко.","kind":"in"}],"note":""},{"id":"B","title":"Посоветовать сохранить","echo":"Оставь пока. Вещь никуда не торопится.","set":{"jacket_intro":"keep"},"lines":[{"who":"Старый","text":"Ты прав. Она меня тридцать лет ждала, ещё один день потерпит.","kind":"in"}],"note":""},{"id":"C","title":"Спросить про пятно","echo":"А ты уверен, что это твоё пятно?","set":{"jacket_intro":"stain"},"lines":[{"who":"Старый","text":"Уверен настолько, насколько вообще можно быть уверенным в пятнах девяносто четвёртого года.","kind":"in"},{"who":"Старый","text":"А куртка всё-таки красивая, скотина.","kind":"in"}],"note":""}],"variants":[{"when":{"sergey_final":"leave"},"lines":[{"who":"Старый","text":"Мне тут советовали прошлое не трогать. Оно, между прочим, само из шкафа вылезло.","kind":"in"}]}]},{"id":"S03","title":"Суббота, 13:27 — Человек в доме","chat":"Алла","core":[{"who":"Алла","text":"Томазик опять ко мне заходил. Принёс воду, хотя у меня вода в квартире есть.","kind":"in"},{"who":"Алла","text":"Я не собираюсь больше стоять возле того дома и слушать, что там происходит.","kind":"in"},{"who":"Алла","text":"Только одно: я точно слышала стук. Что с человеком, если там вообще был человек, — я пока по слухам судить не буду.","kind":"in"}],"choices":[{"id":"A","title":"Не выдумывать подробности","echo":"Правильно. Главное, ты сама в дом не полезла.","set":{"alla_saturday":"support"},"lines":[{"who":"Алла","text":"Я нормальный человек. Я даже чужую кастрюлю без разрешения не открываю, какой ещё подвал.","kind":"in"}],"note":""},{"id":"B","title":"Попросить проверенные сведения","echo":"Если будет информация от тех, кто приезжал, напиши только то, что знаешь.","set":{"alla_saturday":"verify"},"lines":[{"who":"Алла","text":"Так и сделаю. Моя работа — не рассказывать соседям красивый детектив.","kind":"in"}],"note":""},{"id":"C","title":"Предложить отвлечься","echo":"Ты сегодня собиралась по своим делам. Иди уже.","set":{"alla_saturday":"rest"},"lines":[{"who":"Алла","text":"Собиралась. У меня бусины на нитке разошлись. Вот сейчас сижу, ползаю по ковру, собираю. Очень жизненное занятие.","kind":"in"}],"note":""}],"variants":[{"when":{"help_route":"official","alla_final":"help"},"lines":[{"who":"Алла","text":"Да, когда приезжали, человека из дома вывели. Живого. Я видела сама. Только имени не спрашивала.","kind":"in"}]},{"when":{"help_route":"official","alla_final":"record"},"lines":[{"who":"Алла","text":"Я сообщила время и адрес, но кто был внутри и что там обнаружили — мне не объясняли.","kind":"in"}]},{"when":{"help_route":"cautious","alla_final":"help"},"lines":[{"who":"Алла","text":"После звонка там были люди. Разговаривали с соседями. Дальше я не видела.","kind":"in"}]},{"when":{"help_route":"hands_off","alla_final":"autonomy"},"lines":[{"who":"Алла","text":"Удивительно неприятно, когда не знаешь, стало ли кому-то хуже от твоего молчания. Но я правда не знаю.","kind":"in"}]}]},{"id":"S04","title":"Суббота, 14:12 — Про Немана","chat":"Старый","core":[{"who":"Старый","text":"Я с куртки пыль вытряхнул. И весь день потом вспоминал Немана.","kind":"in"},{"who":"Старый","text":"Он тогда на ВДНХ покупал у меня кое-что. При чём здесь куртка — сам пока не понимаю. Просто память так работает.","kind":"in"},{"who":"Старый","text":"Фотографию вещи сделал. Не очень хорошую. Красивые пятна на солнце плохо фотографируются.","kind":"in"},{"who":"Старый","text":"Ты кому-нибудь из наших её показывать будешь?","kind":"in"}],"choices":[{"id":"A","title":"Сохранить только здесь","echo":"Нет. Это твоя вещь и твоя история.","set":{"jacket_route":"private"},"lines":[{"who":"Старый","text":"И отлично. Мне не хочется утром проснуться героем районной переписки.","kind":"in"}],"note":""},{"id":"B","title":"Попросить разрешения на уточнение","echo":"Могу спросить у знакомого, не помнит ли он такую историю. Имя не назову.","set":{"jacket_route":"relay"},"lines":[{"who":"Старый","text":"Ладно. Только не делай из моего старого куртца сенсацию. Я в нём не на выставку ходил.","kind":"in"},{"who":"Марат (версии)","kind":"forward","from":"Старый","text":"Знакомый нашёл куртку с повреждением, которую не носил с 1994 года. Имя и адрес не раскрываю.","media":null}],"note":""},{"id":"C","title":"Предложить не копаться","echo":"Никому. Убери обратно и займись чем-нибудь приятным.","set":{"jacket_route":"back"},"lines":[{"who":"Старый","text":"Хороший совет. Я вот думал суп сварить. Правда, куртку сначала на место положу.","kind":"in"}],"note":""}],"variants":[{"when":{"jacket_intro":"history"},"lines":[{"who":"Старый","text":"Это не секретный архив, понимаешь? Просто давно было. Молодой был, и дырка появилась.","kind":"in"}]},{"when":{"jacket_intro":"stain"},"lines":[{"who":"Старый","text":"Я после твоего вопроса пятно рассмотрел. Нет, анализы делать не буду. Там ткань уже старше половины наших знакомых.","kind":"in"}]}]},{"id":"S05","title":"Суббота, 15:05 — Тридцать лет в чате","chat":"Марат (версии)","core":[{"who":"Марат (версии)","text":"Есть мысль. Про то, как люди обращаются с прошлым.","kind":"in"},{"who":"Марат (версии)","text":"Они его в чулан убирают. А потом находят и удивляются. Хотя вещи там лежали всё это время.","kind":"in"},{"who":"Марат (версии)","text":"Я это не как теорию заговора говорю. Пока.","kind":"in"}],"choices":[{"id":"A","title":"Попросить оставить всё частным","echo":"Ничего в районный чат не отправляй. Это не твоя история.","set":{"mara_jacket":"private"},"lines":[{"who":"Марат (версии)","text":"Имею право не писать в районный чат. Начну с этого. Необычно, но попробую.","kind":"in"}],"note":""},{"id":"B","title":"Разрешить говорить обобщённо","echo":"Можешь про память рассуждать, только без людей, адресов и фотографии.","set":{"mara_jacket":"general"},"lines":[{"who":"Марат (версии)","text":"Это уже практически литература. С литературы у меня обычно неприятности и начинаются.","kind":"in"}],"note":""},{"id":"C","title":"Поддержать публикацию","echo":"Пиши, если считаешь важным. Но чужих имён не называй.","set":{"mara_jacket":"posted"},"lines":[{"who":"Марат (версии)","text":"Имён не будет. Будет «некий человек» и «загадочный предмет». А люди сами всё остальное додумают. Ох, зря я, наверное.","kind":"in"}],"note":""}],"variants":[{"when":{"jacket_route":"relay"},"lines":[{"who":"Марат (версии)","text":"И твой знакомый с курткой у меня в голове теперь сидит. Буквально не в голове, если что. В мыслях.","kind":"in"}]},{"when":{"jacket_route":"private"},"lines":[{"who":"Марат (версии)","text":"Про куртку мне не рассказывали. Поэтому когда слышу разговоры про какие-то куртки, я пока не при делах.","kind":"in"}]},{"when":{"theory_mode":"spread"},"lines":[{"who":"Марат (версии)","text":"Я после истории с кухней осторожнее стал. Там мне уже звонили и спрашивали, где мои доказательства.","kind":"in"}]}]},{"id":"S06","title":"Суббота, 16:36 — Неоплаченный","chat":"Бармен","core":[{"who":"Бармен","text":"Здравствуйте. Номер давно у меня записан. Не помню даже, почему. Можно вопрос?","kind":"in"},{"who":"Бармен","text":"Много лет назад в нашем баре была стрельба. Люди убежали, один милиционер упал. А на столе остался счёт.","kind":"in"},{"who":"Бармен","text":"И вот сегодня мне написал человек. Говорит, помнит этот счёт и хочет заплатить.","kind":"in"},{"who":"Бармен","text":"Он про остальное ничего не спрашивает. Только сколько должен. У нас тогда даже ценники другие были.","kind":"in"},{"who":"Бармен","text":"Вы бы что сделали?","kind":"in"}],"choices":[{"id":"A","title":"Пусть оплатит конкретный счёт","echo":"Назовите сумму из старого счёта, если сохранилась. Не придумывайте новую.","set":{"bar_advice":"account"},"lines":[{"who":"Бармен","text":"Счёт в архиве. Бумага жёлтая, но цифры видно. Я его храню не из ностальгии. Просто бар плохо ведёт бухгалтерию.","kind":"in"}],"note":""},{"id":"B","title":"Не трогать старую историю","echo":"Не отвечайте. Слишком много лет прошло.","set":{"bar_advice":"ignore"},"lines":[{"who":"Бармен","text":"Вроде разумно. Но знаете, как неприятно, когда кто-то помнит твой неоплаченный счёт лучше тебя?","kind":"in"}],"note":""},{"id":"C","title":"Спросить про самого человека","echo":"А он хоть представился? Это точно тот самый клиент?","set":{"bar_advice":"identity"},"lines":[{"who":"Бармен","text":"Имени нет. Пишет, что тогда сидел у окна. Мне это не помогает: у окна сидело полбара.","kind":"in"}],"note":""}],"variants":[]},{"id":"S07","title":"Суббота, 18:02 — Честно поделили","chat":"Валерик","core":[{"who":"Валерик","text":"Они меня теперь спрашивают, каково это — достать из человека список, которого он при жизни никому не доверял.","kind":"in"},{"who":"Валерик","text":"Я отвечаю: как обычно. Работаешь, потом приходишь домой и думаешь, почему люди не могут договориться раньше.","kind":"in"},{"who":"Валерик","text":"Кстати, мне сегодня телевизор привезли. Теперь я не богатый человек. Я богатый человек с телевизором.","kind":"in"},{"who":"Валерик","text":"Ты хотел ещё что-нибудь про Андрея узнать?","kind":"in"}],"choices":[{"id":"A","title":"Отказаться от новых сведений","echo":"Нет. Это твои дела. Я там вообще случайно оказался.","set":{"val_weekend":"leave"},"lines":[{"who":"Валерик","text":"Так и есть. На удивление приятная позиция. Оставайся в ней, пока получается.","kind":"in"}],"note":""},{"id":"B","title":"Спросить, где заканчивается его знание","echo":"Из списка ты узнал только тайники? Не чужую биографию?","set":{"val_weekend":"limits"},"lines":[{"who":"Валерик","text":"Только то, ради чего туда полез. Остальное — не моя работа.","kind":"in"},{"who":"Валерик","text":"Когда платят за одну задачу, не надо бесплатно решать чужую жизнь.","kind":"in"}],"note":""},{"id":"C","title":"Спросить о доле","echo":"И что ты с деньгами собираешься делать?","set":{"val_weekend":"money"},"lines":[{"who":"Валерик","text":"Сегодня уже телевизор. Завтра, может, куплю яблок. Не спрашивай так, будто я обязан стать другим человеком.","kind":"in"}],"note":""}],"variants":[{"when":{"killer_reply":"block"},"lines":[{"who":"Валерик","text":"Тот, кто тебя беспокоил вчера, больше не напишет. Мы это отдельно обсудили.","kind":"in"}]},{"when":{"cross_mode":"mention"},"lines":[{"who":"Валерик","text":"И не надо опять мне про Серёгину кухню. Список Андрея к ней доказанно не относится.","kind":"in"}]},{"when":{"cross_mode":"separate"},"lines":[{"who":"Валерик","text":"Мне нравится, что ты не пытаешься приклеить к нашему делу каждую районную неприятность.","kind":"in"}]}]},{"id":"S08","title":"Суббота, 19:18 — За стеклом магазина","chat":"Томазик","core":[{"who":"Томазик","text":"У меня сегодня покупатель пытался расплатиться купюрой, на которой ручкой написано «вернуть». Я даже не спросил, кому.","kind":"in"},{"who":"Томазик","text":"Алла заходила за хлебом. Вроде держится. Только на тот дом больше не смотрит.","kind":"in"},{"who":"Томазик","text":"Просила, если будут новости, не собирать их из сплетен. Могу ей передать то, что видел сам.","kind":"in"}],"choices":[{"id":"A","title":"Передать только собственное наблюдение","echo":"Скажи ей только про машины и людей, которых ты действительно видел.","set":{"shop_route":"facts"},"lines":[{"who":"Томазик","text":"Именно так. Увидел — сказал. Не увидел — не придумал.","kind":"in"},{"who":"Алла","kind":"forward","from":"Томазик","text":"Я видел машины у дома и людей возле подъезда. Чего они добились и кто был внутри, я не знаю.","media":null}],"note":""},{"id":"B","title":"Не передавать ничего","echo":"Она просила не сплетничать. Лучше просто оставь её в покое.","set":{"shop_route":"quiet"},"lines":[{"who":"Томазик","text":"Понял. Купила хлеб, ушла. Пусть хотя бы сегодня побудет просто покупателем.","kind":"in"}],"note":""},{"id":"C","title":"Предложить спросить лично","echo":"Спроси у Аллы, что ей конкретно нужно, прежде чем что-то пересылать.","set":{"shop_route":"ask"},"lines":[{"who":"Томазик","text":"Спросил. Говорит, ей сейчас нужен хлеб и чтобы никто не стоял на пороге. Это я понимаю.","kind":"in"}],"note":""}],"variants":[{"when":{"help_route":"official","alla_final":"help"},"lines":[{"who":"Томазик","text":"Того мужчину действительно выводили. Я видел, как он сел в машину. Он был жив. Как его зовут — не знаю.","kind":"in"}]},{"when":{"help_route":"cautious","alla_final":"record"},"lines":[{"who":"Томазик","text":"Заходили спрашивать у соседей, был ли стук. Я ничего не слышал — магазин в это время закрыт.","kind":"in"}]},{"when":{"mara_jacket":"posted","jacket_route":"relay"},"lines":[{"who":"Томазик","text":"И ещё одна беда: в районном чате какие-то люди обсуждают куртку с дыркой. Они уже придумали, что она у меня продаётся. Не продаётся.","kind":"in"}]}]},{"id":"S09","title":"Суббота, 21:33 — Не экспонат","chat":"Старый","core":[{"who":"Старый","text":"Куртку я так и не выбросил. Она на спинке стула висит, как будто кто-то сейчас вернётся за ней.","kind":"in"},{"who":"Старый","text":"Я когда её нашёл, думал, будет приятное воспоминание. А вышло — вспомнил людей, с которыми вообще лучше не встречаться.","kind":"in"},{"who":"Старый","text":"Она не памятник. Просто вещь. И никто её у меня не отнимет, даже если я сам когда-нибудь выброшу.","kind":"in"},{"who":"Старый","text":"Ты что скажешь?","kind":"in"}],"choices":[{"id":"A","title":"Сохранить до решения","echo":"Оставь. Захочешь — уберёшь. Решать тебе.","set":{"jacket_end":"keep"},"lines":[{"who":"Старый","text":"Так и сделаю. И без торжественного открытия музея девяностых.","kind":"in"}],"note":""},{"id":"B","title":"Не возвращаться к травме","echo":"Если из-за неё тяжело, не заставляй себя хранить.","set":{"jacket_end":"letgo"},"lines":[{"who":"Старый","text":"Да я не из-за тяжести. Я просто хлам годами не разбираю. Видимо, пора.","kind":"in"}],"note":""},{"id":"C","title":"Попросить не слать фото в паблики","echo":"Лучше убери снимок из общих чатов, если он там появился.","set":{"jacket_end":"protect"},"lines":[{"who":"Старый","text":"Я никому не выкладывал. Если кто-то сам решил показать — это уже его совесть.","kind":"in"}],"note":""}],"variants":[{"when":{"jacket_route":"relay","mara_jacket":"posted"},"lines":[{"who":"Старый","text":"Мне сегодня незнакомые люди в личку написали: «это у вас куртка с дыркой?» Очень мило. Я-то думал, мы просто поговорили.","kind":"in"},{"who":"Старый","text":"Если ещё раз кто-то захочет искать мне по фото биографию — пусть сначала найдёт себе занятие.","kind":"in"}]},{"when":{"jacket_route":"relay","mara_jacket":"private"},"lines":[{"who":"Старый","text":"Твой знакомый, кажется, ничего не разнёс. За это спасибо. Я вчера уже был готов к массовой экскурсии в чулан.","kind":"in"}]},{"when":{"jacket_route":"private"},"lines":[{"who":"Старый","text":"И хорошо, что мы её никому не пересылали. Вчера мне хватило собственных воспоминаний.","kind":"in"}]}]},{"id":"S10","title":"Воскресенье, 08:27 — По старым ценам","chat":"Бармен","core":[{"who":"Бармен","text":"Доброе утро. Счёт, оказывается, можно хранить дольше, чем человека помнят.","kind":"in"},{"who":"Бармен","text":"Мне ещё вчера вечером снова написали про тот старый вечер. Даже не извинились. Только «сколько?».","kind":"in"}],"choices":[{"id":"A","title":"Посоветовать закрыть вопрос","echo":"Если деньги поступили, выдайте подтверждение и закройте счёт.","set":{"bar_final":"closed"},"lines":[{"who":"Бармен","text":"Хорошо. Если что — напишу сумму и что оплата получена. Никаких надгробных речей.","kind":"in"}],"note":""},{"id":"B","title":"Попросить не путать долги и вину","echo":"Оплата счёта не отменит того, что тогда произошло.","set":{"bar_final":"not_forget"},"lines":[{"who":"Бармен","text":"Разумеется. За выстрелы платят не в барной кассе. Просто в кассе тоже был долг.","kind":"in"}],"note":""},{"id":"C","title":"Закончить переписку","echo":"Я тут не помощник. Это между вами.","set":{"bar_final":"distance"},"lines":[{"who":"Бармен","text":"Пожалуй. Я и сам удивился, что столько лет спустя кому-то написал об этой ерунде.","kind":"in"}],"note":""}],"variants":[{"when":{"bar_advice":"account"},"lines":[{"who":"Бармен","text":"Вчера вечером мне прислали перевод — точно по жёлтому чеку. В назначении платежа написали «старый счёт». Ни копейки сверху.","kind":"in"},{"who":"Бармен","text":"Остальное не стало лучше, но у меня хоть одна цифра сошлась.","kind":"in"}]},{"when":{"bar_advice":"identity"},"lines":[{"who":"Бармен","text":"Клиент фото прислал. На нём он молодой, сидит у окна. Лицо я не помню. Тогда я больше смотрел на двери.","kind":"in"},{"who":"Бармен","text":"Деньги пока не прислал. Зато фотография есть. Прямо музей какой-то.","kind":"in"}]},{"when":{"bar_advice":"ignore"},"lines":[{"who":"Бармен","text":"Я вчера так и не ответил. Он написал ещё раз: «можно хотя бы узнать сумму?»","kind":"in"},{"who":"Бармен","text":"Представляете, человек через столько лет ждёт от меня ценник.","kind":"in"}]}]},{"id":"S11","title":"Воскресенье, 10:11 — Вода из крана","chat":"Серёга","core":[{"who":"Серёга","text":"Сантехник приходил. Говорит, прокладка. Я ему сразу поверил. У него сумка с ключами, это располагает.","kind":"in"},{"who":"Серёга","text":"Кухня теперь чистая. Даже странно, как быстро человек снова привыкает к нормальному столу.","kind":"in"},{"who":"Серёга","text":"Мне сегодня опять предложили «найти убийцу». А я хочу найти крышку от кастрюли. И это, между прочим, реальная задача.","kind":"in"},{"who":"Серёга","text":"Ты как думаешь, мне надо дальше всем объяснять, что произошло?","kind":"in"}],"choices":[{"id":"A","title":"Не обязан объяснять","echo":"Нет. Если спросят по делу — ответишь по делу. Остальное не твоя обязанность.","set":{"head_closure":"privacy"},"lines":[{"who":"Серёга","text":"Так и сделаю. Что я видел — расскажу. Чего не видел — придумают без меня.","kind":"in"}],"note":""},{"id":"B","title":"Сохранить факты","echo":"Запиши для себя, что было и когда. Не версии. Факты.","set":{"head_closure":"notes"},"lines":[{"who":"Серёга","text":"Запишу. В четверг проснулся, увидел, не позавтракал. Вот последнее, кстати, меня до сих пор бесит.","kind":"in"}],"note":""},{"id":"C","title":"Отпустить историю","echo":"Давай хотя бы сегодня не будем обсуждать голову.","set":{"head_closure":"stop"},"lines":[{"who":"Серёга","text":"Давай. У меня сегодня вареники. И никакой криминалистики.","kind":"in"}],"note":""}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Мне номер дела продиктовали. Сказали, позвонят, если нужно будет. Ничего такого, чтоб мне теперь самому искать тело.","kind":"in"}]},{"when":{"head_first":"photo"},"lines":[{"who":"Серёга","text":"Кто-то всё ещё пересылает фотографию. Я её удалил. Удалил — и всё, мой вклад в глобальную историю закончен.","kind":"in"}]},{"when":{"head_first":"details"},"lines":[{"who":"Серёга","text":"Вчера наконец сообщил куда надо. Приехали, забрали пакет. Я объяснил про замок и макароны. Макароны их не заинтересовали.","kind":"in"}]},{"when":{"rumor_mode":"contained"},"lines":[{"who":"Серёга","text":"После того, как мы не стали это обсуждать с районом, звонков стало меньше. Удобный эффект молчания.","kind":"in"}]},{"when":{"rumor_mode":"speculation"},"lines":[{"who":"Серёга","text":"Мне сосед напомнил, что я сам разрешил показать снимок. Так что тут мои собственные талантливые решения.","kind":"in"}]}]},{"id":"S12","title":"Воскресенье, 12:32 — Чужой номер","chat":"Шурик","core":[{"who":"Шурик","text":"Ну что. Я нашёл того самого Кольку. Уже точно того.","kind":"in"},{"who":"Шурик","text":"Поговорили минут семь. Про девяностые не стали. Он сказал, что у него внучка родилась.","kind":"in"},{"who":"Шурик","text":"Я его спросил, сколько мы друг другу должны. Он сказал: «Шура, ты вообще нормальный?»","kind":"in"},{"who":"Шурик","text":"Я подумал — да. Если об этом спрашиваю, видимо, стал нормальный.","kind":"in"},{"who":"Шурик","text":"Тебя я тогда всё-таки по ошибке нашёл. Но уж раз написал — спасибо, что ответил.","kind":"in"}],"choices":[{"id":"A","title":"Пожелать простого","echo":"Хорошо, что позвонил. Живи спокойно.","set":{"shura_weekend":"peace"},"lines":[{"who":"Шурик","text":"Вот и план. Вечером за рыбой пойду. В нашем возрасте хороший план всегда про ужин.","kind":"in"}],"note":""},{"id":"B","title":"Пошутить про деньги","echo":"Главное, чтобы ты теперь мне ничего не был должен.","set":{"shura_weekend":"joke"},"lines":[{"who":"Шурик","text":"Поздно. Я тебе уже должен семь минут нормального разговора. Но это я, пожалуй, отдам в рассрочку.","kind":"in"}],"note":""},{"id":"C","title":"Спросить про Филиппины","echo":"Как у тебя там вообще? Не скучно?","set":{"shura_weekend":"life"},"lines":[{"who":"Шурик","text":"Скучно, конечно. Иногда прекрасно скучно. Ты бы знал, сколько сил надо, чтобы такое скучное место себе организовать.","kind":"in"}],"note":""}],"variants":[{"when":{"shurik_mode":"truth"},"lines":[{"who":"Шурик","text":"Кстати, спасибо, что сразу сказал: ты не Димон. Я ведь это только через минуту после звонка заметил.","kind":"in"}]},{"when":{"shurik_mode":"friendly"},"lines":[{"who":"Шурик","text":"Смешно, что я всё начал не с того номера. А хорошо закончилось.","kind":"in"}]}]},{"id":"S13","title":"Воскресенье, 16:03 — Некая куртка","chat":"Марат (версии)","core":[{"who":"Марат (версии)","text":"Я тут кое-что понял про себя.","kind":"in"},{"who":"Марат (версии)","text":"Когда мне дают три факта, я делаю пять выводов. А потом все почему-то хотят, чтобы я им доказал седьмой.","kind":"in"},{"who":"Марат (версии)","text":"И с этой курткой, кажется, получилось примерно так. Если ты вообще понимаешь, о чём я.","kind":"in"},{"who":"Марат (версии)","text":"Может, мне кому-нибудь извиниться?","kind":"in"}],"choices":[{"id":"A","title":"Признать ошибку публично","echo":"Если писал о чужом, напиши там же, что это были догадки.","set":{"mara_retract":"public"},"lines":[{"who":"Марат (версии)","text":"Сделаю. Не самое приятное чувство, зато первый раз за долгое время не буду спорить с собственной записью.","kind":"in"}],"note":""},{"id":"B","title":"Извиниться лично","echo":"Если задел человека, напиши ему напрямую. Без объяснений и теорий.","set":{"mara_retract":"personal"},"lines":[{"who":"Марат (версии)","text":"Попробую. Хотя мне проще написать длинный текст про общество, чем короткое «прости».","kind":"in"}],"note":""},{"id":"C","title":"Оставить тему","echo":"Ты ничего конкретного не доказал. Может, просто больше не обсуждать?","set":{"mara_retract":"silence"},"lines":[{"who":"Марат (версии)","text":"Может. Хотя молчание я обычно принимаю за знак, что моя теория верна. Придётся переучиваться.","kind":"in"}],"note":""}],"variants":[{"when":{"jacket_route":"relay","mara_jacket":"posted"},"lines":[{"who":"Марат (версии)","text":"Я действительно написал про человека с курткой. Адрес не давал, но людям и адреса не надо — остальное сами придумывают.","kind":"in"}]},{"when":{"jacket_route":"relay","mara_jacket":"private"},"lines":[{"who":"Марат (версии)","text":"Я историю никому не пересылал. Но человек всё равно, наверное, боялся. За это можно извиниться.","kind":"in"}]},{"when":{"jacket_route":"private"},"lines":[{"who":"Марат (версии)","text":"Ты мне о той куртке ничего не сообщал. Но я сам вчера почувствовал, что кого-то уже начинаю обвинять без всяких оснований.","kind":"in"}]}]},{"id":"S14","title":"Воскресенье, 18:46 — Вешалка","chat":"Старый","core":[{"who":"Старый","text":"Ну что. Куртка висит в шкафу. Не выбросил.","kind":"in"},{"who":"Старый","text":"Я в ней тогда поехал на одну встречу. Домой привезли уже без неё. Потом отдали.","kind":"in"},{"who":"Старый","text":"И знаешь, что самое неприятное? Я от того лета помню вовсе не больницу. Я помню, как мне было обидно за куртку.","kind":"in"},{"who":"Старый","text":"Сейчас смешно. Тогда не очень.","kind":"in"},{"who":"Старый","text":"Ладно. Спасибо, что выслушал. На следующей неделе тоже шкаф разберу. Там у меня ботинки, но я их ещё боюсь.","kind":"in"}],"choices":[{"id":"A","title":"Закрыть разговор тепло","echo":"Не торопись с ботинками. Хорошо, что написал.","set":{"weekend_end":"warm"},"lines":[{"who":"Старый","text":"Ты прав. Ботинки пусть до следующего века полежат. Не заслужили они такой суеты.","kind":"in"}],"note":""},{"id":"B","title":"Ответить без сантиментов","echo":"Куртка твоя. Шкаф твой. Разбирай когда хочешь.","set":{"weekend_end":"matter"},"lines":[{"who":"Старый","text":"Вот. Человеческий разговор. Ни психоанализа, ни телевизора, одни вещи.","kind":"in"}],"note":""},{"id":"C","title":"Вернуться к фактам","echo":"Если когда-нибудь захочешь рассказать про ту встречу — напиши.","set":{"weekend_end":"story"},"lines":[{"who":"Старый","text":"Может быть. Только я не обещаю, что помню всё правильно. Даже кто первый позвонил, не помню.","kind":"in"}],"note":""}],"variants":[{"when":{"jacket_route":"relay","mara_jacket":"posted","mara_retract":"public"},"lines":[{"who":"Старый","text":"Тот умник в районном чате поправился. Написал, что ошибся и ничего не знает. Удивительная редкость.","kind":"in"}]},{"when":{"jacket_route":"relay","mara_jacket":"posted","mara_retract":"personal"},"lines":[{"who":"Старый","text":"Тот знакомый извинился. Лично. Не просил, но прочитал. Нормально.","kind":"in"}]},{"when":{"jacket_route":"relay","mara_jacket":"posted","mara_retract":"silence"},"lines":[{"who":"Старый","text":"В районном чате так никто и не поправился. Теперь у меня куртка со своей легендой. Легенда, разумеется, чужая.","kind":"in"}]},{"when":{"jacket_route":"private"},"lines":[{"who":"Старый","text":"И хорошо, что никто её не растащил по людям. Куртка у меня, история тоже у меня.","kind":"in"}]},{"when":{"jacket_end":"letgo"},"lines":[{"who":"Старый","text":"Выкинуть решил позже, если что. Сейчас пока пусть будет. Я впервые за много лет на неё спокойно смотрю.","kind":"in"}]}]},{"id":"M01","title":"Понедельник, 08:08 — Ножницы","chat":"Восемь","core":[{"who":"Восемь","text":"Доброе утро. Не помнишь, где хорошие ножницы продают? Маленькие, для ногтей.","kind":"in"},{"who":"Восемь","text":"Купил немецкие. Одну неделю пережили — уже скрипят. А у меня с понедельниками и так непростые отношения.","kind":"in"},{"who":"Восемь","text":"Ладно. Вопрос к тебе как к человеку, у которого, надеюсь, обычное количество рук: ремонтировать или новые?","kind":"in"}],"choices":[{"id":"A","title":"Уточнить, что случилось","echo":"А что ты с ними делал? Металл резал?","set":{"nail_intro":"cause"},"lines":[{"who":"Восемь","text":"Ногти. Просто ногти. У меня неделя была такая, что под ними лучше не рассматривать.","kind":"in"},{"who":"Восемь","text":"Удивительное дело: ножницам хватило семи дней, а мне пока нет.","kind":"in"}],"note":""},{"id":"B","title":"Ответить по делу","echo":"Проще купить новые. Ножницы дешевле твоего времени.","set":{"nail_intro":"replace"},"lines":[{"who":"Восемь","text":"Дельно. Куплю такие же. Хотя старые мне как-то роднее. В отличие от некоторых людей.","kind":"in"}],"note":""},{"id":"C","title":"Отказаться быть консультантом","echo":"Я в маникюрных инструментах вообще не разбираюсь.","set":{"nail_intro":"nohelp"},"lines":[{"who":"Восемь","text":"Нормальный ответ. У меня один знакомый тоже ни в чём не разбирался. И ничего, всю жизнь советовал.","kind":"in"}],"note":""}],"variants":[]},{"id":"M02","title":"Понедельник, 08:43 — Не тот Колян","chat":"Шурик","core":[{"who":"Шурик","text":"Проснулся — у меня двадцать три сообщения от людей, которым я больше ничего не должен.","kind":"in"},{"who":"Шурик","text":"Один спрашивает, не знаю ли я Коляна Кубика-Рубика. Знаешь, сколько на свете Коль?","kind":"in"},{"who":"Шурик","text":"Я сказал, что нужного он пусть сам ищет. Я на Филиппинах. У меня сегодня рыба и ни одного Кубика.","kind":"in"}],"choices":[{"id":"A","title":"Не связывать людей по имени","echo":"Коль много. Это ещё не значит, что речь об одном человеке.","set":{"shura_monday":"names"},"lines":[{"who":"Шурик","text":"Вот именно. Я и жена моя разные, хотя оба друг друга Шурой зовём в шутку.","kind":"in"}],"note":""},{"id":"B","title":"Спросить про жизнь","echo":"Рыбу-то поймал или только план составил?","set":{"shura_monday":"fish"},"lines":[{"who":"Шурик","text":"Пока только повод купить снасти. Когда-нибудь надо же начать заниматься исключительно бесполезным.","kind":"in"}],"note":""},{"id":"C","title":"Попросить не втягивать","echo":"Если тебе напишут по чужому делу, не надо меня туда пересылать.","set":{"shura_monday":"private"},"lines":[{"who":"Шурик","text":"Договорились. Я сам-то тебя сначала нашёл случайно, а теперь стараюсь из этого не делать профессию.","kind":"in"}],"note":""}],"variants":[{"when":{"shura_weekend":"joke"},"lines":[{"who":"Шурик","text":"И да, семь минут разговора в рассрочку ещё не выплатил. Учту в домашней бухгалтерии.","kind":"in"}]},{"when":{"shura_weekend":"life"},"lines":[{"who":"Шурик","text":"Ты спрашивал про скуку. Сегодня решил скучать продуктивно — рассортировал крючки.","kind":"in"}]}]},{"id":"M03","title":"Понедельник, 09:12 — Колян","chat":"Колян","core":[{"who":"Колян","text":"Здорово. Колян Кубик-Рубик. Номер мне общий знакомый дал, не спрашивай какой.","kind":"in"},{"who":"Колян","text":"У меня есть человек, которого сегодня надо предупредить. Вача вышел. Да, тот Вача.","kind":"in"},{"who":"Колян","text":"У него к этому человеку старый разговор: квартира и два миллиона. Настроение у Вачи — как обычно, только ещё хуже.","kind":"in"},{"who":"Колян","text":"Сонному можешь написать? Я у него в блокировке. После прошлой осени заслуженно.","kind":"in"}],"choices":[{"id":"A","title":"Передать предупреждение дословно","echo":"Передам ему всё. Без украшений.","set":{"vacha_notice":"full"},"lines":[{"who":"Колян","text":"Спасибо. Только не добавляй, что он кого-то уже убил. Я этого не знаю.","kind":"in"},{"who":"Сонный","kind":"forward","from":"Колян","text":"Колян предупредил: Вача вышел, хочет встретиться по старому спору о квартире и двух миллионах. Это предупреждение, не подтверждение угрозы.","media":null}],"note":""},{"id":"B","title":"Проверить сведения","echo":"А ты точно знаешь, что Вача вышел, или опять по слухам?","set":{"vacha_notice":"verify"},"lines":[{"who":"Колян","text":"Сам звонил. От Рашидика. Но детали про деньги со слов Вачи. Я бы их отдельно проверял.","kind":"in"},{"who":"Колян","text":"Если хочешь, передай Сонному только сам факт выхода. Это уже что-то.","kind":"in"}],"note":""},{"id":"C","title":"Не брать на себя чужое","echo":"Я не знаю Сонного и не хочу передавать ему чужие обвинения.","set":{"vacha_notice":"none"},"lines":[{"who":"Колян","text":"Понял. Сам попробую ещё раз. Если что, не буду говорить, что ты виноват.","kind":"in"}],"note":""}],"variants":[]},{"id":"M04","title":"Понедельник, 09:58 — Сны","chat":"Сонный","core":[{"who":"Сонный","text":"Привет. Колян дал твой номер. Сказал, ты не любишь, когда люди угадывают чужие биографии.","kind":"in"},{"who":"Сонный","text":"Он мне ночью раза четыре снился. И утром ещё снился. Я встал, поставил чайник и подумал: хватит.","kind":"in"},{"who":"Сонный","text":"Всё равно кто-то сейчас будет названивать и требовать старые деньги. По моему опыту понедельник для этого самый удобный день.","kind":"in"},{"who":"Сонный","text":"Ты бы на моём месте остался дома?","kind":"in"}],"choices":[{"id":"A","title":"Уехать и избежать встречи","echo":"Если реально ждёшь угрозы, не оставайся один дома. Свяжись с теми, кто может помочь.","set":{"sleep_plan":"leave"},"lines":[{"who":"Сонный","text":"Ладно. Пойду к сестре, давно ей обещал полку повесить. Это хотя бы задача, которую можно закончить.","kind":"in"}],"note":""},{"id":"B","title":"Сохранить информацию и попросить помощи","echo":"Запиши угрозы и заранее обратись за помощью. С Вачей сам не разбирайся.","set":{"sleep_plan":"records"},"lines":[{"who":"Сонный","text":"Номера и сообщения сохранил. И ещё у меня утка в холодильнике. Надеюсь, до неё не дойдёт дело раньше меня.","kind":"in"}],"note":""},{"id":"C","title":"Не управлять чужой жизнью","echo":"Это твоя квартира. Я не могу решать за тебя.","set":{"sleep_plan":"stay"},"lines":[{"who":"Сонный","text":"Разумно. Я просто хотел услышать нормальный ответ. А то Колян каждый раз начинает с конца света.","kind":"in"}],"note":""}],"variants":[{"when":{"vacha_notice":"full"},"lines":[{"who":"Сонный","text":"Кстати, твоё сообщение от Коляна дошло. С Вачей я знаком достаточно, чтобы не считать это шуткой.","kind":"in"}]},{"when":{"vacha_notice":"verify"},"lines":[{"who":"Сонный","text":"Колян сказал, что ты спрашивал про подтверждения. Это мне нравится. Остальное пока буду проверять сам.","kind":"in"}]},{"when":{"vacha_notice":"none"},"lines":[{"who":"Сонный","text":"Колян что-то пытался передать через третьих лиц. Я не стал открывать его голосовое — в прошлый раз там были одни претензии.","kind":"in"}]}]},{"id":"M05","title":"Понедельник, 11:06 — Восемь","chat":"Восемь","core":[{"who":"Восемь","text":"С ножницами разобрался. Но есть проблема с ногтями.","kind":"in"},{"who":"Восемь","text":"У меня пальцев на руках восемь. Не девять, не десять. Восемь. Не надо спрашивать, откуда два делись: я тогда даже сам не спрашивал.","kind":"in"},{"who":"Восемь","text":"А под ногтями — всякая жизнь за неделю. Я, между прочим, никого за эту неделю не убил. Не всем такой результат доступен.","kind":"in"},{"who":"Восемь","text":"За остальное не похвалюсь: кому-то руку сломал, кому-то ногу. Сейчас вот ногти пытаюсь привести в порядок.","kind":"in"},{"who":"Восемь","text":"Ты сейчас что-нибудь про меня придумал?","kind":"in"}],"choices":[{"id":"A","title":"Поставить границу","echo":"Нет. Но ломать людям кости — тоже не достижение.","set":{"nail_reply":"boundary"},"lines":[{"who":"Восемь","text":"Я и не просил похвалы. С ножницами вообще легче, чем с разговорами об этике.","kind":"in"}],"note":""},{"id":"B","title":"Спросить о примете, не о преступлении","echo":"Ты всегда говоришь про восемь пальцев так, будто это визитка?","set":{"nail_reply":"notice"},"lines":[{"who":"Восемь","text":"Примета удобная. Человек обычно запоминает. Беда в том, что многие потом помнят только руки.","kind":"in"}],"note":""},{"id":"C","title":"Не обсуждать насилие","echo":"Мне не нужно знать подробности твоей недели. Ножницы решил — и хорошо.","set":{"nail_reply":"distance"},"lines":[{"who":"Восемь","text":"Вот и славно. И знаешь, никто ещё не догадался спросить, удобно ли мне вообще застёгивать пуговицы.","kind":"in"}],"note":""}],"variants":[{"when":{"nail_intro":"cause"},"lines":[{"who":"Восемь","text":"Ты утром спрашивал, чем я ножницы испортил. Теперь, думаю, ясно, почему я стараюсь не обсуждать прошлую неделю.","kind":"in"}]},{"when":{"nail_intro":"replace"},"lines":[{"who":"Восемь","text":"Новые ножницы купил. Продавец так посмотрел, будто я ему сейчас диплом покажу.","kind":"in"}]}]},{"id":"M06","title":"Понедельник, 12:22 — Готовая версия","chat":"Марат (версии)","core":[{"who":"Марат (версии)","text":"Я сегодня был почти хорошим человеком. Ни одного поста про куртки, головы и пропажи.","kind":"in"},{"who":"Марат (версии)","text":"Но мне прислали сообщение про человека с восемью пальцами. Из любопытства, конечно, ничего более.","kind":"in"},{"who":"Марат (версии)","text":"Я уже готов написать, что он имеет отношение к половине наших историй. Тормози меня вовремя.","kind":"in"},{"who":"Марат (версии)","text":"Что мне с этим делать?","kind":"in"}],"choices":[{"id":"A","title":"Оставить сведения частными","echo":"Ничего не публикуй. Восемь пальцев — не доказательство преступления.","set":{"nail_publicity":"private"},"lines":[{"who":"Марат (версии)","text":"Молчу. Наверное, это самое полезное сообщение, которое я сегодня не отправлю.","kind":"in"}],"note":""},{"id":"B","title":"Задать осторожный вопрос без имени","echo":"Можешь спросить, откуда слух, но без имени, адреса и фотографии.","set":{"nail_publicity":"question"},"lines":[{"who":"Марат (версии)","text":"Спрошу только, откуда он взялся. Обещаю не устраивать народный кастинг убийц.","kind":"in"}],"note":""},{"id":"C","title":"Разрешить переслать рассказ","echo":"Передай текст, но напиши, что его никто не проверял.","set":{"nail_publicity":"spread"},"lines":[{"who":"Марат (версии)","text":"Я написал именно так. Люди, правда, обычно читают только самое страшное слово.","kind":"in"}],"note":""}],"variants":[{"when":{"mara_retract":"public"},"lines":[{"who":"Марат (версии)","text":"После истории с курткой я пока держусь. Один публичный отказ от собственных выводов мне уже дорого обошёлся.","kind":"in"}]},{"when":{"mara_retract":"silence"},"lines":[{"who":"Марат (версии)","text":"Кстати, про куртку я так и промолчал. С тех пор её обсуждают без меня, что вообще-то не делает меня умнее.","kind":"in"}]}]},{"id":"M07","title":"Понедельник, 13:14 — Утка","chat":"Сонный","core":[{"who":"Сонный","text":"У меня дома утка. Купил в субботу, хочу по-пекински сделать. Вроде сложный рецепт, но не сложнее моего расписания.","kind":"in"},{"who":"Сонный","text":"Вача пока не пришёл. Колян звонит, а я не беру. Потому что если начинаешь брать все звонки, к вечеру сам становишься справочной.","kind":"in"},{"who":"Сонный","text":"Мне нужно кому-нибудь передать, что я жив. Не своё место, просто факт.","kind":"in"}],"choices":[{"id":"A","title":"Передать Коляну его слова","echo":"Передам Коляну, что ты на связи, без адреса и подробностей.","set":{"sleep_relay":"yes"},"lines":[{"who":"Сонный","text":"Передай. Может, отстанет на пару часов.","kind":"in"},{"who":"Колян","kind":"forward","from":"Сонный","text":"Сонный ответил: он на связи. Адрес, куда поехал или где находится, не передаю.","media":null}],"note":""},{"id":"B","title":"Посоветовать самому написать","echo":"Колян тебя предупреждал. Просто напиши ему сам пару слов.","set":{"sleep_relay":"self"},"lines":[{"who":"Сонный","text":"Сам напишу. Хорошо. Не люблю, когда чужие люди становятся секретарями без зарплаты.","kind":"in"}],"note":""},{"id":"C","title":"Не пересылать ничего","echo":"Я не хочу быть третьим в вашем споре.","set":{"sleep_relay":"no"},"lines":[{"who":"Сонный","text":"Не надо. Понял. Колян человек не обидчивый, он просто долго обижается.","kind":"in"}],"note":""}],"variants":[{"when":{"sleep_plan":"leave"},"lines":[{"who":"Сонный","text":"Полку сестре уже прикрутил. Утка всё ещё дома, а я тут. Можно сказать, пока хороший расклад.","kind":"in"}]},{"when":{"sleep_plan":"records"},"lines":[{"who":"Сонный","text":"Записал звонки и попросил помощи. Теперь за утку отдельно переживаю — не испортится ли.","kind":"in"}]},{"when":{"sleep_plan":"stay"},"lines":[{"who":"Сонный","text":"Я остался у себя. Чужие претензии не повод мне бегать от собственного холодильника.","kind":"in"}]}]},{"id":"M08","title":"Понедельник, 14:03 — Третья попытка","chat":"Колян","core":[{"who":"Колян","text":"Наконец-то добрался до него. Не сразу, но хоть живой.","kind":"in"},{"who":"Колян","text":"Вача уже в городе. Сказал, что придёт с двумя людьми. Дальше мне слушать не понравилось, я разговор закончил.","kind":"in"},{"who":"Колян","text":"Я не прошу тебя устраивать переговоры. Но если ты с Сонным общаешься, помоги не спутать слух с тем, что я сам слышал.","kind":"in"}],"choices":[{"id":"A","title":"Передать подтверждённое","echo":"Передам: Вача сообщил о визите и двух людях. Остальное ты не знаешь.","set":{"kolyan_detail":"facts"},"lines":[{"who":"Колян","text":"Правильно. Меня вчера уже сделали источником трёх чужих фантазий.","kind":"in"},{"who":"Сонный","kind":"forward","from":"Колян","text":"Колян лично услышал от Вачи, что тот собирается прийти с двумя людьми. Время и намерения неизвестны.","media":null}],"note":""},{"id":"B","title":"Попросить его говорить самому","echo":"Свяжись с Сонным напрямую. Это лучше твоего пересказа через меня.","set":{"kolyan_detail":"direct"},"lines":[{"who":"Колян","text":"Попробую ещё раз. И если не возьмёт — напишу. Голосовые больше не буду.","kind":"in"}],"note":""},{"id":"C","title":"Не передавать неподтверждённое","echo":"Не стану ничего добавлять. Ты сказал только про визит.","set":{"kolyan_detail":"keep"},"lines":[{"who":"Колян","text":"Ладно. Хотя иногда человек так тщательно отделяет факты, что потом остаётся один только неприятный факт.","kind":"in"}],"note":""}],"variants":[{"when":{"sleep_relay":"yes"},"lines":[{"who":"Колян","text":"Сообщение от Сонного дошло. Спасибо, что не сказал, где он. Я ведь и сам не спрашивал адрес.","kind":"in"}]},{"when":{"sleep_relay":"no"},"lines":[{"who":"Колян","text":"Я его и так нашёл. В третий раз позвонил, он написал «отстань». Узнаю старого знакомого.","kind":"in"}]}]},{"id":"M09","title":"Понедельник, 15:09 — Слухи про руки","chat":"Восемь","core":[{"who":"Восемь","text":"Мне сегодня позвонил человек, которого я знать не знаю. Спросил, сколько у меня пальцев.","kind":"in"},{"who":"Восемь","text":"Я ему сказал: на руках восемь. Он такой: «Значит, всё сходится». И отключился. Очень продуктивная беседа.","kind":"in"},{"who":"Восемь","text":"Я не святой. Но меня сейчас хотят пристегнуть к делу, о котором я даже не слышал.","kind":"in"},{"who":"Восемь","text":"Ты что-нибудь кому-нибудь обо мне рассказывал?","kind":"in"}],"choices":[{"id":"A","title":"Признать, что обсуждение было","echo":"Марат спрашивал, что делать со слухом. Я не называл тебя участником чужих дел.","set":{"nail_honesty":"admit"},"lines":[{"who":"Восемь","text":"Понял. Хорошо, что сказал прямо. А то за всю неделю у меня был один честный разговор, и тот про ножницы.","kind":"in"}],"note":""},{"id":"B","title":"Спросить про звонок","echo":"Кто звонил? Не давай ему новых сведений и сохрани номер.","set":{"nail_honesty":"ask"},"lines":[{"who":"Восемь","text":"Номер неизвестный. У меня теперь даже спам звонит с интересом к биографии.","kind":"in"}],"note":""},{"id":"C","title":"Отгородиться","echo":"Я не знаю, откуда у людей этот слух. И искать тебе виновных не собираюсь.","set":{"nail_honesty":"distance"},"lines":[{"who":"Восемь","text":"И правильно. Принять участие в разговоре о себе — ещё не значит стать его ведущим.","kind":"in"}],"note":""}],"variants":[{"when":{"nail_publicity":"spread"},"lines":[{"who":"Восемь","text":"И картинка уже в районной ленте. Без лица, правда. Зато в подписи написали, что я эксперт по кровавым делам.","kind":"in"}]},{"when":{"nail_publicity":"private"},"lines":[{"who":"Восемь","text":"Слышал, что один из этих умников всё-таки отказался публиковать. Непривычное ощущение: меня не показали по телевизору.","kind":"in"}]},{"when":{"nail_publicity":"question"},"lines":[{"who":"Восемь","text":"Говорят, кто-то спросил, откуда взялась история. Первый раз хороший вопрос, а не очередной приговор.","kind":"in"}]}]},{"id":"M10","title":"Понедельник, 15:48 — Чужой счёт","chat":"Бармен","core":[{"who":"Бармен","text":"Вы не поверите: сегодня мне снова предложили оплатить тот старый счёт.","kind":"in"},{"who":"Бармен","text":"Только это другой человек. Первый, кажется, уже перевёл. Второй вообще уверен, что счёт его.","kind":"in"},{"who":"Бармен","text":"Я теперь думаю, как мне не превратить бар в благотворительную кассу для людей с плохой памятью.","kind":"in"},{"who":"Бармен","text":"Что бы вы сказали второму?","kind":"in"}],"choices":[{"id":"A","title":"Проверить платёж","echo":"Скажите, что сначала сверите квитанцию. Дважды за одно не берите.","set":{"bar_monday":"check"},"lines":[{"who":"Бармен","text":"Хорошо. У меня бухгалтерия плохая, но не настолько, чтобы чужое себе записывать.","kind":"in"}],"note":""},{"id":"B","title":"Отказаться от второго","echo":"Если счёт закрыт, скажите, что больше денег не нужно.","set":{"bar_monday":"refuse"},"lines":[{"who":"Бармен","text":"Так и отвечу. Хоть кому-то из этих людей должно хватить один раз заплатить.","kind":"in"}],"note":""},{"id":"C","title":"Попросить не втягивать","echo":"Это вопрос вашего бара, я бы не вмешивался.","set":{"bar_monday":"leave"},"lines":[{"who":"Бармен","text":"И справедливо. Не знаю, почему я из неоплаченного счёта сделал жанр переписки.","kind":"in"}],"note":""}],"variants":[{"when":{"bar_advice":"account"},"lines":[{"who":"Бармен","text":"Про первого я знаю точно — старый жёлтый чек закрыт. А у второго, кажется, просто совесть проснулась.","kind":"in"}]},{"when":{"bar_advice":"ignore"},"lines":[{"who":"Бармен","text":"Тогда я ответил только вчера. Возможно, и поэтому теперь два желающих заплатить за одного.","kind":"in"}]},{"when":{"bar_final":"not_forget"},"lines":[{"who":"Бармен","text":"То, что тогда стреляли, ни одна квитанция, разумеется, не отменит.","kind":"in"}]}]},{"id":"M11","title":"Понедельник, 16:27 — Районная переписка","chat":"Марат (версии)","core":[{"who":"Марат (версии)","text":"Похоже, с восемью пальцами я тоже поторопился. Вернее, я сразу никуда не спешил. Только три раза нажал «отправить».","kind":"in"},{"who":"Марат (версии)","text":"Сегодня мой знакомый уже приписал человеку три убийства, одну ограбленную аптеку и чужую кухню.","kind":"in"},{"who":"Марат (версии)","text":"Я проверил: доказательств ни по одному из этих пунктов у меня нет.","kind":"in"},{"who":"Марат (версии)","text":"Что теперь делать со своим сообщением?","kind":"in"}],"choices":[{"id":"A","title":"Удалить догадки и исправить","echo":"Удали обвинения. Если уже разослал — напиши там же, что это выдумка.","set":{"mara_nail":"retract"},"lines":[{"who":"Марат (версии)","text":"Написал. Меня, правда, спросили, кто заставил. Ответил: отсутствие фактов.","kind":"in"}],"note":""},{"id":"B","title":"Ответить только проверенным","echo":"Напиши, что никаких подтверждённых связей с другими случаями нет.","set":{"mara_nail":"facts"},"lines":[{"who":"Марат (версии)","text":"Короткое сообщение получилось. Даже странно: без слова «возможно» почти обошёлся.","kind":"in"}],"note":""},{"id":"C","title":"Не обсуждать больше","echo":"Я не буду разбирать твои сообщения за тебя.","set":{"mara_nail":"leave"},"lines":[{"who":"Марат (версии)","text":"Да, я понял. В следующий раз сначала подумать, потом отправить. Ты сегодня третий, кто мне это говорит.","kind":"in"}],"note":""}],"variants":[{"when":{"nail_publicity":"spread"},"lines":[{"who":"Марат (версии)","text":"И да, я тот самый текст разослал. Хотя ты и предупреждал, что он непроверенный. Это не освобождает меня от ответственности.","kind":"in"}]},{"when":{"nail_publicity":"private"},"lines":[{"who":"Марат (версии)","text":"Хорошо, что тогда хотя бы ты не попросил меня сделать из человека сенсацию. Я и так справился бы.","kind":"in"}]}]},{"id":"M12","title":"Понедельник, 18:03 — Звонок в дверь","chat":"Сонный","core":[{"who":"Сонный","text":"Колян угадал про понедельник. Вача действительно приехал.","kind":"in"},{"who":"Сонный","text":"У меня теперь на кухне утка, которую я не приготовил. И телефон с двадцатью непрочитанными.","kind":"in"},{"who":"Сонный","text":"Я не буду тебе пересказывать, как выглядит человек, с которым споришь о квартире. Лучше скажи, что отвечать Коляну.","kind":"in"}],"choices":[{"id":"A","title":"Попросить конкретный факт","echo":"Главное: ты сам жив и в безопасности?","set":{"sleep_after":"safety"},"lines":[{"who":"Сонный","text":"Сейчас — да. За завтра говорить не буду. Пусть хотя бы ужин окажется предсказуемым.","kind":"in"}],"note":""},{"id":"B","title":"Попросить не скрывать важное","echo":"Коляна надо предупредить, если кому-то сейчас угрожает опасность.","set":{"sleep_after":"alert"},"lines":[{"who":"Сонный","text":"Уже предупредил тех, кому положено знать. Я не делаю из этого приключение на телефон.","kind":"in"}],"note":""},{"id":"C","title":"Не выспрашивать","echo":"Раз ты написал, значит, можешь говорить. Остальное не рассказывай, если не хочешь.","set":{"sleep_after":"space"},"lines":[{"who":"Сонный","text":"Спасибо. С некоторых разговоров нужно снимать обувь, прежде чем в них входить.","kind":"in"}],"note":""}],"variants":[{"when":{"sleep_plan":"leave"},"lines":[{"who":"Сонный","text":"Я тогда ушёл к сестре. Он подошёл к закрытой двери, позвонил, потом уехал. Утка ждёт дома, завтра за ней вернусь.","kind":"in"},{"who":"Сонный","text":"Не знаю, решил ли он вопрос. Знаю только, что не решил его со мной на пороге.","kind":"in"}]},{"when":{"sleep_plan":"records","vacha_notice":"full"},"lines":[{"who":"Сонный","text":"Я заранее сообщил об угрозах. Когда он пришёл, было кому принять разговор вместо меня. Разошлись не друзьями, зато живыми.","kind":"in"}]},{"when":{"sleep_plan":"records","vacha_notice":"verify"},"lines":[{"who":"Сонный","text":"Я всё записал и попросил помощи. Когда приехали люди, было уже шумно. С собой уехал один человек, кого именно — мне пока не говорят.","kind":"in"}]},{"when":{"sleep_plan":"records","vacha_notice":"none"},"lines":[{"who":"Сонный","text":"Предупреждения я толком не понял. Когда он пришёл с двумя, поздно было что-то обсуждать.","kind":"in"},{"who":"Сонный","text":"У меня теперь три чужих телефона в коридоре и полиция в прихожей. Ты выводы сам делай, я пока не хочу.","kind":"in"}]},{"when":{"sleep_plan":"stay"},"lines":[{"who":"Сонный","text":"Я остался дома. Он действительно пришёл с двумя. Я живой. Они — нет.","kind":"in"},{"who":"Сонный","text":"Утка, кстати, в холодильнике. Хоть она ни при чём.","kind":"in"}]}]},{"id":"M13","title":"Понедельник, 19:25 — Сведения дошли","chat":"Колян","core":[{"who":"Колян","text":"Сонный написал. Коротко, но написал. Я уже думал, что надо ехать лично.","kind":"in"},{"who":"Колян","text":"Я сегодня ещё с дачи Рашидика звонил. Там связь нормальная. А до друга всё равно пришлось через чужие номера добираться.","kind":"in"},{"who":"Колян","text":"Сейчас мне бы понять только одно: меня будут вспоминать как человека, который предупредил, или как человека, который разнёс слух?","kind":"in"}],"choices":[{"id":"A","title":"Зафиксировать свою часть","echo":"Ты предупредил о том, что услышал. Что произошло дальше — не твоё сообщение.","set":{"kolyan_end":"truth"},"lines":[{"who":"Колян","text":"Хоть один нормальный ответ. Спасибо. Мне и правда не надо придумывать развязки за других.","kind":"in"}],"note":""},{"id":"B","title":"Посоветовать дать прямые показания","echo":"Если видел что-то сам, сообщи это тем, кто разбирается. Не через меня.","set":{"kolyan_end":"report"},"lines":[{"who":"Колян","text":"Сделаю. Что слышал — повторю. Чего не слышал — не придумаю. Кажется, научился.","kind":"in"}],"note":""},{"id":"C","title":"Не давать оценки","echo":"Тебе самому решать, чего ты добился. Я в это уже не полезу.","set":{"kolyan_end":"distant"},"lines":[{"who":"Колян","text":"Тоже ответ. Неприятный, но свой. Я, пожалуй, до завтра телефон выключу.","kind":"in"}],"note":""}],"variants":[{"when":{"sleep_plan":"leave"},"lines":[{"who":"Колян","text":"Он вообще ушёл до визита. На моей памяти первый раз кто-то предпочёл не встречаться с собственным прошлым.","kind":"in"}]},{"when":{"sleep_plan":"records","vacha_notice":"full"},"lines":[{"who":"Колян","text":"Говорит, успел обратиться за помощью. Вот и хорошо. Я не обязан теперь ехать туда с разговорами.","kind":"in"}]},{"when":{"sleep_plan":"records","vacha_notice":"verify"},"lines":[{"who":"Колян","text":"Вмешались другие люди. Самого Вачу я сегодня не видел. Но по телефону он уже не орёт.","kind":"in"}]},{"when":{"sleep_plan":"records","vacha_notice":"none"},"lines":[{"who":"Колян","text":"Сонный говорит, теперь там разбираются в трёх чужих телефонах. Я не буду спрашивать, кому они принадлежали.","kind":"in"}]},{"when":{"sleep_plan":"stay"},"lines":[{"who":"Колян","text":"Приехал Вача с двумя и не уехал. Всё. Никакой красивой арифметики.","kind":"in"}]},{"when":{"kolyan_detail":"facts"},"lines":[{"who":"Колян","text":"Спасибо, что вторую мою информацию передал как предупреждение, а не как уже случившуюся драку.","kind":"in"}]}]},{"id":"M14","title":"Понедельник, 20:16 — Лишний палец","chat":"Восемь","core":[{"who":"Восемь","text":"Вот тебе фотографию пока не пришлю. Устал, что каждую дырку на куртке и каждый шрам превращают в общественное дело.","kind":"in"},{"who":"Восемь","text":"Под ногтями всё отмыл. А каких именно пальцев нет — не спрашивай. Ножницы я держу, мне хватает.","kind":"in"},{"who":"Восемь","text":"Я не хочу быть хорошим героем твоей переписки. И плохим тоже не хочу. Мне нужны ножницы.","kind":"in"},{"who":"Восемь","text":"Есть по этому поводу ещё вопросы?","kind":"in"}],"choices":[{"id":"A","title":"Закончить по-бытовому","echo":"Не осталось. Новые ножницы купи и береги.","set":{"nail_final":"everyday"},"lines":[{"who":"Восемь","text":"Купил. Сижу, проверяю. Седьмой ноготь подрезал, один остался.","kind":"in"}],"note":""},{"id":"B","title":"Не оправдывать прошлое","echo":"Ножницы тут не главное. Но я не собираюсь тебя судить по переписке.","set":{"nail_final":"boundaries"},"lines":[{"who":"Восемь","text":"Справедливо. Если надо будет судить — меня найдут и без тебя.","kind":"in"}],"note":""},{"id":"C","title":"Попросить не писать о насилии","echo":"Про инструменты пиши. Про людей, которым ты что-то сломал, мне не надо.","set":{"nail_final":"distance"},"lines":[{"who":"Восемь","text":"Договорились. От людей мне тоже отдых нужен. Купил, кстати, новую пилочку.","kind":"in"}],"note":""}],"variants":[{"when":{"nail_publicity":"spread","mara_nail":"retract"},"lines":[{"who":"Восемь","text":"В районном чате написали исправление. Поздновато, но хотя бы перестали спрашивать, где я прячу три тела.","kind":"in"}]},{"when":{"nail_publicity":"spread","mara_nail":"leave"},"lines":[{"who":"Восемь","text":"Никто пока не исправил ту ерунду. Теперь на меня смотрят как на музейную экспозицию криминалистики.","kind":"in"}]},{"when":{"nail_publicity":"private"},"lines":[{"who":"Восемь","text":"И если ты не раздавал мой номер — спасибо. Даже преступному человеку иногда хочется покоя.","kind":"in"}]}]},{"id":"M15","title":"Понедельник, 21:02 — Крышка","chat":"Серёга","core":[{"who":"Серёга","text":"Крышка от кастрюли нашлась.","kind":"in"},{"who":"Серёга","text":"Три дня я её искал, а она за холодильником. Откуда там — хрен знает. Я уже научился на такое не удивляться.","kind":"in"},{"who":"Серёга","text":"Соседи всё ещё обсуждают пакет. Мне теперь каждый раз, когда я не отвечаю, пишут: «Ты точно жив?»","kind":"in"},{"who":"Серёга","text":"Чайник работает. Картошка варится. Ты как?","kind":"in"}],"choices":[{"id":"A","title":"Ответить о своих делах","echo":"У меня сегодня обычный понедельник. По крайней мере, я так надеюсь.","set":{"sergey_monday":"normal"},"lines":[{"who":"Серёга","text":"Это хорошо. Я теперь тоже обычные дни собираю, как кто-то марки.","kind":"in"}],"note":""},{"id":"B","title":"Пошутить","echo":"Главное, чтобы за холодильником больше никого не было.","set":{"sergey_monday":"joke"},"lines":[{"who":"Серёга","text":"Я проверил. Только паутина. Паутину оставил — мало ли, её там кто-то ждёт.","kind":"in"}],"note":""},{"id":"C","title":"Остановить обсуждение","echo":"Про пакет сегодня не надо. Лучше покажи, что сварил.","set":{"sergey_monday":"quiet"},"lines":[{"who":"Серёга","text":"Картошку. Нормальную. Фотографию присылать не буду, я теперь с фотографиями осторожнее.","kind":"in"}],"note":""}],"variants":[{"when":{"head_closure":"stop"},"lines":[{"who":"Серёга","text":"Да, мы договаривались больше о голове не говорить. Я слово держу, насколько умею.","kind":"in"}]},{"when":{"head_closure":"notes"},"lines":[{"who":"Серёга","text":"Я всё записал по дням. Получилось удивительно мало текста для такой огромной неприятности.","kind":"in"}]}]},{"id":"M16","title":"Понедельник, 22:41 — Разные жизни","chat":"Сонный","core":[{"who":"Сонный","text":"Утку я так и не приготовил. Съел картошку. Оказалось, можно прожить день без утки и без выяснения отношений.","kind":"in"},{"who":"Сонный","text":"Завтра будут свои дела. Может, ещё неприятнее сегодняшних. Но хоть следующие полчаса можно не думать о них?","kind":"in"},{"who":"Сонный","text":"Колян написал мне один раз, нормально, без крика. Он умеет, когда захочет.","kind":"in"},{"who":"Сонный","text":"Всё, что мне сейчас нужно, — поесть и закрыть телефон. Ты тоже можешь.","kind":"in"}],"choices":[{"id":"A","title":"Оставить его в покое","echo":"Ешь. Если понадобится помощь, напиши, но сейчас отдохни.","set":{"monday_end":"rest"},"lines":[{"who":"Сонный","text":"Разумный подход. Наконец-то кто-то не требует красивую концовку за ужином.","kind":"in"}],"note":""},{"id":"B","title":"Подтвердить границы","echo":"Я не буду пересказывать эту историю другим.","set":{"monday_end":"privacy"},"lines":[{"who":"Сонный","text":"Спасибо. У нас и без тебя найдутся специалисты по чужому вечеру.","kind":"in"}],"note":""},{"id":"C","title":"Закончить на простом","echo":"У меня тоже ужин. Бывай до завтра.","set":{"monday_end":"goodnight"},"lines":[{"who":"Сонный","text":"Вот. Это хороший конец переписки. Два человека идут есть.","kind":"in"}],"note":""}],"variants":[{"when":{"sleep_plan":"leave"},"lines":[{"who":"Сонный","text":"Полку сестре доделал. Она сказала, что я первый раз приехал без просьбы одолжить денег. Прогресс.","kind":"in"}]},{"when":{"sleep_plan":"records","vacha_notice":"full"},"lines":[{"who":"Сонный","text":"Я рад, что не пытался решать старую историю чужими кулаками. Оно того не стоило.","kind":"in"}]},{"when":{"sleep_plan":"records","vacha_notice":"verify"},"lines":[{"who":"Сонный","text":"Если завтра вызовут рассказать, что было, расскажу. Главное не выдумать лишнего.","kind":"in"}]},{"when":{"sleep_plan":"stay"},"lines":[{"who":"Сонный","text":"Про то, что произошло в прихожей, завтра всё равно придётся отвечать. Сегодня сил нет.","kind":"in"}]},{"when":{"nail_publicity":"spread"},"lines":[{"who":"Сонный","text":"И пожалуйста, больше не пересылай мне районные новости. У меня и своих достаточно.","kind":"in"}]}]},{"id":"T01","title":"Вторник, 08:16 — Чужие фотографии","chat":"Старый","core":[{"who":"Старый","text":"Привет. Ты не занят? Не отвечай сразу. Это вопрос из вежливости.","kind":"in"},{"who":"Старый","text":"Лёха объявился. Тот, который всё бросил, уехал в деревню и обещал там остаться навсегда.","kind":"in"},{"who":"Старый","text":"Вернулся. Теперь из квартиры почти не выходит. Прислал мне фотографию сарая. На фото сарая нет.","kind":"in"},{"who":"Старый","text":"Он говорит, ты умеешь слушать, не устраивая собрание свидетелей. Можно дать ему твой номер?","kind":"in"}],"choices":[{"id":"A","title":"Разрешить ему написать","echo":"Пусть напишет. Только ничего обо мне не придумывай.","set":{"village_first":"welcome"},"lines":[{"who":"Старый","text":"Передам. Он сам за тебя всё додумает, но это его ремесло.","kind":"in"}],"note":""},{"id":"B","title":"Попросить сначала объяснить","echo":"Дай хотя бы понять, что с ним случилось.","set":{"village_first":"ask"},"lines":[{"who":"Старый","text":"Пытался. Он пересказывает это как ремонт крыши: сначала в доме волк, потом больница, а в конце куда-то делись двери.","kind":"in"}],"note":""},{"id":"C","title":"Не навязываться","echo":"Если хочет — сам найдёт. Посредником между вами не буду.","set":{"village_first":"distance"},"lines":[{"who":"Старый","text":"Согласен. Я вообще хотел выяснить, есть ли у человека работа. Он вместо этого про волка рассказал.","kind":"in"}],"note":""}],"variants":[{"when":{"jacket_route":"quiet"},"lines":[{"who":"Старый","text":"После истории с моей курткой я, кстати, перестал рассылать людям чужие фотографии. Научился на старости лет.","kind":"in"}]},{"when":{"jacket_route":"share"},"lines":[{"who":"Старый","text":"Ты помнишь, как мою куртку по району обсуждали? Я теперь все фото сперва сто раз рассматриваю.","kind":"in"}]}]},{"id":"T02","title":"Вторник, 09:04 — Лёха","chat":"Лёха (деревня)","core":[{"who":"Лёха (деревня)","text":"Здорово. Это Лёха. Старый номер дал. Не перепутал?","kind":"in"},{"who":"Лёха (деревня)","text":"Я раньше в Москве жил. Потом решил, что хватит. Купил дом за городом, развёл хозяйство. Красота, тишина.","kind":"in"},{"who":"Лёха (деревня)","text":"Щенка подобрал. Думал, будет охранять коз. Выросло что-то не то.","kind":"in"},{"who":"Лёха (деревня)","text":"В общем, волк оказался. Меня покалечил. Пока в больнице лежал, из хозяйства почти всё вынесли.","kind":"in"},{"who":"Лёха (деревня)","text":"Я обратно в Москву приехал. В квартире тише, чем там. Даже телевизор не включаю.","kind":"in"},{"who":"Лёха (деревня)","text":"А ты веришь, что можно один раз переехать и стать другим человеком?","kind":"in"}],"choices":[{"id":"A","title":"Поговорить о возвращении","echo":"Не знаю. А ты хоть рад, что обратно приехал?","set":{"village_question":"return"},"lines":[{"who":"Лёха (деревня)","text":"Рад, что здесь стены не шевелятся по ночам. А сам я — не уверен.","kind":"in"}],"note":""},{"id":"B","title":"Спросить про животное","echo":"Ты его щенком взял? Никто не заметил, что он на собаку не похож?","set":{"village_question":"wolf"},"lines":[{"who":"Лёха (деревня)","text":"Заметили. Только все потом. У нас в деревне любую плохую новость задним числом знают.","kind":"in"}],"note":""},{"id":"C","title":"Не превращать в урок","echo":"Случилось и случилось. Не надо из этого выводить правило жизни.","set":{"village_question":"plain"},"lines":[{"who":"Лёха (деревня)","text":"Хорошо сказал. А то знакомые уже требуют, чтобы я теперь мудрость излучал. Мне бы поспать.","kind":"in"}],"note":""}],"variants":[{"when":{"village_first":"welcome"},"lines":[{"who":"Лёха (деревня)","text":"Старый сказал, ты не против разговора. Это редкость.","kind":"in"}]},{"when":{"village_first":"distance"},"lines":[{"who":"Лёха (деревня)","text":"Мне сказали, что лучше не навязываться. Вот и не навязываюсь. Просто написал.","kind":"in"}]}]},{"id":"T03","title":"Вторник, 09:39 — За гаражами","chat":"Бармен","core":[{"who":"Бармен","text":"Помнишь мужика, который всё допытывался, кто ему старый счёт оплатил? Он перестал допытываться. Уехал.","kind":"in"},{"who":"Бармен","text":"Теперь другой приезжает, пьёт чай, грозится описать свою драку за гаражами в подробностях. Никто не просил, а он уже половину рассказал.","kind":"in"},{"who":"Бармен","text":"Вчера у него телефон сел. Дал твой номер, сказал, что ты не любишь длинных историй. Не знаю, за что он так тебя.","kind":"in"},{"who":"Бармен","text":"Если напишет — не говори, что я тебя предупреждал.","kind":"in"}],"choices":[{"id":"A","title":"Оставить разговор за барменом","echo":"Ты мог просто не давать мой номер.","set":{"garage_intro":"boundary"},"lines":[{"who":"Бармен","text":"Мог. Но он уже записал его на салфетке. Салфетку я не отнял — бизнес всё-таки.","kind":"in"}],"note":""},{"id":"B","title":"Спросить об очевидцах","echo":"Ты сам драку видел или он рассказывает?","set":{"garage_intro":"verify"},"lines":[{"who":"Бармен","text":"Видел только грязную куртку. Весь спектакль — с его слов. Не запоминай меня свидетелем.","kind":"in"}],"note":""},{"id":"C","title":"Пошутить","echo":"С тебя хотя бы чай за этот телефонный сервис.","set":{"garage_intro":"tea"},"lines":[{"who":"Бармен","text":"Чай будет. По прайсу. Сначала оплатишь, чтобы я ещё через двадцать лет тебя не искал.","kind":"in"}],"note":""}],"variants":[{"when":{"bar_advice":"pay"},"lines":[{"who":"Бармен","text":"Кстати, старый счёт закрыт. Не доплатили только за свежую нервотрёпку.","kind":"in"}]},{"when":{"bar_advice":"leave"},"lines":[{"who":"Бармен","text":"Счёт за ту ночь всё ещё в блокноте. Бумага удивительно живучая.","kind":"in"}]}]},{"id":"T04","title":"Вторник, 10:12 — Куртка","chat":"Гаражи","core":[{"who":"Гаражи","text":"Слушай сюда. Твой номер через бар дали. Я не жаловаться.","kind":"in"},{"who":"Гаражи","text":"На днях меня трое за гаражами остановили. Хотели показать, как надо разговаривать. Я показал, как не надо.","kind":"in"},{"who":"Гаражи","text":"Один здоровый, другой пониже, последний Васюня. У последнего железяка была. Я нож достал.","kind":"in"},{"who":"Гаражи","text":"Чем закончилось — сам не видел толком. Я уходил, снег под ногами скрипел.","kind":"in"},{"who":"Гаражи","text":"Теперь по району говорят, что я троих положил. Вот ведь люди. Сами там не были, а всё знают.","kind":"in"},{"who":"Гаражи","text":"Ты бы тоже так рассказал?","kind":"in"}],"choices":[{"id":"A","title":"Оставить факты отдельно","echo":"Я бы сказал только то, что видел. Ты сам говоришь, что исход не видел.","set":{"garage_intro_reply":"facts"},"lines":[{"who":"Гаражи","text":"Ну да. Но это не так эффектно, как если сказать «все легли».","kind":"in"}],"note":""},{"id":"B","title":"Спросить о пострадавших","echo":"Кто-нибудь вызвал помощь? Ты про Васюню что-нибудь знаешь?","set":{"garage_intro_reply":"concern"},"lines":[{"who":"Гаражи","text":"Не знаю. Утром хотел спросить, а потом решил: мне и своего вчера достаточно.","kind":"in"}],"note":""},{"id":"C","title":"Не участвовать в хвастовстве","echo":"Не хочу быть зрителем чужой драки.","set":{"garage_intro_reply":"stop"},"lines":[{"who":"Гаражи","text":"А никто и не заставляет. Просто хочется, чтоб хоть кто-то не добавлял к истории лишних трупов.","kind":"in"}],"note":""}],"variants":[{"when":{"garage_intro":"verify"},"lines":[{"who":"Гаражи","text":"Бармен, кстати, правильно сказал: он меня видел уже после. На самой драке его не было.","kind":"in"}]},{"when":{"garage_intro":"tea"},"lines":[{"who":"Гаражи","text":"Чай у него хороший. Правда, разговаривает о счёте чаще, чем я о драке.","kind":"in"}]}]},{"id":"T05","title":"Вторник, 11:08 — Дом без двери","chat":"Лёха (деревня)","core":[{"who":"Лёха (деревня)","text":"Прислали мне фотографию деревенского дома. Смешно: я свой дом по фотографии сразу не узнал.","kind":"in"},{"who":"Лёха (деревня)","text":"Сарая нет. Ворота сняли. На месте теплицы пепел. А я туда целый год каждый гвоздь вкручивал.","kind":"in"},{"who":"Лёха (деревня)","text":"Знакомый предлагает выложить это в районный канал. Мол, все увидят, что там творится.","kind":"in"},{"who":"Лёха (деревня)","text":"Я сомневаюсь. Люди посмотрят — и что? Волка мне обратно привезут?","kind":"in"},{"who":"Лёха (деревня)","text":"Ты бы как поступил?","kind":"in"}],"choices":[{"id":"A","title":"Сначала связаться с людьми на месте","echo":"Попроси конкретные фото и документы. И без имён, пока сам не разобрался.","set":{"village_photo":"verify"},"lines":[{"who":"Лёха (деревня)","text":"Хорошо. Пусть покажут, откуда это снято и когда. А то даже печку на снимке не вижу.","kind":"in"}],"note":""},{"id":"B","title":"Опубликовать историю","echo":"Если хочешь огласки, выложи. Только напиши, что знаешь лично.","set":{"village_photo":"public"},"lines":[{"who":"Лёха (деревня)","text":"Написал, как было. Волка не сфотографировал. Глядя на комментарии, это главный мой промах.","kind":"in"},{"who":"Марат (версии)","kind":"forward","from":"Лёха (деревня)","text":"Лёха рассказал о разграбленном деревенском доме. Кто и когда разобрал строения, пока неизвестно. Фотографию не прикладываю.","media":null}],"note":""},{"id":"C","title":"Оставить в прошлом","echo":"Если сил нет — не выкладывай. Тебе не обязательно устраивать публичный суд.","set":{"village_photo":"private"},"lines":[{"who":"Лёха (деревня)","text":"Да. Я устал от того, что любой мой разговор становится вопросом «а кто виноват?».","kind":"in"}],"note":""}],"variants":[]},{"id":"T06","title":"Вторник, 11:46 — Слова и последствия","chat":"Гаражи","core":[{"who":"Гаражи","text":"Короче, про драку уже в трёх чатах написали. На третьей версии я там двенадцать человек зарезал и ушёл на лыжах.","kind":"in"},{"who":"Гаражи","text":"Я на лыжах, между прочим, вообще не умею.","kind":"in"},{"who":"Гаражи","text":"Один знакомый спрашивает, знаю ли я, куда делся Васюня. Я не знаю. Человек исчез из виду — не значит, что умер.","kind":"in"},{"who":"Гаражи","text":"Чё отвечать?","kind":"in"}],"choices":[{"id":"A","title":"Предложить проверить состояние пострадавшего","echo":"Спроси, обращался ли он за помощью. Если ему плохо, пусть вызовут медиков.","set":{"garage_help":"medical"},"lines":[{"who":"Гаражи","text":"Попробую. Там теперь даже соседей по фамилиям спрашивают. Будто это районная олимпиада.","kind":"in"}],"note":""},{"id":"B","title":"Попросить передать только свидетельства","echo":"Скажи: ты видел драку, но не видел, что было после. Без похорон на словах.","set":{"garage_help":"witness"},"lines":[{"who":"Гаражи","text":"Это точно. Про то, чего не видел, лучше не умничать.","kind":"in"}],"note":""},{"id":"C","title":"Не передавать неподтверждённое","echo":"Не распространяй ничего, пока не узнаешь сам.","set":{"garage_help":"quiet"},"lines":[{"who":"Гаражи","text":"Ладно. Телефон пока выключу. Если нужен буду, в баре найдут.","kind":"in"}],"note":""}],"variants":[]},{"id":"T07","title":"Вторник, 12:30 — Одна фотография","chat":"Марат (версии)","core":[{"who":"Марат (версии)","text":"Здравствуй. У меня сегодня две новости, и обе плохие для моей репутации.","kind":"in"},{"who":"Марат (версии)","text":"Сначала история про разграбленный дом. Потом кто-то прислал рассказ про трёх убитых за гаражами.","kind":"in"},{"who":"Марат (версии)","text":"Меня прямо тянет объединить: деревня, гаражи, волк. Причём волк явно организатор.","kind":"in"},{"who":"Марат (версии)","text":"Нет, серьёзно: люди спрашивают, пересылать ли этот ужас. Как мне ответить?","kind":"in"}],"choices":[{"id":"A","title":"Разделить истории","echo":"Не связывай неизвестных людей. Про гаражи нет подтверждения смертей, по дому тоже неясно.","set":{"mara_tuesday":"separate"},"lines":[{"who":"Марат (версии)","text":"Разделю. Из двух историй получилось две. Я почему-то расстроен.","kind":"in"}],"note":""},{"id":"B","title":"Предложить проверить исходники","echo":"Попроси две независимые детали и даты. Потом решай, писать ли что-то.","set":{"mara_tuesday":"verify"},"lines":[{"who":"Марат (версии)","text":"Проверил. Даты у них разные. Даже области разные. Публикацию отменяю.","kind":"in"}],"note":""},{"id":"C","title":"Разрешить переслать, но с оговоркой","echo":"Можешь переслать, но явно пометь, что это неподтверждённые рассказы.","set":{"mara_tuesday":"spread"},"lines":[{"who":"Марат (версии)","text":"Пометил. Через пятнадцать минут пометку обрезали, оставили только слово «убиты». Великолепно.","kind":"in"}],"note":""}],"variants":[{"when":{"nail_publicity":"spread","mara_nail":"leave"},"lines":[{"who":"Марат (версии)","text":"После той истории с человеком без двух пальцев у меня вообще-то кредит доверия почти закончился.","kind":"in"}]},{"when":{"village_photo":"public"},"lines":[{"who":"Марат (версии)","text":"Про дом пришло пересланное сообщение от Лёхи. Хоть теперь ясно, с чьих слов началась история.","kind":"in"}]},{"when":{"village_photo":"private"},"lines":[{"who":"Марат (версии)","text":"Фотографию дома мне не присылали. Обсуждают то, чего никто из компании не видел.","kind":"in"}]}]},{"id":"T08","title":"Вторник, 13:11 — Не тот доктор","chat":"Док","core":[{"who":"Док","text":"Мне сейчас с незнакомого номера прислали: «Васюня живой?» Без фотографии, без фамилии, без чего-либо.","kind":"in"},{"who":"Док","text":"Слушай, я патологоанатом. По вопросам здоровья живых есть другие специалисты. Это у нас важное профессиональное разграничение.","kind":"in"},{"who":"Док","text":"А тут ещё кто-то предлагает по снимку определить, кто ударил первым. Тебе тоже такое пишут?","kind":"in"}],"choices":[{"id":"A","title":"Не пересылать непроверенную историю","echo":"Пишут. Но я не буду присылать тебе чужую драку.","set":{"doc_tuesday":"private"},"lines":[{"who":"Док","text":"И правильно. У меня после работы достаточно чужих историй, даже когда я дома.","kind":"in"}],"note":""},{"id":"B","title":"Передать осторожный вопрос","echo":"Спросили только о человеке по имени Васюня. Отвечать не обязан.","set":{"doc_tuesday":"ask"},"lines":[{"who":"Док","kind":"forward","from":"Гаражи","text":"После драки за гаражами участник не знает, что стало с Васюней. Подтверждения смерти нет.","media":null},{"who":"Док","text":"Официальный ответ: по слову «Васюня» я не узнаю ни живого, ни мёртвого. Передавай.","kind":"in"}],"note":""},{"id":"C","title":"Ответить бытовым вопросом","echo":"Тебя хотя бы дома никто не просит справки о жизни?","set":{"doc_tuesday":"joke"},"lines":[{"who":"Док","text":"Просят. Моя мать считает, что я должен лучше всех знать, где у неё ключи. Наука пока бессильна.","kind":"in"}],"note":""}],"variants":[]},{"id":"T09","title":"Вторник, 14:06 — Обратно в город","chat":"Лёха (деревня)","core":[{"who":"Лёха (деревня)","text":"Нашёл старую фотографию. Я на ней стою у ворот, за спиной дом, рядом щенок — ну так я тогда думал.","kind":"in"},{"who":"Лёха (деревня)","text":"Показал другу. Он сказал, что у зверя ещё тогда взгляд подозрительный.","kind":"in"},{"who":"Лёха (деревня)","text":"Мне не хватает даже не дома. Ощущения, что вот сейчас всё сделаю своими руками, и больше никуда не надо.","kind":"in"},{"who":"Лёха (деревня)","text":"Хотел снова туда съездить, посмотреть своими глазами. Что скажешь?","kind":"in"}],"choices":[{"id":"A","title":"Не ехать одному, если тяжело","echo":"Если поедешь, возьми знакомого. Тебе необязательно там всё разбирать самому.","set":{"village_trip":"together"},"lines":[{"who":"Лёха (деревня)","text":"Старого позову. Он всё равно собирался заехать ко мне.","kind":"in"}],"note":""},{"id":"B","title":"Уточнить цель поездки","echo":"Тебе нужны документы или просто увидеть место?","set":{"village_trip":"purpose"},"lines":[{"who":"Лёха (деревня)","text":"Сам не знаю. Возможно, мне и нужен ответ, что дома там больше нет.","kind":"in"}],"note":""},{"id":"C","title":"Не советовать возвращаться","echo":"Не заставляй себя. Ты уже дома, пусть пока этого хватит.","set":{"village_trip":"stay"},"lines":[{"who":"Лёха (деревня)","text":"Вот. Я впервые за долгое время услышал, что можно просто никуда не ехать.","kind":"in"}],"note":""}],"variants":[{"when":{"village_photo":"verify"},"lines":[{"who":"Лёха (деревня)","text":"Снимок с датой прислали. Дом тот самый. Но на фотографии чужая табличка, которую я точно не вешал.","kind":"in"}]},{"when":{"village_photo":"public"},"lines":[{"who":"Лёха (деревня)","text":"В комментариях уже два человека уверяют, что это не мой дом. Один предлагает купить мне другого щенка.","kind":"in"}]},{"when":{"village_photo":"private"},"lines":[{"who":"Лёха (деревня)","text":"Никому фото не отправил. Сам смотрю и никак не могу закрыть галерею.","kind":"in"}]}]},{"id":"T10","title":"Вторник, 15:10 — Опять деньги","chat":"Бармен","core":[{"who":"Бармен","text":"В баре у меня как обычно: один спрашивает про старый неоплаченный счёт, другой — не найдётся ли записи драки у гаражей.","kind":"in"},{"who":"Бармен","text":"Камеры у меня смотрят на вход в бар. Гаражи оттуда не видно. Но человеку это объяснить трудно.","kind":"in"},{"who":"Бармен","text":"Он ещё предложил устроить встречу «всех очевидцев» у меня за столом. Мне такая вечеринка не нужна.","kind":"in"},{"who":"Бармен","text":"Что ему передать?","kind":"in"}],"choices":[{"id":"A","title":"Сказать правду про камеры","echo":"Передай, что камеры на бар, а не на гаражи. Ты не свидетель драки.","set":{"bar_garage":"facts"},"lines":[{"who":"Бармен","text":"Сказал. Пришёл ответ: «Ну хоть чай есть?» Чай, как видишь, полезнее видеозаписи.","kind":"in"}],"note":""},{"id":"B","title":"Отказать в собрании","echo":"Не собирай их у себя. Пусть разбираются там, где это уместно.","set":{"bar_garage":"refuse"},"lines":[{"who":"Бармен","text":"Уже отказал. У меня пятница занята свадьбой. До свадьбы дожить бы.","kind":"in"}],"note":""},{"id":"C","title":"Переслать ему слова Гаражей без сенсации","echo":"Скажи ему: человек не знает, что произошло после драки.","set":{"bar_garage":"forward"},"lines":[{"who":"Бармен","kind":"forward","from":"Гаражи","text":"Рассказчик сам не знает, что стало с Васюней после драки. Это не сообщение о гибели.","media":null},{"who":"Бармен","text":"Переслал. Надеюсь, теперь больше никто не будет требовать у меня протокол гаражей.","kind":"in"}],"note":""}],"variants":[{"when":{"bar_advice":"pay"},"lines":[{"who":"Бармен","text":"И да, старый должник сегодня принёс мне открытку. Денег не принёс. Но старый счёт уже закрыт.","kind":"in"}]}]},{"id":"T11","title":"Вторник, 16:22 — Эффект телефона","chat":"Гаражи","core":[{"who":"Гаражи","text":"Всё. Теперь пишут, будто я драку в интернете сам выкладывал. Я выложил только фотографию рукава. Там грязь.","kind":"in"},{"who":"Гаражи","text":"И один мне прислал чью-то справку. Фамилию замазал. Я её даже открыть не хочу.","kind":"in"},{"who":"Гаражи","text":"Он спрашивает, подтверждаю ли я всё, что про меня пишут. Ну я же сам сказал, что не видел, что с Васюней потом было.","kind":"in"},{"who":"Гаражи","text":"Ты как думаешь, стоит отвечать?","kind":"in"}],"choices":[{"id":"A","title":"Заявить только проверенное","echo":"Напиши, что не знаешь исхода и что чужих справок не видел.","set":{"garage_statement":"truth"},"lines":[{"who":"Гаражи","text":"Написал. Три предложения вышло. Даже непохоже на меня. Но по крайней мере всё моё.","kind":"in"}],"note":""},{"id":"B","title":"Поддержать громкую версию","echo":"Можешь написать, как слышал, но это не будет подтверждением.","set":{"garage_statement":"loud"},"lines":[{"who":"Гаражи","text":"Вот беда: люди читают «слышал» как «видел». Теперь опять про лыжи спрашивают.","kind":"in"}],"note":""},{"id":"C","title":"Не давать комментариев","echo":"Не отвечай на всё подряд. Если есть серьёзные вопросы, отвечай тем, кто разбирается.","set":{"garage_statement":"silence"},"lines":[{"who":"Гаражи","text":"Телефон положу. Не думал, что драку можно продолжить одной перепиской.","kind":"in"}],"note":""}],"variants":[{"when":{"garage_help":"medical"},"lines":[{"who":"Гаражи","text":"Через знакомого проверил, куда обратиться за помощью пострадавшим. Это пока всё, что могу сказать без выдумок.","kind":"in"}]},{"when":{"garage_help":"quiet"},"lines":[{"who":"Гаражи","text":"Я никому ничего не передал. От этого в районных чатах почему-то стало только громче.","kind":"in"}]}]},{"id":"T12","title":"Вторник, 17:04 — Соседи помнят всё","chat":"Марат (версии)","core":[{"who":"Марат (версии)","text":"Докладываю: мой районный чат пережил вторник. Пока что.","kind":"in"},{"who":"Марат (версии)","text":"Кто-то опять связал гаражи с человеком без двух пальцев. Я уже устал объяснять, что у одного нет двух пальцев, у другого есть куртка — и всё.","kind":"in"},{"who":"Марат (версии)","text":"В комментариях теперь просят назвать имя Васюни. Я не знаю. И не хочу добывать.","kind":"in"},{"who":"Марат (версии)","text":"Мне исправлять старое сообщение?","kind":"in"}],"choices":[{"id":"A","title":"Исправить публично","echo":"Исправь там же: нет подтверждений, что кто-то погиб.","set":{"rumor_correction":"public"},"lines":[{"who":"Марат (версии)","text":"Написал. Мне пришёл один лайк и девять сообщений, что я скрываю правду. Прогресс.","kind":"in"}],"note":""},{"id":"B","title":"Ограничиться частным уточнением","echo":"Напиши тем, кому сам разослал. Не надо собирать ещё аудиторию.","set":{"rumor_correction":"private"},"lines":[{"who":"Марат (версии)","text":"В личку и отправил. Мне ответили, что уже переслали другим. Так работает мой маленький издательский дом.","kind":"in"}],"note":""},{"id":"C","title":"Не вмешиваться","echo":"Ты сам выбирай, что исправлять. Только больше не выдумывай.","set":{"rumor_correction":"none"},"lines":[{"who":"Марат (версии)","text":"Ладно. Поставлю телефон экраном вниз. Впервые без самого интересного комментария.","kind":"in"}],"note":""}],"variants":[{"when":{"mara_tuesday":"spread"},"lines":[{"who":"Марат (версии)","text":"Я действительно разослал рассказ. Теперь исправляю уже не один чат, а целый район.","kind":"in"}]},{"when":{"mara_tuesday":"verify"},"lines":[{"who":"Марат (версии)","text":"Хорошо, что я тогда хотя бы проверил даты. Волка с гаражами объединять перестал.","kind":"in"}]}]},{"id":"T13","title":"Вторник, 17:57 — Восемь не значит двенадцать","chat":"Восемь","core":[{"who":"Восемь","text":"Чудесная жизнь: кто-то за гаражами достал нож, а мне теперь пишут, не моими ли руками это сделано.","kind":"in"},{"who":"Восемь","text":"Я в тот день ножницы покупал. И нет, это не алиби на все преступления мира.","kind":"in"},{"who":"Восемь","text":"Скоро у меня будет отдельная подписка на объяснения людям, что восемь — это количество пальцев, а не номер бригады.","kind":"in"},{"who":"Восемь","text":"Что ему, Марату твоему, ответить?","kind":"in"}],"choices":[{"id":"A","title":"Написать коротко","echo":"Напиши, что эти события нельзя связывать без доказательств.","set":{"nail_tuesday":"facts"},"lines":[{"who":"Восемь","text":"Написал. Слишком разумный ответ для моего характера. Надо полежать.","kind":"in"}],"note":""},{"id":"B","title":"Попросить не участвовать в слухах","echo":"Не трать на него время, если не хочешь.","set":{"nail_tuesday":"rest"},"lines":[{"who":"Восемь","text":"Согласен. Пойду лучше ножницы искать. Опять куда-то положил.","kind":"in"}],"note":""},{"id":"C","title":"Оставить выбор Восьми","echo":"Сам реши. Это про тебя, а не про меня.","set":{"nail_tuesday":"autonomy"},"lines":[{"who":"Восемь","text":"Своим решением выбираю чай. Когда всё началось, я ещё его не успел заварить.","kind":"in"}],"note":""}],"variants":[{"when":{"nail_publicity":"private"},"lines":[{"who":"Восемь","text":"И спасибо, что мой рассказ не разослал. Хоть один человек способен оставить вещь на месте.","kind":"in"}]},{"when":{"mara_nail":"retract"},"lines":[{"who":"Восемь","text":"За предыдущую ерунду Марат вроде извинялся. Я это запомнил. Но не простил за него остальных.","kind":"in"}]}]},{"id":"T14","title":"Вторник, 19:06 — Без красивого финала","chat":"Гаражи","core":[{"who":"Гаражи","text":"Мне сегодня звонили. Про Васюню три версии: умер, уехал, ходит по району с перевязанной рукой.","kind":"in"},{"who":"Гаражи","text":"Я его после драки не видел. А теперь и версии толком не отличишь — кто сам видел, кто у соседа спросил.","kind":"in"},{"who":"Гаражи","text":"Других двоих по-прежнему не знаю где искать. И искать, честно, не собираюсь.","kind":"in"},{"who":"Гаражи","text":"Вчера я был убийца района. Сегодня — мужик с грязным рукавом. Это даже лучше.","kind":"in"},{"who":"Гаражи","text":"Ты бы что на моём месте сказал людям?","kind":"in"}],"choices":[{"id":"A","title":"Отметить подтверждённое","echo":"Скажи, кто именно передал сообщение и что сам не проверял.","set":{"garage_outcome":"careful"},"lines":[{"who":"Гаражи","text":"Написал. Меня назвали скучным. Вот уж чего не ожидал после ножевой драки.","kind":"in"}],"note":""},{"id":"B","title":"Не общаться с публикой","echo":"Не обязан ничего рассказывать в районном чате.","set":{"garage_outcome":"private"},"lines":[{"who":"Гаражи","text":"Не буду. Лучше дойти до дома и выбросить эту куртку.","kind":"in"}],"note":""},{"id":"C","title":"Попросить заняться последствиями","echo":"Если кто-то пострадал, выясняйте это через тех, кто вправе разбираться, а не через слухи.","set":{"garage_outcome":"official"},"lines":[{"who":"Гаражи","text":"Уже понял. И про рукав расскажу, если спросят официально. Там и без меня хлопот хватает.","kind":"in"}],"note":""}],"variants":[{"when":{"garage_help":"medical","garage_statement":"truth"},"lines":[{"who":"Гаражи","text":"Тот знакомый, которого я просил узнать о помощи, поговорил с Васюней. Говорит, он живой и злой, рука перевязана. Сам я его не видел.","kind":"in"}]},{"when":{"garage_help":"quiet","garage_statement":"loud"},"lines":[{"who":"Гаражи","text":"После моих разговоров люди решили, что трое точно погибли. А я сам ничего не выяснил. Отлично устроился.","kind":"in"}]},{"when":{"rumor_correction":"public"},"lines":[{"who":"Гаражи","text":"Марат написал исправление. Впервые полезный районный пост про меня.","kind":"in"}]}]},{"id":"T15","title":"Вторник, 20:15 — Обычная поездка","chat":"Лёха (деревня)","core":[{"who":"Лёха (деревня)","text":"Я тут понял: если всё-таки поеду, не хочу на месте искать смысл. Хочу просто посмотреть, что осталось.","kind":"in"},{"who":"Лёха (деревня)","text":"Старый согласился съездить со мной, если решусь. Сказал, не будет рассказывать, как в девяностые было лучше.","kind":"in"},{"who":"Лёха (деревня)","text":"А в городе у меня уже третий день сосед снизу телевизор орёт. Обычная жизнь. Мне даже понравилось.","kind":"in"},{"who":"Лёха (деревня)","text":"Какой совет на завтра?","kind":"in"}],"choices":[{"id":"A","title":"Не торопить его","echo":"Поезжай, когда будешь готов. Не надо доказывать ничего знакомым.","set":{"village_plan":"ready"},"lines":[{"who":"Лёха (деревня)","text":"Уговорил. Сначала нормально поем, потом решу.","kind":"in"}],"note":""},{"id":"B","title":"Предложить опереться на друга","echo":"Если едешь — пусть Старый будет рядом. Просто как друг.","set":{"village_plan":"friend"},"lines":[{"who":"Лёха (деревня)","text":"Да. Мы столько лет знали друг друга, а в машине ни разу просто так не сидели.","kind":"in"}],"note":""},{"id":"C","title":"Сосредоточиться на настоящем","echo":"Может, пока займись комнатой здесь. В деревне дом уже не восстановить за ночь.","set":{"village_plan":"city"},"lines":[{"who":"Лёха (деревня)","text":"Сделаю. Куплю полку. В старом доме у меня тоже всё начиналось с полки.","kind":"in"}],"note":""}],"variants":[{"when":{"village_trip":"together"},"lines":[{"who":"Лёха (деревня)","text":"Ты тогда предложил не ехать одному. Старый действительно согласился.","kind":"in"}]},{"when":{"village_trip":"stay"},"lines":[{"who":"Лёха (деревня)","text":"Сегодня не поехал. И от этого ничего не рухнуло, представляешь?","kind":"in"}]}]},{"id":"T16","title":"Вторник, 21:03 — На Филиппинах","chat":"Шурик","core":[{"who":"Шурик","text":"Добрый вечер. У вас там день, наверное. У меня здесь дождь с громом.","kind":"in"},{"who":"Шурик","text":"Сосед купил собаку. Сказал, что она охотничья. Я спросил: на кого охотится? Он говорит: на тапки.","kind":"in"},{"who":"Шурик","text":"Сижу, думаю. Можно же всю жизнь куда-то переезжать, а сосед всё равно найдёт способ принести тебе тапки в зубах.","kind":"in"},{"who":"Шурик","text":"Ты как, без больших происшествий?","kind":"in"}],"choices":[{"id":"A","title":"Ответить коротко","echo":"Пока жив, и это уже неплохой итог вторника.","set":{"shura_tuesday":"short"},"lines":[{"who":"Шурик","text":"Я тоже. Так что у нас международный клуб живых людей.","kind":"in"}],"note":""},{"id":"B","title":"Поделиться про Лёху","echo":"Один знакомый вернулся из деревни. Там было не очень.","set":{"shura_tuesday":"village"},"lines":[{"who":"Шурик","text":"Пусть вернётся в себя сначала. Местность тут редко главное.","kind":"in"}],"note":""},{"id":"C","title":"Спросить про собаку","echo":"А тапки хоть вернул соседу?","set":{"shura_tuesday":"dog"},"lines":[{"who":"Шурик","text":"Вернул. Собака обиделась. Кажется, это самый сложный конфликт моей недели.","kind":"in"}],"note":""}],"variants":[{"when":{"shura_monday":"fish"},"lines":[{"who":"Шурик","text":"Рыба вчера не клюнула. Зато крючки теперь у меня в идеальном порядке.","kind":"in"}]}]},{"id":"T17","title":"Вторник, 22:07 — Где разошлись","chat":"Марат (версии)","core":[{"who":"Марат (версии)","text":"Конец дня. Проверил свои сообщения. Из двадцати двух «точных свидетельств» осталось одно: на остановке кто-то оставил пакет с яблоками.","kind":"in"},{"who":"Марат (версии)","text":"Я не шучу. Даже с яблоками выяснилось, что это не там, где мне написали.","kind":"in"},{"who":"Марат (версии)","text":"Лёху уже в комментариях назвали владельцем дикого зверя, который натравил его на деревню. Такого я не писал.","kind":"in"},{"who":"Марат (версии)","text":"Стоит ли отправить ему скриншоты? Или дать человеку спокойно жить?","kind":"in"}],"choices":[{"id":"A","title":"Отправить только проверенную часть","echo":"Сначала уточни, что это вообще его дом. Отправлять обвинения без источника не надо.","set":{"mara_late":"check"},"lines":[{"who":"Марат (версии)","text":"Проверил. Оказалось, два снимка из разных деревень. Отправлю ему только то, что касается его дома.","kind":"in"}],"note":""},{"id":"B","title":"Предупредить лично","echo":"Напиши ему коротко, что слухи есть, но сами обвинения не пересылай.","set":{"mara_late":"warn"},"lines":[{"who":"Марат (версии)","text":"Так и написал. Человек ответил: «Я знаю». Потом ещё: «Спасибо». Два слова за весь день.","kind":"in"}],"note":""},{"id":"C","title":"Остановить переписку","echo":"Не делай его ответственным за чужой интернет. Лучше ничего не присылай.","set":{"mara_late":"leave"},"lines":[{"who":"Марат (версии)","text":"Ладно. Сегодня впервые удалю своё сообщение ещё до отправки.","kind":"in"}],"note":""}],"variants":[{"when":{"village_photo":"public","mara_tuesday":"spread"},"lines":[{"who":"Марат (версии)","text":"А началось всё с сообщения от Лёхи, которое кто-то уже пересказывает от своего имени. Хорошая наука.","kind":"in"}]},{"when":{"rumor_correction":"public"},"lines":[{"who":"Марат (версии)","text":"По гаражам исправление разместил. От него почти нет удовольствия. Значит, полезно.","kind":"in"}]}]},{"id":"T18","title":"Вторник, 23:14 — Обычный ужин","chat":"Лёха (деревня)","core":[{"who":"Лёха (деревня)","text":"Решил написать перед сном. Купил хлеба, картошки, соль. Готовил ужин. Ничего не случилось.","kind":"in"},{"who":"Лёха (деревня)","text":"Сосед орал телевизором, потом затих. Я впервые за долгое время не прислушивался к шуму за дверью.","kind":"in"},{"who":"Лёха (деревня)","text":"А ведь когда-то я тоже думал, что у меня будет просто дом, собака и огород.","kind":"in"},{"who":"Лёха (деревня)","text":"Ладно. До завтра. Не надо искать в этом никакой морали.","kind":"in"}],"choices":[{"id":"A","title":"Пожелать спокойной ночи","echo":"Спокойной ночи, Лёх. Завтра просто среда.","set":{"tuesday_end":"night"},"lines":[{"who":"Лёха (деревня)","text":"Надеюсь. Не люблю, когда календарь начинает фантазировать.","kind":"in"}],"note":""},{"id":"B","title":"Попросить написать после поездки","echo":"Если поедешь к дому, дай знать, как прошло. Без фотоотчёта.","set":{"tuesday_end":"report"},"lines":[{"who":"Лёха (деревня)","text":"Напишу. Сфотографировать мне сейчас и так хочется меньше всего.","kind":"in"}],"note":""},{"id":"C","title":"Остаться в разговоре","echo":"Знаешь, можно иногда просто поговорить. Без повода.","set":{"tuesday_end":"talk"},"lines":[{"who":"Лёха (деревня)","text":"Можно. Я пока об этом плохо помню, но надо привыкать.","kind":"in"}],"note":""}],"variants":[{"when":{"village_photo":"public","mara_late":"warn"},"lines":[{"who":"Лёха (деревня)","text":"Марат прислал предупреждение про слухи. Я ему сказал, что уже видел. Спасибо, что без ссылок на чужую грязь.","kind":"in"}]},{"when":{"village_photo":"public","mara_tuesday":"spread","mara_late":"leave"},"lines":[{"who":"Лёха (деревня)","text":"Обсуждают мой дом без меня. Не люблю интернет. Он никогда не живёт в том, что показывает.","kind":"in"}]},{"when":{"village_trip":"together","village_plan":"friend"},"lines":[{"who":"Лёха (деревня)","text":"Со Старым решили: если поедем, без свидетелей, без прямых эфиров. Просто вдвоём посмотрим.","kind":"in"}]},{"when":{"village_trip":"stay","village_plan":"city"},"lines":[{"who":"Лёха (деревня)","text":"Полку прикрутил. Очень хорошо держится. Не нужен мне пока другой дом.","kind":"in"}]},{"when":{"garage_help":"medical","rumor_correction":"public"},"lines":[{"who":"Лёха (деревня)","text":"И про вашего гаражного мужика сегодня уже пишут меньше. Наверное, все нашли себе другие новости.","kind":"in"}]}]},{"id":"W01","title":"Среда, 08:17 — Коробка под стойкой","chat":"Бармен","core":[{"who":"Бармен","text":"Доброе. У меня вчера под стойкой нашли коробку с кассетами. Я даже не знаю, откуда там магнитофон. Кассеты нашлись, магнитофон — нет.","kind":"in"},{"who":"Бармен","text":"На одной наклейка: «2007. Не стирать». У нас в баре тогда даже этой стойки ещё не было.","kind":"in"},{"who":"Бармен","text":"Человек, который оцифровывает старые записи, спрашивает, можно ли тебе написать. Я говорю: смотря сколько он предложит за чай.","kind":"in"},{"who":"Бармен","text":"Ты в такие древности вообще полезешь?","kind":"in"}],"choices":[{"id":"A","title":"Послушать, но без публикаций","echo":"Пусть напишет. Только сперва без чужих фамилий и районных чатов.","set":{"archive_intro":"private"},"lines":[{"who":"Бармен","text":"Годится. Наклейку ему и отдам. Фамилий на коробке нет, только пятна от кофе.","kind":"in"}],"note":""},{"id":"B","title":"Выяснить происхождение","echo":"Сначала спроси, чей магнитофон и кто принёс коробку.","set":{"archive_intro":"source"},"lines":[{"who":"Бармен","text":"У нас в книге находок этого нет. Но книгу я завёл три года назад. Историк из меня среднего качества.","kind":"in"}],"note":""},{"id":"C","title":"Не брать чужой архив","echo":"Зачем это мне? Отдай тому, кто принёс. Если найдётся.","set":{"archive_intro":"distance"},"lines":[{"who":"Бармен","text":"Разумный подход. Передам, чтобы тебя не делали хранителем семейной памяти. Он всё равно хочет спросить кое-что.","kind":"in"}],"note":""}],"variants":[{"when":{"bar_advice":"pay"},"lines":[{"who":"Бармен","text":"И не напоминай про мой старый счёт. Его уже закрыли, а люди всё равно приносят мне бумаги, как бухгалтеру.","kind":"in"}]},{"when":{"bar_advice":"leave"},"lines":[{"who":"Бармен","text":"После старой истории со счётом я вообще стараюсь ничего лишнего не хранить. Но коробка уже тут.","kind":"in"}]}]},{"id":"W02","title":"Среда, 09:03 — Два голоса","chat":"Архив","core":[{"who":"Архив","text":"Добрый день. Я оцифровываю кассеты для частных коллекций. Бармен дал ваш контакт, но номер я сохранил без имени.","kind":"in"},{"who":"Архив","text":"Сначала техническое: дата «2007» написана маркером. Это не экспертиза и даже не доказательство года записи.","kind":"in"},{"who":"Архив","text":"На записи два человека. Один перечисляет знакомых, с которыми намерен расправиться. Второй возражает. Есть упоминание гантели.","kind":"in"},{"who":"Архив","text":"В конце того же носителя другой фрагмент: голос уже говорит о случившемся и просит остановиться. Упоминает Лёху и Данилку.","kind":"in"},{"who":"Архив","text":"Мне переслать краткую опись, но кому?","kind":"in"}],"choices":[{"id":"A","title":"Оставить опись только здесь","echo":"Напиши мне, что слышно, без записи и голосов. Пока не пересылай никому.","set":{"tape_scope":"private"},"lines":[{"who":"Архив","text":"Сделаю две карточки: намерение и последствия. Не называю одну другую доказательством.","kind":"in"}],"note":""},{"id":"B","title":"Спросить о совпадающих деталях","echo":"Сначала сравни имена, гантель и последовательность. Не делай вывод по дате на коробке.","set":{"tape_scope":"verify"},"lines":[{"who":"Архив","text":"Вот за это люблю работу. Можно сравнить вещи, не придумывая людей. Сверю отметки на плёнке.","kind":"in"}],"note":""},{"id":"C","title":"Разрешить короткое описание знакомому","echo":"Только короткую опись. Сам звук никуда пока не раздавай.","set":{"tape_scope":"summary"},"lines":[{"who":"Архив","text":"Краткую опись сделаю. Отдельно напишу, что личности участников не подтверждены.","kind":"in"}],"note":""}],"variants":[{"when":{"archive_intro":"distance"},"lines":[{"who":"Архив","text":"Бармен предупредил, что вы не собираете чужие беды. Не предлагаю ничего расследовать. Мне нужна реакция на сохранность.","kind":"in"}]}]},{"id":"W03","title":"Среда, 09:44 — Кто ещё помнит девяностые","chat":"Старый","core":[{"who":"Старый","text":"Бармен мне про кассеты рассказал. Сказал, 2007-й. Хороший год был — я тогда ещё пытался выглядеть моложе.","kind":"in"},{"who":"Старый","text":"У меня куртка из девяносто четвёртого, у них запись из две тысячи седьмого. Уже жду, когда какой-нибудь долбоёб объявит это одним уголовным делом.","kind":"in"},{"who":"Старый","text":"Мне опись прислать? Или я тогда опять весь день проведу в телефоне?","kind":"in"}],"choices":[{"id":"A","title":"Дать краткую опись","echo":"Могу переслать текст, только без записей и чужих имён.","set":{"old_archive":"summary"},"lines":[{"who":"Старый","kind":"forward","from":"Архив","text":"На кассете два фрагмента: разговор перед нападением и свидетельский голос после. Личности и год по одной надписи не доказаны.","media":null},{"who":"Старый","text":"Прочитал. Значит, про мою куртку пока никто не говорит. Уже праздник.","kind":"in"}],"note":""},{"id":"B","title":"Оставить в стороне","echo":"Тебя это никак не касается. Давай не тащить ещё и куртку.","set":{"old_archive":"off"},"lines":[{"who":"Старый","text":"Отлично. Пойду куплю хлеба, пока из него не сделали свидетельство.","kind":"in"}],"note":""},{"id":"C","title":"Спросить, что он знает точно","echo":"Ты сам встречал кого-то из этих людей? Не по слухам.","set":{"old_archive":"ask"},"lines":[{"who":"Старый","text":"Никого. И это единственный факт, который я готов подтвердить своей подписью.","kind":"in"}],"note":""}],"variants":[{"when":{"jacket_route":"share"},"lines":[{"who":"Старый","text":"Я ещё помню, как в прошлый раз мне устроили расследование по фотографии чужой куртки. Повторять не надо.","kind":"in"}]}]},{"id":"W04","title":"Среда, 10:19 — Картинка с чужого телефона","chat":"Гаражи","core":[{"who":"Гаражи","text":"Слушай. Тот районный чат, где про меня писали, нашёл новую игрушку. Старая запись, 2007 год, гантель, какие-то близнецы.","kind":"in"},{"who":"Гаражи","text":"А ещё мне незнакомый человек написал: «Мы троих перепутали — чё такого». Я думал, он про нашу драку. Оказалось, нет.","kind":"in"},{"who":"Гаражи","text":"Сейчас перешлю тебе его сообщение. Только не перепутай, кто его сказал.","kind":"in"},{"who":"Гаражи","kind":"forward","from":"Лоси","text":"Трое были похожи, адрес совпадал, машина такая же. Ошибся, бывает. Чего вы все пристали?","media":null},{"who":"Гаражи","text":"Он говорит, через тебя можно передать ответ. Я номер ему не давал. Что написать?","kind":"in"}],"choices":[{"id":"A","title":"Не брать роль посредника","echo":"Я его не знаю. Не буду решать за него и за тех троих.","set":{"moose_intro":"distance"},"lines":[{"who":"Гаражи","text":"Вот и я не знаю. Отвечу, что у меня магазин справок о чужих драках не открыт.","kind":"in"}],"note":""},{"id":"B","title":"Попросить не смешивать истории","echo":"Скажи ему: история с троими — не моя драка и не запись из 2007-го.","set":{"moose_intro":"separate"},"lines":[{"who":"Гаражи","text":"Написал. Он поставил реакцию. Смысл реакции не понял, но это уже его проблема.","kind":"in"}],"note":""},{"id":"C","title":"Разрешить контакт без пересылки фото","echo":"Если хочет поговорить, пусть сам пишет. Без адресов и снимков людей.","set":{"moose_intro":"contact"},"lines":[{"who":"Гаражи","text":"Передал. Предупредил, что у тебя не платная приёмная по ошибкам.","kind":"in"}],"note":""}],"variants":[{"when":{"rumor_correction":"public"},"lines":[{"who":"Гаражи","text":"Марат вроде научился писать опровержения. Теперь бы ещё научить читать тех, кто репостит.","kind":"in"}]},{"when":{"garage_outcome":"private"},"lines":[{"who":"Гаражи","text":"Про прошлую драку сегодня никто не спрашивал. Считай, день удался.","kind":"in"}]}]},{"id":"W05","title":"Среда, 11:02 — Не те люди","chat":"Лоси","core":[{"who":"Лоси","text":"Ты тот самый, кому всякие знакомые пишут? Мне тут сказали, ты умеешь без криков разговаривать.","kind":"in"},{"who":"Лоси","text":"У меня история простая. Надо было троих найти. Нашёл троих. Адрес подходил, машина тоже. Потом выяснилось, что это были не те трое.","kind":"in"},{"who":"Лоси","text":"А мне теперь читают лекцию, как будто они сами никогда не косячили.","kind":"in"},{"who":"Лоси","text":"У меня вообще дел дохрена. Надо ещё одному Валере ответить. Он уже третий раз пишет.","kind":"in"},{"who":"Лоси","text":"Ты бы что сказал на моём месте?","kind":"in"}],"choices":[{"id":"A","title":"Не оправдывать ошибку","echo":"Что трое не те — это не мелочь. И твоих знакомых ошибки ничего не меняют.","set":{"moose_attitude":"responsibility"},"lines":[{"who":"Лоси","text":"Да понял я, что не мелочь. Не надо это слово повторять. Просто от тебя лекции не ожидал.","kind":"in"}],"note":""},{"id":"B","title":"Спросить, кто проверял данные","echo":"Кто вообще сказал, что адрес и машина те? И кто это проверил?","set":{"moose_attitude":"facts"},"lines":[{"who":"Лоси","text":"Все говорили «проверено». Когда выяснилось, что нет, все резко перестали говорить.","kind":"in"}],"note":""},{"id":"C","title":"Отказаться участвовать","echo":"Я не собираюсь оценивать такую историю по переписке.","set":{"moose_attitude":"distance"},"lines":[{"who":"Лоси","text":"Ну ладно. Хоть не отправил мне голосовое на двадцать минут.","kind":"in"}],"note":""}],"variants":[{"when":{"moose_intro":"separate"},"lines":[{"who":"Лоси","text":"Гаражи сказал, что ты не любишь, когда чужие истории смешивают. Это хоть какая-то полезная привычка.","kind":"in"}]},{"when":{"moose_intro":"distance"},"lines":[{"who":"Лоси","text":"Мне уже передали, что ты в дела не лезешь. Я тут всего на минуту.","kind":"in"}]}]},{"id":"W06","title":"Среда, 11:39 — Опись не протокол","chat":"Архив","core":[{"who":"Архив","text":"Проверил два фрагмента. Есть повторяющиеся имена и предмет. На первом голос ещё обсуждает намерение, на втором — уже последствия.","kind":"in"},{"who":"Архив","text":"Это сильная внутренняя связь. Но по одному носителю нельзя установить личности голосов и судьбу свидетеля.","kind":"in"},{"who":"Архив","text":"Марат пишет мне в соцсетях: «Доказательства на новую районную группировку». Почему люди так любят слово «доказательства»?","kind":"in"},{"who":"Архив","text":"Что ему отвечать?","kind":"in"}],"choices":[{"id":"A","title":"Передать ограниченную опись","echo":"Передай краткий текст с оговорками. Не отправляй запись.","set":{"tape_to_marat":"qualified"},"lines":[{"who":"Марат (версии)","kind":"forward","from":"Архив","text":"Два фрагмента одной записи: план нападения и голос очевидца после него. Повторяются Лёха, Данилка и гантель. Год на коробке и личности не проверены.","media":null},{"who":"Архив","text":"Переслал с оговоркой. Он спросил, где перечень участников. Не стал отвечать.","kind":"in"}],"note":""},{"id":"B","title":"Не передавать","echo":"Ничего не отдавай. Если он уже придумал группировку, опись ему не поможет.","set":{"tape_to_marat":"none"},"lines":[{"who":"Архив","text":"Остановился. Сохранил только рабочую заметку. Никакого общего чата.","kind":"in"}],"note":""},{"id":"C","title":"Разрешить только факт связи эпизодов","echo":"Можно сказать лишь, что два фрагмента про один эпизод. Без имен и адресов.","set":{"tape_to_marat":"connection"},"lines":[{"who":"Марат (версии)","kind":"forward","from":"Архив","text":"На одной записи два тематически связанных фрагмента. Личности и дата не подтверждены.","media":null},{"who":"Архив","text":"Отправил короткую формулировку. Насколько он её сократит, уже вопрос к нему.","kind":"in"}],"note":""}],"variants":[{"when":{"tape_scope":"verify"},"lines":[{"who":"Архив","text":"Хорошо, что ты попросил сверить порядок. Я бы иначе слишком доверился надписи на коробке.","kind":"in"}]},{"when":{"tape_scope":"summary"},"lines":[{"who":"Архив","text":"Опись я составил, но сам звук пока никому не отдаю.","kind":"in"}]}]},{"id":"W07","title":"Среда, 12:17 — Один Валера и много Валер","chat":"Валерик","core":[{"who":"Валерик","text":"Добрый день. Меня сегодня два человека спросили, топил ли я кого-нибудь в Неве. Ты не знаешь, почему?","kind":"in"},{"who":"Валерик","text":"Есть какой-то Валера, о котором рассказывают весьма увлекательные вещи. Но у меня паспорт, другая биография и сегодня стоматолог.","kind":"in"},{"who":"Валерик","text":"Кто это распространяет? Только фамилии без источников не пиши, пожалуйста.","kind":"in"},{"who":"Валерик","text":"И да, мозг Андрея Коромысло я теперь обсуждать ни с кем не собираюсь. Мне одного такого дня хватило.","kind":"in"}],"choices":[{"id":"A","title":"Исправить ошибочное отождествление","echo":"Это другой Валера из чужой истории. Я скажу, что тебя с ним перепутали.","set":{"valera_mix":"correct"},"lines":[{"who":"Марат (версии)","kind":"forward","from":"Валерик","text":"Меня перепутали с другим Валерой. У меня другая биография, и из совпадения имён ничего не следует.","media":null},{"who":"Валерик","text":"Спасибо. Главное, чтобы теперь два разных человека не стали одним из-за лени чужого мозга.","kind":"in"}],"note":""},{"id":"B","title":"Отправить только информацию без имени","echo":"Не буду пересылать твоё сообщение. Могу объяснить, что совпадение имени ничего не доказывает.","set":{"valera_mix":"quiet"},"lines":[{"who":"Валерик","text":"Отлично. Уговор дороже любого опровержения.","kind":"in"}],"note":""},{"id":"C","title":"Спросить, не знает ли того Валеру","echo":"А того Валеру ты сам хоть раз встречал?","set":{"valera_mix":"ask"},"lines":[{"who":"Валерик","text":"Нет. И не обязан знакомиться со всеми, кого так зовут. Мне достаточно себя.","kind":"in"}],"note":""}],"variants":[{"when":{"killer_reply":"block"},"lines":[{"who":"Валерик","text":"И вообще, я хотел один спокойный день без людей, которые недавно убили знакомого. Не выходит.","kind":"in"}]}]},{"id":"W08","title":"Среда, 13:05 — Группа поддержки отсутствует","chat":"Лоси","core":[{"who":"Лоси","text":"Мне уже прислали «расследование» про каких-то людей с гантелью из две тысячи седьмого.","kind":"in"},{"who":"Лоси","text":"Типа там тоже знакомые и тоже неудачная встреча. Ну так у нас половина страны знакомые. Что, всех теперь склеивать?","kind":"in"},{"who":"Лоси","text":"Я посмотрел — там вообще другие имена. Это даже я вижу. А мне, между прочим, говорят, что я в лицах не разбираюсь.","kind":"in"},{"who":"Лоси","text":"Хочешь, я сам напишу районным, чтоб не выдумывали?","kind":"in"}],"choices":[{"id":"A","title":"Попросить не раздувать","echo":"Если напишешь, не называй новых людей и не выдумывай связи.","set":{"moose_public":"limits"},"lines":[{"who":"Лоси","text":"Да уж, начну с того, что я ни с какой плёнкой не знаком. Там мне, может, поверят.","kind":"in"}],"note":""},{"id":"B","title":"Отговорить от публикации","echo":"Лучше не делай публичного заявления. Оно ещё сильнее разнесёт историю.","set":{"moose_public":"private"},"lines":[{"who":"Лоси","text":"Ладно. Буду всем объяснять по одному. Сдохну раньше, чем закончу.","kind":"in"}],"note":""},{"id":"C","title":"Попросить короткое исправление","echo":"Напиши одно: запись не про твою историю. Больше ничего.","set":{"moose_public":"retract"},"lines":[{"who":"Марат (версии)","kind":"forward","from":"Лоси","text":"Старая запись с гантелью не имеет отношения к моей истории. Я тех людей не знаю.","media":null},{"who":"Лоси","text":"Отправил. Теперь можно о погоде?","kind":"in"}],"note":""}],"variants":[{"when":{"tape_to_marat":"qualified"},"lines":[{"who":"Лоси","text":"Марат мне уже даже уточнённую опись прислал. Он прочитал половину, как и положено специалисту.","kind":"in"}]},{"when":{"tape_to_marat":"none"},"lines":[{"who":"Лоси","text":"Самой записи я не видел. Но знаю, что обо мне там ничего нет. Удивительная уверенность, да?","kind":"in"}]}]},{"id":"W09","title":"Среда, 13:41 — У людей память","chat":"Марат (версии)","core":[{"who":"Марат (версии)","text":"Слушай, я уже три раза переписал сообщение про плёнку. Последняя версия даже скучная.","kind":"in"},{"who":"Марат (версии)","text":"Там люди с гантелью, здесь троих перепутали, где-то была драка за гаражами. Схожесть? Есть. Доказательство общей истории? Нет.","kind":"in"},{"who":"Марат (версии)","text":"Теперь мне пишут, что я всё скрываю. Ужас: я впервые не знаю, как развить теорию.","kind":"in"},{"who":"Марат (версии)","text":"Что делать с моим старым постом?","kind":"in"}],"choices":[{"id":"A","title":"Исправить его там же","echo":"Исправь публично и убери вывод об общей истории. Не удаляй объяснение.","set":{"rumor_wednesday":"correct"},"lines":[{"who":"Марат (версии)","text":"Сделал. Мне объяснили, что скучные факты — тоже заговор. Прекрасно.","kind":"in"}],"note":""},{"id":"B","title":"Удалить спорное сообщение","echo":"Если ты сам не уверен, убери исходный пост и объясни почему.","set":{"rumor_wednesday":"delete"},"lines":[{"who":"Марат (версии)","text":"Удалил и написал причину. В ответ прислали скриншот удалённого. Интернет прекрасен.","kind":"in"}],"note":""},{"id":"C","title":"Оставить с оговоркой","echo":"Можешь оставить как гипотезу, но прямо напиши, чего не знаешь.","set":{"rumor_wednesday":"hedge"},"lines":[{"who":"Марат (версии)","text":"Добавил оговорку. Кто-то спросил, зачем вообще писать, если не уверен. Хороший вопрос.","kind":"in"}],"note":""}],"variants":[{"when":{"valera_mix":"correct"},"lines":[{"who":"Марат (версии)","text":"От Валерика пришло сообщение. Он просит перестать делать из него валеру с Невы. И справедливо.","kind":"in"}]},{"when":{"tape_to_marat":"none"},"lines":[{"who":"Марат (версии)","text":"Никто не дал мне саму опись, так что я собирал смысл по слухам. Это обнаружилось только когда я перечитал свои сообщения.","kind":"in"}]},{"when":{"moose_public":"retract"},"lines":[{"who":"Марат (версии)","text":"И Лоси написал, что с этой записью не связан. Это, конечно, его слова, но лучше, чем моя фантазия.","kind":"in"}]}]},{"id":"W10","title":"Среда, 14:20 — Кому нужна запись","chat":"Архив","core":[{"who":"Архив","text":"Нашёл на кассете вторую наклейку под старой. Там ничего полезного — просто буква и след от клея.","kind":"in"},{"who":"Архив","text":"Проверяю ещё раз: в первом куске человек ещё строит планы, во втором другой голос уже пытается его остановить. Имена и предмет совпадают.","kind":"in"},{"who":"Архив","text":"Могу оставить цифровую копию в частном каталоге, а могу передать носитель Бармену. Третьего варианта, где всё знает полиция из будущего, нет.","kind":"in"},{"who":"Архив","text":"Как лучше поступить с копией?","kind":"in"}],"choices":[{"id":"A","title":"Оставить закрытой","echo":"Сохрани, но пока не публикуй. Подпиши, что личности и судьба свидетеля неизвестны.","set":{"tape_archive":"private"},"lines":[{"who":"Архив","text":"Так и сделаю. В каталоге будет описание, не сенсация.","kind":"in"}],"note":""},{"id":"B","title":"Вернуть носитель владельцу","echo":"Бармену и верни. Ты техническую работу выполнил.","set":{"tape_archive":"return"},"lines":[{"who":"Архив","text":"Вернул. Оставил у себя только опись и сведения о качестве звука.","kind":"in"}],"note":""},{"id":"C","title":"Сделать историческую карточку","echo":"Опубликуй лишь факт наличия двух фрагментов, без имён и аудио.","set":{"tape_archive":"public_meta"},"lines":[{"who":"Архив","text":"Подготовлю нейтральную карточку: два фрагмента, без звуковых файлов. Это ещё не свидетельские показания.","kind":"in"}],"note":""}],"variants":[{"when":{"archive_intro":"source"},"lines":[{"who":"Архив","text":"Происхождение выяснить не удалось. Коробку до появления у Бармена никто не зарегистрировал.","kind":"in"}]}]},{"id":"W11","title":"Среда, 15:07 — Пятый свидетель","chat":"Бармен","core":[{"who":"Бармен","text":"Из-за этой коробки у меня сегодня пятеро людей спрашивали, можно ли послушать старую запись.","kind":"in"},{"who":"Бармен","text":"Один предложил принести проектор. Второй — провести платный вечер. Третий — позвать эксперта из телевизора. Я ему говорю: эксперту сперва нужно заказать столик.","kind":"in"},{"who":"Бармен","text":"Я бармен. Моя задача — знать, у кого закончился чай. А не у кого закончилась биография.","kind":"in"},{"who":"Бармен","text":"Что им всем сказать?","kind":"in"}],"choices":[{"id":"A","title":"Не устраивать прослушивание","echo":"Никакого вечера. Просто верни чужие вещи, если выяснишь, чьи они.","set":{"bar_archive":"no"},"lines":[{"who":"Бармен","text":"Договорились. Проектор они теперь пусть несут на день рождения.","kind":"in"}],"note":""},{"id":"B","title":"Пусть спрашивают у Архива","echo":"Скажи: есть опись, а подробности у человека, который её сделал.","set":{"bar_archive":"referral"},"lines":[{"who":"Архив","kind":"forward","from":"Бармен","text":"Владельца записи не установили, личности участников неизвестны. Публичного прослушивания не будет.","media":null},{"who":"Бармен","text":"Переслал. Теперь у него звонит телефон, а у меня наливается чай. Все при своём.","kind":"in"}],"note":""},{"id":"C","title":"Только нейтральная информация","echo":"Объясни, что год на коробке и история на записи — разные вещи.","set":{"bar_archive":"explain"},"lines":[{"who":"Бармен","text":"Объяснил. Люди обиделись на хронологию. Бывает.","kind":"in"}],"note":""}],"variants":[{"when":{"bar_garage":"refuse"},"lines":[{"who":"Бармен","text":"Помнишь, мне вчера хотели собрать очевидцев драки? Сегодня хотят собирать очевидцев кассеты. Я не концертный зал.","kind":"in"}]}]},{"id":"W12","title":"Среда, 16:04 — Совпадение не знакомство","chat":"Старый","core":[{"who":"Старый","text":"Вот за что люблю ваши чаты. Стоило найти плёнку, как моя куртка опять стала предметом интереса. Говорят, её могли видеть люди из записи.","kind":"in"},{"who":"Старый","text":"А запись с пометкой 2007. Куртка у меня с 1994-го. Это всё, что у нас совпадает с реальностью: числа существуют.","kind":"in"},{"who":"Старый","text":"Вчера Лёха, который с деревней, жаловался, что люди обсуждают его дом без него. Сегодня, видимо, мой черёд.","kind":"in"},{"who":"Старый","text":"Будешь районным отвечать?","kind":"in"}],"choices":[{"id":"A","title":"Попросить не склеивать эпохи","echo":"Скажу, что доказательств связи куртки и записи нет.","set":{"old_public":"correct"},"lines":[{"who":"Марат (версии)","kind":"forward","from":"Старый","text":"Моя куртка 1994 года не доказывает ничего о записи с пометкой «2007». Я участников не знаю.","media":null},{"who":"Старый","text":"Спасибо. Больше всего мне нравится отсутствие новых версий.","kind":"in"}],"note":""},{"id":"B","title":"Не делать публикацию","echo":"Не надо. Пусть перестанут кормиться твоей историей.","set":{"old_public":"quiet"},"lines":[{"who":"Старый","text":"Хорошо. Куртка в шкафу. Шкаф пока без комментариев.","kind":"in"}],"note":""},{"id":"C","title":"Предложить короткое личное уточнение","echo":"Ответим только тем, кто спрашивал тебя напрямую.","set":{"old_public":"private"},"lines":[{"who":"Старый","text":"Так и сделал. Двое извинились, третий предложил купить куртку. Не продам.","kind":"in"}],"note":""}],"variants":[{"when":{"village_trip":"together"},"lines":[{"who":"Старый","text":"К Лёхе завтра всё-таки зайду. Не за уликами, просто человека проведать.","kind":"in"}]},{"when":{"village_plan":"city"},"lines":[{"who":"Старый","text":"Лёха дома полку прикрутил. Мне теперь каждый день фотографию этой полки шлёт. Лучше, чем фотографии сарая.","kind":"in"}]}]},{"id":"W13","title":"Среда, 17:11 — Трое с одного адреса","chat":"Лоси","core":[{"who":"Лоси","text":"Мне сегодня принесли ещё одну фотографию. Подписали: «Вот же ваши трое». Я посмотрел: опять не те.","kind":"in"},{"who":"Лоси","text":"Я не собираюсь ничего выяснять через тебя. Но мне, блядь, уже страшно отвечать на вопросы про чужие лица.","kind":"in"},{"who":"Лоси","text":"У меня столько старых знакомых, что каждый второй считает себя очевидцем. А потом «нет, я не видел, мне рассказали».","kind":"in"},{"who":"Лоси","text":"Что с этой фоткой делать?","kind":"in"}],"choices":[{"id":"A","title":"Не пересылать дальше","echo":"Ничего не публикуй и не пересылай. У тебя уже была ошибка с людьми.","set":{"moose_photo":"stop"},"lines":[{"who":"Лоси","text":"Да понял. Удалю из пересылок. У себя оставлю, если спросят, откуда она взялась.","kind":"in"}],"note":""},{"id":"B","title":"Спросить у источника","echo":"Уточни, кто сделал снимок. Не называй людей на нём.","set":{"moose_photo":"source"},"lines":[{"who":"Лоси","text":"Источник сказал: «Из интернета». Охуительный свидетель. Прямо диплом выдавать.","kind":"in"}],"note":""},{"id":"C","title":"Оставить решение ему","echo":"Свою историю ты сам знаешь. Не делай посторонних следующими жертвами догадок.","set":{"moose_photo":"warning"},"lines":[{"who":"Лоси","text":"Оставлю. Мне до конца жизни хватит тех, кого я однажды перепутал.","kind":"in"}],"note":""}],"variants":[{"when":{"moose_attitude":"responsibility"},"lines":[{"who":"Лоси","text":"Ты меня утром одёрнул, и не зря. Не во всём, но тут я ошибку не оспариваю.","kind":"in"}]},{"when":{"moose_public":"retract"},"lines":[{"who":"Лоси","text":"С твоим коротким исправлением хоть перестали приписывать мне гантелю.","kind":"in"}]}]},{"id":"W14","title":"Среда, 18:02 — Гаражи опять виноваты","chat":"Гаражи","core":[{"who":"Гаражи","text":"Сегодня отличные новости. Ко мне пришли не с вопросом про Васюню, а с просьбой подтвердить события 2007 года.","kind":"in"},{"who":"Гаражи","text":"Я тогда в другом городе жил. Но это никого не интересует. Человек увидел слово «драка» и решил, что дальше можно не читать.","kind":"in"},{"who":"Гаражи","text":"Я сказал, что не был там и записи не слышал. Он обиделся. Как будто я обязан был присутствовать.","kind":"in"},{"who":"Гаражи","text":"Хочу ему ответить последний раз. Что лучше?","kind":"in"}],"choices":[{"id":"A","title":"Коротко обозначить факты","echo":"Так и скажи: тебя там не было. Точка.","set":{"garage_wed":"facts"},"lines":[{"who":"Гаражи","text":"Написал. Он спросил, почему я скрываю правду. Поставлю телефон на зарядку — пусть придумает без меня.","kind":"in"}],"note":""},{"id":"B","title":"Переслать публичное исправление","echo":"Если Марат уже исправил публикацию, можно дать ссылку на исправление.","set":{"garage_wed":"retract"},"lines":[{"who":"Марат (версии)","kind":"forward","from":"Гаражи","text":"У истории с гаражами нет подтверждённой связи с записью 2007 года.","media":null},{"who":"Гаражи","text":"Переслал. Никогда не думал, что буду пересылать опровержения как открытки.","kind":"in"}],"note":""},{"id":"C","title":"Закончить разговор","echo":"Не отвечай. Ничего не обязан доказывать незнакомцам.","set":{"garage_wed":"ignore"},"lines":[{"who":"Гаражи","text":"Закончил. Мне теперь ещё в магазин за хлебом идти. Это реальное дело.","kind":"in"}],"note":""}],"variants":[{"when":{"garage_help":"medical","garage_statement":"truth"},"lines":[{"who":"Гаражи","text":"По Васюне у меня хотя бы одно подтверждение было. Здесь ни одного.","kind":"in"}]},{"when":{"rumor_wednesday":"correct"},"lines":[{"who":"Гаражи","text":"Марат своё исправление выложил. Может, когда-нибудь люди научатся читать и его.","kind":"in"}]}]},{"id":"W15","title":"Среда, 19:09 — Что делать с именами","chat":"Архив","core":[{"who":"Архив","text":"Ещё раз пересмотрел оба фрагмента. Там действительно есть именованные люди. Но имена на записи не заменяют установление личности.","kind":"in"},{"who":"Архив","text":"Именные карточки создавать не буду. Для каталога это записи о событиях, а не список подозреваемых.","kind":"in"},{"who":"Архив","text":"Меня больше всего спрашивают, выжил ли человек, который говорит во втором фрагменте.","kind":"in"},{"who":"Архив","text":"Я не знаю. На записи финал неопределённый.","kind":"in"},{"who":"Архив","text":"Как это написать, чтобы людям не показалось, что я недосказал правду?","kind":"in"}],"choices":[{"id":"A","title":"Признать неопределённость","echo":"Прямо: дальнейшая судьба свидетеля неизвестна. Всё.","set":{"witness_note":"unknown"},"lines":[{"who":"Архив","text":"Так и будет. Неведение — это не пробел, который обязаны зашпаклевать.","kind":"in"}],"note":""},{"id":"B","title":"Сохранить оба варианта","echo":"Запиши: мог выжить, мог погибнуть. Ни один вариант запись не подтверждает.","set":{"witness_note":"alternatives"},"lines":[{"who":"Архив","text":"Добавлю помету об ограничениях расшифровки. Никакого нового человека в конце записи не изобретаем.","kind":"in"}],"note":""},{"id":"C","title":"Не писать о судьбе","echo":"Оставь вопрос открытым. Это опись носителя, не биография.","set":{"witness_note":"skip"},"lines":[{"who":"Архив","text":"Верно. Я и так слишком много объясняю про то, чего не знаю.","kind":"in"}],"note":""}],"variants":[{"when":{"tape_archive":"private"},"lines":[{"who":"Архив","text":"Частная копия подписана. Доступ никто не запрашивал через меня напрямую.","kind":"in"}]},{"when":{"tape_archive":"return"},"lines":[{"who":"Архив","text":"Оригинальный носитель я вернул Бармену. В карточке остались только технические заметки.","kind":"in"}]}]},{"id":"W16","title":"Среда, 20:13 — Не путайте с протоколом","chat":"Марат (версии)","core":[{"who":"Марат (версии)","text":"Сегодня мне уже неинтересно строить теории. Мне интересно, сколько людей читают слово «предположительно» и слышат «точно».","kind":"in"},{"who":"Марат (версии)","text":"Вчера один мужик был связан с гаражами, сегодня он уже фигурирует на кассете из 2007-го. Завтра ему припишут смерть Наполеона.","kind":"in"},{"who":"Марат (версии)","text":"Я нашёл старый свой пост, где написал, что Валерик — тот самый Валера с Невы. Оказывается, я его даже не спросил.","kind":"in"},{"who":"Марат (версии)","text":"Писать отдельное исправление или уже поздно?","kind":"in"}],"choices":[{"id":"A","title":"Исправить с источниками","echo":"Исправь и укажи: одно имя, две истории, доказательств тождества нет.","set":{"mara_wed_final":"fact"},"lines":[{"who":"Марат (версии)","text":"Сделал. Мне написали, что я стал скучным. Если это цена ясности — дорого, но терпимо.","kind":"in"}],"note":""},{"id":"B","title":"Написать ему лично","echo":"Начни с того, кому навредил. Не делай из исправления очередное шоу.","set":{"mara_wed_final":"private"},"lines":[{"who":"Марат (версии)","text":"Написал Валерику. Он ответил: «Не мешайте мне жить». Кратко и справедливо.","kind":"in"}],"note":""},{"id":"C","title":"Предложить удалить только ложный вывод","echo":"Убери именно вывод, а факты о старом эпизоде оставь отдельно.","set":{"mara_wed_final":"remove"},"lines":[{"who":"Марат (версии)","text":"Убрал утверждение. Комментарии, конечно, остались. И это уже не исправить одной кнопкой.","kind":"in"}],"note":""}],"variants":[{"when":{"valera_mix":"correct","rumor_wednesday":"correct"},"lines":[{"who":"Марат (версии)","text":"Кстати, уже два человека переслали моё исправление вместо первоначального поста. Не думал, что это возможно.","kind":"in"}]},{"when":{"rumor_wednesday":"hedge","moose_public":"limits"},"lines":[{"who":"Марат (версии)","text":"Пока старый пост висел с догадкой, его успели скопировать без оговорок. Сам виноват.","kind":"in"}]}]},{"id":"W17","title":"Среда, 21:07 — Нормальный чайник","chat":"Серёга","core":[{"who":"Серёга","text":"Здоров. Все сегодня обсуждают какие-то кассеты. Я им говорю: у меня в жизни хватило одной находки, спасибо.","kind":"in"},{"who":"Серёга","text":"Старый чайник всё-таки починил. Сейчас думаю, зачем два дня грел воду в кастрюле.","kind":"in"},{"who":"Серёга","text":"А кто-то написал, что плёнка связана с моей кухней. Ну просто потому что там и там что-то страшное.","kind":"in"},{"who":"Серёга","text":"Может, они ещё погоде подозрения предъявят. Как считаешь, надо отвечать?","kind":"in"}],"choices":[{"id":"A","title":"Не подпитывать слух","echo":"Нет. Между твоей кухней и кассетой нет никакой установленной связи.","set":{"sergey_wed":"ignore"},"lines":[{"who":"Серёга","text":"Вот. У меня уже шесть кружек помыты, а люди всё только начинают выдвигать версии.","kind":"in"}],"note":""},{"id":"B","title":"Ответить только о себе","echo":"Если хочется, скажи, что с твоей историей происходит на самом деле.","set":{"sergey_wed":"plain"},"lines":[{"who":"Серёга","text":"Напишу, что чайник работает. Это сегодня единственная подтверждённая хорошая новость.","kind":"in"}],"note":""},{"id":"C","title":"Предложить закрыть тему","echo":"Ты не обязан разговаривать о находке каждый день.","set":{"sergey_wed":"boundary"},"lines":[{"who":"Серёга","text":"Да. Тем более вчера я приготовил котлеты, и никто даже не спросил, вкусные ли.","kind":"in"}],"note":""}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Про находку тем, кому положено, я уже сказал. Они разберутся. Мне теперь кастрюлю отмыть бы.","kind":"in"}]},{"when":{"head_first":"photo"},"lines":[{"who":"Серёга","text":"Фотография из моего телефона не обязана объяснять вообще всё на свете.","kind":"in"}]}]},{"id":"W18","title":"Среда, 22:38 — Третья ошибка","chat":"Лоси","core":[{"who":"Лоси","text":"Я тут сел и перечитал переписку. Никогда не думал, что стану это делать добровольно.","kind":"in"},{"who":"Лоси","text":"Троих тогда перепутал. Теперь люди путают меня с чужой записью. Получается, ошибка — тоже заразная штука.","kind":"in"},{"who":"Лоси","text":"Валера мне не ответил. Костик тоже. Аирапет, наверное, уже спит. Это не значит, что я что-то понял.","kind":"in"},{"who":"Лоси","text":"Мне ещё одну фотографию прислали. На превью три человека у белой машины. Открывать не хочу. С таким я уже один раз отлично разобрался.","kind":"in"},{"who":"Лоси","text":"Ладно. Последний вопрос на сегодня: оставить её закрытой или опять пытаться узнать, кто там?","kind":"in"}],"choices":[{"id":"A","title":"Оставить закрытой","echo":"Не открывай. Особенно если собираешься снова судить по лицам.","set":{"wednesday_end":"closed"},"lines":[{"who":"Лоси","text":"Закрыл. Удивительно. Ничего не случилось за те три секунды, пока я не открывал.","kind":"in"}],"note":""},{"id":"B","title":"Вернуться к проверяемому","echo":"Сначала выясни, кто прислал и почему. Не делай из снимка новую цель.","set":{"wednesday_end":"verify"},"lines":[{"who":"Лоси","text":"Спросил. Ответ: «Да это мем». Вот тебе и фотография. Хорошо, что не поехал проверять адрес.","kind":"in"}],"note":""},{"id":"C","title":"Закончить беседу","echo":"Я за тебя не решу. Но к разговору о тех троих мы ещё вернёмся.","set":{"wednesday_end":"boundary"},"lines":[{"who":"Лоси","text":"Понял. Это ты мне красиво сказал «отъебись». Ладно, до связи.","kind":"in"}],"note":""}],"variants":[{"when":{"rumor_wednesday":"correct","mara_wed_final":"fact"},"lines":[{"who":"Лоси","text":"Кстати, мой номер перестали присылать незнакомым людям. Какой-то Марат написал опровержение с источниками. Неожиданная польза от интернета.","kind":"in"}]},{"when":{"rumor_wednesday":"hedge","moose_photo":"source"},"lines":[{"who":"Лоси","text":"В районе теперь три человека спорят о той фотографии. А снял её, оказывается, школьник для объявления о продаже машины. Вот им и расследование.","kind":"in"}]},{"when":{"tape_archive":"public_meta","bar_archive":"explain"},"lines":[{"who":"Лоси","text":"Архивщик выложил карточку про две части старой записи. Народ требует третью. Почему третью? Потому что серий должно быть три.","kind":"in"}]},{"when":{"moose_attitude":"distance","rumor_wednesday":"hedge"},"lines":[{"who":"Лоси","text":"Я сначала не хотел в это лезть. А потом всё равно пришлось объяснять четырём посторонним, что я не герой их старой записи.","kind":"in"}]},{"when":{"rumor_wednesday":"hedge","tape_to_marat":"qualified"},"lines":[{"who":"Лоси","text":"Запись, конечно, до сих пор обсуждают рядом с моим именем. Но теперь хотя бы пишут «вероятно». Смешно, если подумать.","kind":"in"}]},{"when":{"valera_mix":"correct"},"lines":[{"who":"Лоси","text":"И тот самый Валерик из переписок сегодня велел всем не звать его моим знакомым. И правильно.","kind":"in"}]},{"when":{"moose_photo":"stop","moose_public":"private"},"lines":[{"who":"Лоси","text":"А старую фотку я так никому и не переслал. Тот, кто её прислал, уже три раза спросил, почему. Даже не отвечаю.","kind":"in"}]},{"when":{"sergey_wed":"boundary"},"lines":[{"who":"Лоси","text":"Слышал, у одного мужика на кухне вообще другой случай. Не буду спрашивать какой. Поужинать спокойно охота.","kind":"in"}]}]}]};
